#[cfg(windows)]
const VIDEO_AUDIO_EXIT_DIAGNOSTIC_MIN_INTERVAL: std::time::Duration =
    std::time::Duration::from_secs(1);

#[cfg(windows)]
#[derive(Clone, Debug)]
struct VideoAudioExitKeyDiagnosticInputs {
    fs_idx: usize,
    pass: u64,
    video_audio_mode: Option<usize>,
    action_peek: bool,
    z_press: DiagnosticChordPressSnapshot,
    fullscreen_summary: Option<String>,
}

#[cfg(windows)]
impl VideoAudioExitKeyDiagnosticInputs {
    fn fullscreen_summary_saw_z_down(&self) -> bool {
        self.fullscreen_summary
            .as_deref()
            .is_some_and(|summary| fullscreen_summary_saw_key_down(summary, "Z"))
    }

    fn saw_z_or_action_press(&self) -> bool {
        self.action_peek
            || self.z_press.win32_viewport_key_down
            || self.z_press.win32_any_key_down_source.is_some()
            || self.z_press.egui_key_down
            || self.fullscreen_summary_saw_z_down()
    }
}

#[cfg(windows)]
#[derive(Clone, Debug)]
struct VideoAudioExitKeyDiagnosticRecord {
    inputs: VideoAudioExitKeyDiagnosticInputs,
    outcome: VideoAudioExitKeyOutcome,
}

#[cfg(windows)]
#[derive(Clone, Debug, Default)]
struct VideoAudioExitKeyDiagnosticRateState {
    last_observed_outcome: Option<VideoAudioExitKeyOutcome>,
    last_observed_target: Option<(usize, Option<usize>)>,
    last_emitted_at: Option<std::time::Instant>,
    pending: Option<VideoAudioExitKeyDiagnosticRecord>,
}

#[cfg(windows)]
impl VideoAudioExitKeyDiagnosticRateState {
    fn reset_session(&mut self) {
        self.last_observed_outcome = None;
        self.last_observed_target = None;
        self.pending = None;
    }

    fn observe(
        &mut self,
        now: std::time::Instant,
        record: VideoAudioExitKeyDiagnosticRecord,
    ) -> Option<VideoAudioExitKeyDiagnosticRecord> {
        let outcome_changed = self.last_observed_outcome != Some(record.outcome);
        let target = (record.inputs.fs_idx, record.inputs.video_audio_mode);
        let target_changed = self.last_observed_target != Some(target);
        self.last_observed_outcome = Some(record.outcome);
        self.last_observed_target = Some(target);

        // A diagnostic must not make eligibility depend only on the probes whose failure it is
        // investigating. That already made this path silent twice: first when every record was
        // gated by action_peek, then when these four Z probes alone selected candidates. The
        // independently produced fullscreen summary is also a candidate source, and the timed
        // emission below is an unconditional heartbeat while audio mode keeps calling observe.
        if outcome_changed || target_changed || record.inputs.saw_z_or_action_press() {
            let replace_pending = self.pending.as_ref().is_none_or(|pending| {
                !pending.inputs.saw_z_or_action_press() && record.inputs.saw_z_or_action_press()
            });
            if replace_pending {
                self.pending = Some(record.clone());
            }
        }

        let interval_elapsed = self.last_emitted_at.is_none_or(|last_emitted| {
            now.saturating_duration_since(last_emitted) >= VIDEO_AUDIO_EXIT_DIAGNOSTIC_MIN_INTERVAL
        });
        if interval_elapsed {
            let ready = self.pending.take().unwrap_or(record);
            self.last_emitted_at = Some(now);
            Some(ready)
        } else {
            None
        }
    }
}

#[cfg(windows)]
static VIDEO_AUDIO_EXIT_DIAGNOSTIC_RATE_STATE: std::sync::OnceLock<
    std::sync::Mutex<VideoAudioExitKeyDiagnosticRateState>,
> = std::sync::OnceLock::new();

#[cfg(windows)]
pub(crate) fn reset_video_audio_exit_key_diagnostic_rate() {
    if let Ok(mut state) = VIDEO_AUDIO_EXIT_DIAGNOSTIC_RATE_STATE
        .get_or_init(Default::default)
        .lock()
    {
        state.reset_session();
    }
}

#[cfg(windows)]
fn log_video_audio_exit_key_outcome(
    inputs: &VideoAudioExitKeyDiagnosticInputs,
    outcome: VideoAudioExitKeyOutcome,
) {
    let record = VideoAudioExitKeyDiagnosticRecord {
        inputs: inputs.clone(),
        outcome,
    };
    let ready = VIDEO_AUDIO_EXIT_DIAGNOSTIC_RATE_STATE
        .get_or_init(Default::default)
        .lock()
        .ok()
        .and_then(|mut state| state.observe(std::time::Instant::now(), record));
    let Some(record) = ready else {
        return;
    };
    let inputs = record.inputs;
    let z = inputs.z_press;
    crate::logger::log(format!(
        "[video-audio] exit key diagnostic fs_idx={} viewport={:?} pass={} \
         video_audio_mode={:?} outcome={} peek_action={} peek_z_chord={} \
         frame_active={} frame_had_key_down={} pressed_key_down_viewport_z={} \
         pressed_key_down_viewport_z_chord={} any_viewport_z_down={} \
         any_viewport_z_source={:?} egui_z_pressed={} egui_z_chord_pressed={} \
         egui_fallback_allowed={} frame_active_blocks_egui_fallback={} \
         fs_summary_source=egui_events fs_summary={:?}",
        inputs.fs_idx,
        z.viewport,
        inputs.pass,
        inputs.video_audio_mode,
        record.outcome.as_str(),
        inputs.action_peek,
        z.result,
        z.frame_active,
        z.frame_had_key_down,
        z.win32_viewport_key_down,
        z.win32_viewport_chord_down,
        z.win32_any_key_down_source.is_some(),
        z.win32_any_key_down_source,
        z.egui_key_down,
        z.egui_chord_down,
        z.egui_fallback_allowed,
        z.frame_active_blocks_egui_fallback,
        inputs.fullscreen_summary
    ));
}

/// Cross-frame owner for primary-pointer suppression in fullscreen.
///
/// Touch replacement on a terminal TouchFrame is deliberately not stored:
/// it suppresses that pass only. Persisting it would require a future primary
/// release even though the touch owner has already observed the stream end.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub(crate) enum FullscreenPrimarySuppression {
    #[default]
    Idle,
    PointerStream,
    TouchStream,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum FullscreenPrimarySuppressionEvent {
    PointerStreamStarted,
    PointerFrame {
        released: bool,
    },
    TouchFrame {
        suppresses_current_frame: bool,
        active: bool,
        completed: bool,
        cancelled: bool,
    },
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum FullscreenPrimarySuppressionDecision {
    Preserve,
    Allow,
    Suppress,
}

impl FullscreenPrimarySuppressionDecision {
    fn overridden_by(self, next: Self) -> Self {
        match next {
            Self::Preserve => self,
            Self::Allow | Self::Suppress => next,
        }
    }

    fn suppresses_current_frame(self) -> bool {
        self == Self::Suppress
    }
}

impl FullscreenPrimarySuppression {
    pub(crate) fn is_active(self) -> bool {
        self != Self::Idle
    }

    pub(crate) fn arm_pointer_stream(&mut self) {
        let _ = self.apply(FullscreenPrimarySuppressionEvent::PointerStreamStarted);
    }

    fn apply(
        &mut self,
        event: FullscreenPrimarySuppressionEvent,
    ) -> FullscreenPrimarySuppressionDecision {
        match event {
            FullscreenPrimarySuppressionEvent::PointerStreamStarted => {
                *self = Self::PointerStream;
                FullscreenPrimarySuppressionDecision::Suppress
            }
            FullscreenPrimarySuppressionEvent::PointerFrame { released } => {
                let decision = if self.is_active() {
                    FullscreenPrimarySuppressionDecision::Suppress
                } else {
                    FullscreenPrimarySuppressionDecision::Allow
                };
                if released && *self == Self::PointerStream {
                    *self = Self::Idle;
                }
                decision
            }
            FullscreenPrimarySuppressionEvent::TouchFrame {
                suppresses_current_frame,
                active,
                completed,
                cancelled,
            } => {
                // PointerStream is provisional until raw-touch correlation has
                // identified the source. From that point the touch frame is
                // authoritative for this pass: canvas gestures are allowed,
                // while correlated replacement/control responses stay
                // suppressed by `suppresses_current_frame`.
                let decision = if active || completed || cancelled || suppresses_current_frame {
                    if suppresses_current_frame {
                        FullscreenPrimarySuppressionDecision::Suppress
                    } else {
                        FullscreenPrimarySuppressionDecision::Allow
                    }
                } else {
                    FullscreenPrimarySuppressionDecision::Preserve
                };
                if cancelled || completed {
                    *self = Self::Idle;
                } else if active && (*self == Self::PointerStream || suppresses_current_frame) {
                    // A positively correlated touch stream owns the same
                    // promoted primary pointer, including a focus-reclaim
                    // canvas gesture.
                    *self = Self::TouchStream;
                } else if *self == Self::TouchStream && !active {
                    *self = Self::Idle;
                }
                decision
            }
        }
    }
}

