    crate::compare_wgpu::CompareShaderSlot::Main;
const COMPARE_NAVIGATOR_SHADER_SLOT: crate::compare_wgpu::CompareShaderSlot =
    crate::compare_wgpu::CompareShaderSlot::Navigator;

/// Full-image resources actually drawn by the page path for this frame.
///
/// This map serves both the navigator and the presentation trace seam. Missing navigator entries
/// deliberately fall back to the catalog thumbnail, while missing trace entries mean that page
/// was not reported as presented.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum FsDisplayUnitPageProvenance {
    Live,
    Holdover,
}

struct FsNavigatorTextureSource {
    idx: usize,
    resource: FullscreenPaintResource,
    provenance: FsDisplayUnitPageProvenance,
}

#[derive(Default)]
struct FsNavigatorTextureSources {
    pages: Vec<FsNavigatorTextureSource>,
}

#[derive(Clone, Copy)]
enum FsPageLayoutSource {
    CurrentItem,
    Captured {
        layout_size: egui::Vec2,
        post_filter: crate::adjustment::PostFilter,
    },
}

impl FsNavigatorTextureSources {
    fn single(page_idx: usize, texture: Option<FullscreenPaintResource>) -> Self {
        Self {
            pages: texture
                .into_iter()
                .map(|resource| FsNavigatorTextureSource {
                    idx: page_idx,
                    resource,
                    provenance: FsDisplayUnitPageProvenance::Live,
                })
                .collect(),
        }
    }

    fn spread(
        left_idx: usize,
        left: Option<FullscreenPaintResource>,
        right_idx: usize,
        right: Option<FullscreenPaintResource>,
    ) -> Self {
        let mut pages = Vec::with_capacity(2);
        if let Some(resource) = left {
            pages.push(FsNavigatorTextureSource {
                idx: left_idx,
                resource,
                provenance: FsDisplayUnitPageProvenance::Live,
            });
        }
        if let Some(resource) = right {
            pages.push(FsNavigatorTextureSource {
                idx: right_idx,
                resource,
                provenance: FsDisplayUnitPageProvenance::Live,
            });
        }
        Self { pages }
    }

    /// A display-unit holdover is painted after the live pages, so its resources must replace
    /// the live map as a unit even when the capture-time idx equals the new page idx.
    fn replace_with_display_unit(&mut self, unit: &FsDisplayUnitHoldover) {
        self.pages = unit
            .pages
            .iter()
            .map(|page| FsNavigatorTextureSource {
                idx: page.idx,
                resource: page.texture.clone(),
                provenance: FsDisplayUnitPageProvenance::Holdover,
            })
            .collect();
    }

    fn texture_for_page<'a>(
        &'a self,
        page_idx: usize,
        thumbnail: Option<&'a egui::TextureHandle>,
    ) -> Option<&'a egui::TextureHandle> {
        self.pages
            .iter()
            .find(|source| source.idx == page_idx)
            .map(|source| source.resource.source_texture())
            .or(thumbnail)
    }
}

#[derive(Clone)]
struct PanoramaNavigatorLayout {
    panel_rect: egui::Rect,
    header_rect: egui::Rect,
    canvas_rect: egui::Rect,
    content_rect: egui::Rect,
    outline_segments: Vec<Vec<egui::Pos2>>,
}

impl FlatNavigatorLayout {
    fn page_at(&self, pos: egui::Pos2) -> Option<FlatNavigatorPage> {
        self.pages
            .iter()
            .copied()
            .find(|page| page.navigator.contains_screen(pos))
    }

    fn nearest_page_at(&self, pos: egui::Pos2) -> Option<(FlatNavigatorPage, egui::Pos2)> {
        self.page_at(pos).map(|page| (page, pos)).or_else(|| {
            self.pages
                .iter()
                .copied()
                .map(|page| {
                    let clamped =
                        pos.clamp(page.navigator.paint_rect.min, page.navigator.paint_rect.max);
                    (page, clamped, clamped.distance_sq(pos))
                })
                .min_by(|a, b| a.2.total_cmp(&b.2))
                .map(|(page, clamped, _)| (page, clamped))
        })
    }
}

