#[derive(Debug, Clone, Copy)]
struct LoupeSampleMapping {
    uv_rect: egui::Rect,
    image_rect: egui::Rect,
}

fn loupe_sample_mapping(
    uv_center: egui::Vec2,
    half_uv: egui::Vec2,
    loupe_rect: egui::Rect,
) -> LoupeSampleMapping {
    debug_assert!(half_uv.x > 0.0 && half_uv.y > 0.0);
    let desired_min = uv_center - half_uv;
    let desired_max = uv_center + half_uv;
    let uv_min = egui::pos2(desired_min.x.clamp(0.0, 1.0), desired_min.y.clamp(0.0, 1.0));
    let uv_max = egui::pos2(desired_max.x.clamp(0.0, 1.0), desired_max.y.clamp(0.0, 1.0));
    let desired_size = desired_max - desired_min;
    let image_min_fraction = egui::vec2(
        (uv_min.x - desired_min.x) / desired_size.x,
        (uv_min.y - desired_min.y) / desired_size.y,
    );
    let image_max_fraction = egui::vec2(
        (uv_max.x - desired_min.x) / desired_size.x,
        (uv_max.y - desired_min.y) / desired_size.y,
    );
    let image_min = loupe_rect.min + image_min_fraction * loupe_rect.size();
    let image_max = loupe_rect.min + image_max_fraction * loupe_rect.size();
    LoupeSampleMapping {
        uv_rect: egui::Rect::from_min_max(uv_min, uv_max),
        image_rect: egui::Rect::from_min_max(image_min, image_max),
    }
}

fn window_geometry_pos_to_viewport(pos: egui::Pos2, ui_scale: f32) -> egui::Pos2 {
    egui::pos2(
        crate::settings::window_geometry_to_viewport_points(pos.x, ui_scale),
        crate::settings::window_geometry_to_viewport_points(pos.y, ui_scale),
    )
}

fn window_geometry_size_to_viewport(size: egui::Vec2, ui_scale: f32) -> egui::Vec2 {
    egui::vec2(
        crate::settings::window_geometry_to_viewport_points(size.x, ui_scale),
        crate::settings::window_geometry_to_viewport_points(size.y, ui_scale),
    )
}

/// 全画面 viewport の位置とサイズを決める。
///
/// `window_rect` は**いまウィンドウが居る矩形**で、最大化中も値が入っている
/// (`App::last_window_rect`)。復元先の `last_outer_rect` を渡すと、最大化で起動して
/// 一度も戻していない間 `None` になり、最後の分岐へ落ちて画面の左上へ小さく出る
/// (2026-09-02 利用者報告)。
///
/// `monitor_at` はモニター矩形の解決 (物理ピクセル座標 → 論理矩形)。テストから
/// 差し替えられるように引数で受ける。
fn fullscreen_viewport_geometry(
    window_rect: Option<egui::Rect>,
    pixels_per_point: f32,
    ui_scale: f32,
    monitor_at: impl Fn(f32, f32) -> Option<egui::Rect>,
) -> (egui::Pos2, egui::Vec2) {
    let monitor_rect = window_rect
        .map(|r| r.center())
        .and_then(|c| monitor_at(c.x * pixels_per_point, c.y * pixels_per_point))
        // 現在位置が分からないときでも全画面にはする。原点はどのモニターにも
        // 属さないことがあるが、解決は MONITOR_DEFAULTTONEAREST なので必ず
        // どこかのモニターが返る。固定の 1280x720 は画面の一部しか覆わない。
        .or_else(|| monitor_at(0.0, 0.0));

    if let Some(rect) = monitor_rect {
        return (
            window_geometry_pos_to_viewport(rect.min, ui_scale),
            window_geometry_size_to_viewport(rect.size(), ui_scale),
        );
    }
    if let Some(rect) = window_rect {
        // `window_rect` は現在の viewport points で報告されているので変換しない。
        return (rect.min, rect.size());
    }
    (
        window_geometry_pos_to_viewport(egui::pos2(0.0, 0.0), ui_scale),
        window_geometry_size_to_viewport(egui::vec2(1280.0, 720.0), ui_scale),
    )
}

#[cfg(windows)]
fn viewport_rect_to_window_geometry(rect: egui::Rect, ui_scale: f32) -> egui::Rect {
    egui::Rect::from_min_max(
        egui::pos2(
            crate::settings::viewport_points_to_window_geometry(rect.min.x, ui_scale),
            crate::settings::viewport_points_to_window_geometry(rect.min.y, ui_scale),
        ),
        egui::pos2(
            crate::settings::viewport_points_to_window_geometry(rect.max.x, ui_scale),
            crate::settings::viewport_points_to_window_geometry(rect.max.y, ui_scale),
        ),
    )
}

#[cfg(windows)]
fn detached_placement_from_viewport_rects(
    mut placement: crate::settings::DetachedViewerWindowPlacement,
    outer_rect: egui::Rect,
    inner_rect: Option<egui::Rect>,
    maximized: bool,
    ui_scale: f32,
) -> crate::settings::DetachedViewerWindowPlacement {
    let outer = viewport_rect_to_window_geometry(outer_rect, ui_scale);
    let inner = inner_rect.map(|rect| viewport_rect_to_window_geometry(rect, ui_scale));
    placement.x = outer.min.x;
    placement.y = outer.min.y;
    if let Some(inner) = inner {
        placement.w = inner.width();
        placement.h = inner.height();
    } else {
        placement.w = outer.width();
        placement.h = outer.height();
    }
    placement.maximized = maximized;
    placement
}

