fn fs_overflow_panel_body_row_count(state: FsOverflowPanelState) -> usize {
    match state {
        FsOverflowPanelState::Closed => 0,
        FsOverflowPanelState::Root => FullscreenOverflowItemId::fixed_order().len(),
        FsOverflowPanelState::NavigatorPosition => 1 + FullscreenNavigatorCorner::ALL.len(),
    }
}

fn fs_overflow_panel_rect(
    full_rect: egui::Rect,
    state: FsOverflowPanelState,
) -> Option<egui::Rect> {
    if state == FsOverflowPanelState::Closed {
        return None;
    }
    let available_width = (full_rect.width() - FS_OVERFLOW_PANEL_MARGIN * 2.0).max(0.0);
    let top = full_rect.top() + TOP_BAR_HEIGHT + FS_OVERFLOW_PANEL_MARGIN;
    let available_height = (full_rect.bottom() - FS_OVERFLOW_PANEL_MARGIN - top).max(0.0);
    if available_width <= 0.0 || available_height <= 0.0 {
        return None;
    }
    let width = FS_OVERFLOW_PANEL_WIDTH.min(available_width);
    let desired_height = FS_OVERFLOW_PANEL_PADDING * 2.0
        + FS_OVERFLOW_PANEL_HEADER_HEIGHT
        + fs_overflow_panel_body_row_count(state) as f32 * FS_OVERFLOW_PANEL_ROW_HEIGHT;
    let height = desired_height.min(available_height);
    let left = full_rect.right() - FS_OVERFLOW_PANEL_MARGIN - width;
    Some(egui::Rect::from_min_size(
        egui::pos2(left, top),
        egui::vec2(width, height),
    ))
}

fn append_fs_overflow_touch_exclusion(
    excluded: &mut Vec<egui::Rect>,
    full_rect: egui::Rect,
    state: FsOverflowPanelState,
) {
    if let Some(rect) = fs_overflow_panel_rect(full_rect, state) {
        excluded.push(rect);
    }
}

fn draw_fs_overflow_panel_row(
    ui: &mut egui::Ui,
    _id: impl std::hash::Hash,
    label: &str,
    status: &str,
    selected: bool,
    enabled: bool,
    disabled_reason: Option<&'static str>,
) -> egui::Response {
    let sense = if enabled {
        egui::Sense::click()
    } else {
        egui::Sense::hover()
    };
    let (rect, response) = ui.allocate_exact_size(
        egui::vec2(ui.available_width(), FS_OVERFLOW_PANEL_ROW_HEIGHT),
        sense,
    );
    let background = if selected {
        egui::Color32::from_rgb(54, 93, 142)
    } else if enabled && response.hovered() {
        egui::Color32::from_gray(58)
    } else {
        egui::Color32::TRANSPARENT
    };
    ui.painter().rect_filled(rect, 4.0, background);
    ui.painter().line_segment(
        [
            egui::pos2(rect.left() + 8.0, rect.bottom()),
            egui::pos2(rect.right() - 8.0, rect.bottom()),
        ],
        egui::Stroke::new(1.0, egui::Color32::from_gray(58)),
    );

    let text_color = if enabled {
        ui.visuals().text_color()
    } else {
        egui::Color32::from_gray(118)
    };
    let status_color = if selected {
        egui::Color32::WHITE
    } else if enabled {
        ui.visuals().weak_text_color()
    } else {
        egui::Color32::from_gray(105)
    };
    let status_galley = ui.painter().layout_no_wrap(
        status.to_owned(),
        egui::FontId::proportional(13.0),
        status_color,
    );
    let status_size = status_galley.size();
    let status_right = rect.right() - 12.0;
    ui.painter().galley(
        egui::pos2(
            status_right - status_size.x,
            rect.center().y - status_size.y * 0.5,
        ),
        status_galley,
        status_color,
    );

    let label_left = rect.left() + 12.0;
    let label_width = (status_right - status_size.x - 12.0 - label_left).max(40.0);
    let mut label_job = egui::text::LayoutJob::single_section(
        label.to_owned(),
        egui::TextFormat::simple(egui::FontId::proportional(14.0), text_color),
    );
    label_job.wrap = egui::text::TextWrapping::truncate_at_width(label_width);
    let label_galley = ui.painter().layout_job(label_job);
    ui.painter().galley(
        egui::pos2(label_left, rect.center().y - label_galley.size().y * 0.5),
        label_galley,
        text_color,
    );

    if let Some(reason) = disabled_reason {
        response.hover_tip_dark(reason)
    } else {
        response
    }
}

fn draw_fs_overflow_panel_surface(
    ui: &mut egui::Ui,
    panel_rect: egui::Rect,
    view: &FsOverflowPanelView,
) -> Option<FsOverflowPanelAction> {
    ui.painter().rect_filled(
        panel_rect,
        8.0,
        egui::Color32::from_rgba_unmultiplied(24, 24, 24, 248),
    );
    ui.painter().rect_stroke(
        panel_rect,
        8.0,
        egui::Stroke::new(1.0, egui::Color32::from_gray(82)),
        egui::StrokeKind::Inside,
    );
    let _sink = ui.interact(
        panel_rect,
        egui::Id::new("fs_overflow_panel_sink"),
        egui::Sense::click(),
    );

    let mut child = ui.new_child(egui::UiBuilder::new().max_rect(panel_rect));
    child.set_clip_rect(panel_rect);
    crate::os_theme::apply_dark_ui(&mut child);
    let header_rect = egui::Rect::from_min_size(
        panel_rect.min,
        egui::vec2(panel_rect.width(), FS_OVERFLOW_PANEL_HEADER_HEIGHT),
    );
    child.painter().rect_filled(
        header_rect,
        8.0,
        egui::Color32::from_rgba_unmultiplied(36, 36, 36, 250),
    );
    let title = match view.state {
        FsOverflowPanelState::Root => "その他の機能",
        FsOverflowPanelState::NavigatorPosition => "ナビゲータ位置",
        FsOverflowPanelState::Closed => return None,
    };
    child.painter().text(
        egui::pos2(header_rect.left() + 14.0, header_rect.center().y),
        egui::Align2::LEFT_CENTER,
        title,
        egui::FontId::proportional(15.0),
        child.visuals().text_color(),
    );
    let close_rect = egui::Rect::from_min_size(
        egui::pos2(
            header_rect.right() - FS_OVERFLOW_PANEL_HEADER_HEIGHT,
            header_rect.top(),
        ),
        egui::vec2(
            FS_OVERFLOW_PANEL_HEADER_HEIGHT,
            FS_OVERFLOW_PANEL_HEADER_HEIGHT,
        ),
    );
    let close_response = child.interact(
        close_rect,
        egui::Id::new("fs_overflow_panel_close"),
        egui::Sense::click(),
    );
    if close_response.hovered() {
        child
            .painter()
            .rect_filled(close_rect, 4.0, egui::Color32::from_rgb(120, 46, 46));
    }
    child.painter().text(
        close_rect.center(),
        egui::Align2::CENTER_CENTER,
        "×",
        egui::FontId::proportional(18.0),
        egui::Color32::WHITE,
    );
    let mut action = close_response
        .clicked()
        .then_some(FsOverflowPanelAction::Close);

    let body_rect = egui::Rect::from_min_max(
        egui::pos2(
            panel_rect.left() + FS_OVERFLOW_PANEL_PADDING,
            header_rect.bottom() + FS_OVERFLOW_PANEL_PADDING,
        ),
        egui::pos2(
            panel_rect.right() - FS_OVERFLOW_PANEL_PADDING,
            panel_rect.bottom() - FS_OVERFLOW_PANEL_PADDING,
        ),
    );
    if body_rect.is_positive() {
        let mut body = child.new_child(egui::UiBuilder::new().max_rect(body_rect));
        body.set_clip_rect(body_rect);
        body.spacing_mut().scroll = egui::style::ScrollStyle::solid();
        egui::ScrollArea::vertical()
            .id_salt("fs_overflow_panel_body")
            .max_height(body_rect.height())
            .auto_shrink([false, false])
            .show(&mut body, |ui| {
                ui.set_width(ui.available_width());
                match view.state {
                    FsOverflowPanelState::Root => {
                        for row in &view.root_rows {
                            let response = draw_fs_overflow_panel_row(
                                ui,
                                ("fs_overflow_root", row.item),
                                &row.label,
                                &row.status,
                                false,
                                row.enabled,
                                row.disabled_reason,
                            );
                            if response.clicked() {
                                action = Some(FsOverflowPanelAction::Activate(row.item));
                            }
                        }
                    }
                    FsOverflowPanelState::NavigatorPosition => {
                        if draw_fs_overflow_panel_row(
                            ui,
                            "fs_overflow_back",
                            "<  戻る",
                            view.navigator_corner.label(),
                            false,
                            true,
                            None,
                        )
                        .clicked()
                        {
                            action = Some(FsOverflowPanelAction::Back);
                        }
                        for &corner in FullscreenNavigatorCorner::ALL {
                            let selected = corner == view.navigator_corner.normalized();
                            if draw_fs_overflow_panel_row(
                                ui,
                                ("fs_overflow_corner", corner as u8),
                                corner.label(),
                                if selected { "選択中" } else { "" },
                                selected,
                                true,
                                None,
                            )
                            .clicked()
                            {
                                action = Some(FsOverflowPanelAction::SetNavigatorCorner(corner));
                            }
                        }
                    }
                    FsOverflowPanelState::Closed => {}
                }
            });
    }
    action
}

pub(crate) fn panel_callout_edge_rect(
    full_rect: egui::Rect,
    edge: crate::ui_helpers::PanelEdge,
) -> egui::Rect {
    let width = crate::ui_helpers::PANEL_CALLOUT_HIT_PX.min(full_rect.width().max(0.0));
    match edge {
        crate::ui_helpers::PanelEdge::Left => egui::Rect::from_min_max(
            full_rect.min,
            egui::pos2(full_rect.min.x + width, full_rect.max.y),
        ),
        crate::ui_helpers::PanelEdge::Right => egui::Rect::from_min_max(
            egui::pos2(full_rect.max.x - width, full_rect.min.y),
            full_rect.max,
        ),
        crate::ui_helpers::PanelEdge::Top => egui::Rect::NOTHING,
    }
}

pub(crate) fn panel_callout_bar_rect(
    full_rect: egui::Rect,
    edge: crate::ui_helpers::PanelEdge,
) -> egui::Rect {
    let width = 20.0_f32.min(full_rect.width().max(0.0));
    let height = (full_rect.height() * 0.24).clamp(96.0, 220.0);
    let center_y = full_rect.center().y;
    let x = match edge {
        crate::ui_helpers::PanelEdge::Left => full_rect.left(),
        crate::ui_helpers::PanelEdge::Right => full_rect.right() - width,
        crate::ui_helpers::PanelEdge::Top => return egui::Rect::NOTHING,
    };
    egui::Rect::from_min_size(
        egui::pos2(x, center_y - height * 0.5),
        egui::vec2(width, height),
    )
}

/// Touch chrome reserves at most a 48 pt side handle: above the 40 pt target
/// from the tablet measurements, with enough horizontal margin for normal
/// finger drift. Music narrows this only to stay inside its existing empty
/// visualization margin.
const TOUCH_PANEL_HANDLE_WIDTH_PT: f32 = 48.0;
const MUSIC_TOUCH_PANEL_HANDLE_MIN_WIDTH_PT: f32 = 24.0;

fn touch_panel_handle_rect(
    full_rect: egui::Rect,
    edge: crate::ui_helpers::PanelEdge,
    safe_top_inset: f32,
    safe_bottom_inset: f32,
    max_width: f32,
) -> egui::Rect {
    if edge == crate::ui_helpers::PanelEdge::Top {
        return egui::Rect::NOTHING;
    }

    let safe_top = (full_rect.top() + safe_top_inset.max(0.0)).min(full_rect.bottom());
    let safe_bottom = (full_rect.bottom() - safe_bottom_inset.max(0.0)).max(full_rect.top());
    if safe_bottom <= safe_top {
        return egui::Rect::NOTHING;
    }
    let safe_height = safe_bottom - safe_top;
    let height = (full_rect.height() * 0.24)
        .clamp(96.0, 220.0)
        .min(safe_height);
    let width = TOUCH_PANEL_HANDLE_WIDTH_PT
        .min(max_width.max(0.0))
        .min(full_rect.width().max(0.0) * 0.5);
    if width <= 0.0 || height <= 0.0 {
        return egui::Rect::NOTHING;
    }
    let x = match edge {
        crate::ui_helpers::PanelEdge::Left => full_rect.left(),
        crate::ui_helpers::PanelEdge::Right => full_rect.right() - width,
        crate::ui_helpers::PanelEdge::Top => unreachable!(),
    };
    egui::Rect::from_min_size(
        egui::pos2(x, (safe_top + safe_bottom - height) * 0.5),
        egui::vec2(width, height),
    )
}

fn still_touch_panel_handle_rect(
    full_rect: egui::Rect,
    edge: crate::ui_helpers::PanelEdge,
) -> egui::Rect {
    touch_panel_handle_rect(
        full_rect,
        edge,
        TOP_BAR_HEIGHT,
        FS_SEEK_BAR_HEIGHT,
        TOUCH_PANEL_HANDLE_WIDTH_PT,
    )
}

fn still_touch_panel_handle_rects(full_rect: egui::Rect) -> [egui::Rect; 2] {
    [
        still_touch_panel_handle_rect(full_rect, crate::ui_helpers::PanelEdge::Left),
        still_touch_panel_handle_rect(full_rect, crate::ui_helpers::PanelEdge::Right),
    ]
}

fn visible_still_touch_panel_handle_rects(
    full_rect: egui::Rect,
    handles_enabled: bool,
    left_panel_open: bool,
    right_panel_open: bool,
) -> [egui::Rect; 2] {
    visible_touch_panel_handle_rects(
        still_touch_panel_handle_rects(full_rect),
        handles_enabled,
        left_panel_open,
        right_panel_open,
    )
}

fn visible_touch_panel_handle_rects(
    [left, right]: [egui::Rect; 2],
    handles_enabled: bool,
    left_panel_open: bool,
    right_panel_open: bool,
) -> [egui::Rect; 2] {
    if !handles_enabled {
        return [egui::Rect::NOTHING; 2];
    }
    [
        if left_panel_open {
            egui::Rect::NOTHING
        } else {
            left
        },
        if right_panel_open {
            egui::Rect::NOTHING
        } else {
            right
        },
    ]
}

fn extend_touch_excluded_with_panel_handles(
    excluded: &mut Vec<egui::Rect>,
    full_rect: egui::Rect,
    handles_enabled: bool,
    left_panel_open: bool,
    right_panel_open: bool,
) {
    excluded.extend(
        visible_still_touch_panel_handle_rects(
            full_rect,
            handles_enabled,
            left_panel_open,
            right_panel_open,
        )
        .into_iter()
        .filter(egui::Rect::is_positive),
    );
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum StillSidePanelAction {
    OpenAdjustment,
    OpenMetadata,
}

fn still_side_panel_action_for_handle_edge(
    edge: crate::ui_helpers::PanelEdge,
) -> StillSidePanelAction {
    match edge {
        crate::ui_helpers::PanelEdge::Left => StillSidePanelAction::OpenAdjustment,
        crate::ui_helpers::PanelEdge::Right => StillSidePanelAction::OpenMetadata,
        crate::ui_helpers::PanelEdge::Top => unreachable!("side-panel handle has no top edge"),
    }
}

fn touch_panel_tap_command_dismisses_before_dispatch(
    command: crate::touch_input::TouchCommand,
    left_open: crate::ui_helpers::MetadataPanelOpenState,
    right_open: crate::ui_helpers::MetadataPanelOpenState,
) -> bool {
    matches!(
        command,
        crate::touch_input::TouchCommand::ToggleChrome
            | crate::touch_input::TouchCommand::PageSide { .. }
    ) && (left_open == crate::ui_helpers::MetadataPanelOpenState::ByTouchHandle
        || right_open == crate::ui_helpers::MetadataPanelOpenState::ByTouchHandle)
}

#[derive(Clone, Copy)]
struct StillSidePanelChromeInputs {
    is_music_view: bool,
    analysis_active: bool,
    is_video: bool,
    compare_wipe_active: bool,
    panorama_active: bool,
    overlay_edit_active: bool,
    view_trim_active: bool,
    zoom_active: bool,
    animated: bool,
}

/// 右情報パネルのロックが**効くか**を決める入力。
///
/// ロックは「重ねずに右へ領域を確保する」なので、**確保する条件と描く条件が同じ**でなければ
/// ならない。別々に綴ると、パネルを描かないモードで右だけ空白の帯が残る (backlog §1.158)。
/// ここに並ぶのは、パネルを描かないモードとして描画側の分岐が既に持っている条件である。
#[derive(Clone, Copy)]
struct StillInfoPanelLockInputs {
    is_video: bool,
    video_tile_active: bool,
    local_adjust_active: bool,
    sns_split_active: bool,
    export_crop_active: bool,
    view_trim_active: bool,
    analysis_active: bool,
    panorama_active: bool,
    compare_wipe_active: bool,
    overlay_edit_active: bool,
    zoom_active: bool,
}

fn still_info_panel_lock_effective(locked: bool, input: StillInfoPanelLockInputs) -> bool {
    locked
        && !input.is_video
        && !input.video_tile_active
        && !input.local_adjust_active
        && !input.sns_split_active
        && !input.export_crop_active
        && !input.view_trim_active
        && !input.analysis_active
        && !input.panorama_active
        && !input.compare_wipe_active
        && !input.overlay_edit_active
        && !input.zoom_active
}

fn still_side_panel_chrome_enabled(input: StillSidePanelChromeInputs) -> bool {
    !input.is_music_view
        && !input.analysis_active
        && !input.is_video
        && !input.compare_wipe_active
        && !input.panorama_active
        && !input.overlay_edit_active
        && !input.view_trim_active
        && !input.zoom_active
        && !input.animated
}

#[derive(Clone, Copy)]
struct StillTopBarVisibilityInputs {
    locked: bool,
    hover_in_top: bool,
    side_panel_visible: bool,
    spread_popup_open: bool,
    fit_popup_open: bool,
    slideshow_popup_open: bool,
    rotation_popup_open: bool,
    panorama_projection_popup_open: bool,
    overflow_panel_open: bool,
    view_trim_mode: bool,
    touch_chrome_latched: bool,
}

fn still_top_bar_visible_from_inputs(input: StillTopBarVisibilityInputs) -> bool {
    input.locked
        || input.hover_in_top
        || input.side_panel_visible
        || input.spread_popup_open
        || input.fit_popup_open
        || input.slideshow_popup_open
        || input.rotation_popup_open
        || input.panorama_projection_popup_open
        || input.overflow_panel_open
        || input.view_trim_mode
        || input.touch_chrome_latched
}

#[derive(Clone, Copy)]
struct StillSeekBarVisibilityInputs {
    allowed: bool,
    locked: bool,
    bottom_hover: bool,
    drag_active: bool,
    side_panel_visible: bool,
    touch_chrome_latched: bool,
    wide_enough: bool,
    content_available: bool,
}

fn still_seek_bar_visible_from_inputs(input: StillSeekBarVisibilityInputs) -> bool {
    input.allowed
        && input.wide_enough
        && input.content_available
        && (input.locked
            || input.bottom_hover
            || input.drag_active
            || input.side_panel_visible
            || input.touch_chrome_latched)
}

#[derive(Clone, Copy, Default)]
struct StillTouchInputEnabledInputs {
    is_video: bool,
    is_music_view: bool,
    has_fullscreen_item: bool,
    dialog_open: bool,
    wants_keyboard_input: bool,
    ime_input_active: bool,
    context_menu_open: bool,
    spread_popup_open: bool,
    fit_popup_open: bool,
    slideshow_popup_open: bool,
    rotation_popup_open: bool,
    panorama_projection_popup_open: bool,
    compare_wipe_active: bool,
    overlay_edit_active: bool,
    view_trim_active: bool,
    zoom_active: bool,
}

/// タッチ入力を扱ってよい状況か。ここで false なら**ジェスチャー認識ごと止まる**。
///
/// 別ウィンドウ・ダイアログ・IME・ポップアップのように、そもそもキャンバスが
/// 前面にない状況だけを落とす。「自前のポインタ操作を持つ表示モード」は
/// `still_touch_tap_zones_enabled` の側で落とす。
fn still_touch_input_enabled(input: StillTouchInputEnabledInputs) -> bool {
    !input.is_video
        && !input.is_music_view
        && input.has_fullscreen_item
        && !input.dialog_open
        && !input.wants_keyboard_input
        && !input.ime_input_active
        && !input.context_menu_open
        && !input.spread_popup_open
        && !input.fit_popup_open
        && !input.slideshow_popup_open
        && !input.rotation_popup_open
        && !input.panorama_projection_popup_open
        && !input.compare_wipe_active
        && !input.overlay_edit_active
        && !input.view_trim_active
        && !input.zoom_active
}

/// 表示モードがキャンバスを所有しているか。
///
/// true のとき、キャンバスのクリック / タップは「ページ送り」ではなく、その
/// モード自身の操作を意味する。**マウスでもタッチでも同じ**。
///
/// クリックのページ送りは `fs_zoom` などの変形が無いときだけ走る作りで、
/// 360 度ビューと分析ツールは自前の状態を持ち `fs_zoom` を動かさないため、
/// この 2 つでは変形なしと見なされてページ送りが生きていた
/// (利用者報告 2026-08-13: 分析ツールのパネルを触ってもページが送られる)。
fn fs_display_mode_owns_canvas(panorama_active: bool, analysis_active: bool) -> bool {
    panorama_active || analysis_active
}

/// タップをページ送り / 中央タップとして解釈してよいか。
///
/// 360 度ビューと分析ツールは**画面全体が自前のポインタ操作**なので、タップ判定を
/// 使わない。ただしピンチは要る。かつては両方まとめて `still_touch_input_enabled`
/// で落としていて、**ピンチまで巻き添えで消えていた** (利用者報告 2026-08-13)。
///
/// この 2 つだけを分けるのは、**アイコンから入れる = キーボード無しで到達できる**
/// 表示モードがこの 2 つだからという判断 (2026-08-13、利用者判断)。ズームモードは
/// ホバー前提、編集系と比較ワイプはキー操作とセットでしか使えないので、
/// `still_touch_input_enabled` 側で止めたままにする。
fn still_touch_tap_zones_enabled(panorama_active: bool, analysis_active: bool) -> bool {
    !fs_display_mode_owns_canvas(panorama_active, analysis_active)
}

#[derive(Clone, Copy)]
struct StillTouchFirstRunHelpEligibility {
    learned: bool,
    touch_activity: bool,
    gestures_disabled: bool,
    touch_input_enabled: bool,
}

fn should_start_still_touch_first_run_help(input: StillTouchFirstRunHelpEligibility) -> bool {
    !input.learned && input.touch_activity && !input.gestures_disabled && input.touch_input_enabled
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum StillTouchFirstRunHelpPhase {
    /// The contact which discovered the help is consumed only to show it.
    AwaitingInitialRelease,
    /// A later tap anywhere dismisses the help and reveals chrome.
    Ready,
}

impl Default for StillTouchFirstRunHelpPhase {
    fn default() -> Self {
        Self::AwaitingInitialRelease
    }
}

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
struct StillTouchFirstRunHelpState {
    scope: StillTouchChromeLatch,
    phase: StillTouchFirstRunHelpPhase,
}

fn still_touch_first_run_help_id(ctx: &egui::Context) -> egui::Id {
    egui::Id::new((
        "miv_touch_first_run_help",
        ctx.viewport_id(),
        crate::touch_correlation::TouchSurface::StillFullscreen,
    ))
}

fn still_touch_first_run_help_phase(
    ctx: &egui::Context,
    scope: StillTouchChromeLatch,
) -> Option<StillTouchFirstRunHelpPhase> {
    let id = still_touch_first_run_help_id(ctx);
    ctx.data(|data| {
        data.get_temp::<StillTouchFirstRunHelpState>(id)
            .filter(|state| state.scope == scope)
            .map(|state| state.phase)
    })
}

fn set_still_touch_first_run_help_phase(
    ctx: &egui::Context,
    scope: StillTouchChromeLatch,
    phase: StillTouchFirstRunHelpPhase,
) {
    let id = still_touch_first_run_help_id(ctx);
    ctx.data_mut(|data| {
        data.insert_temp(id, StillTouchFirstRunHelpState { scope, phase });
    });
    ctx.request_repaint();
}

fn clear_still_touch_first_run_help(ctx: &egui::Context) {
    let id = still_touch_first_run_help_id(ctx);
    let removed = ctx.data_mut(|data| {
        data.remove_temp::<StillTouchFirstRunHelpState>(id)
            .is_some()
    });
    if removed {
        ctx.request_repaint();
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum StillTouchFirstRunHelpTapAction {
    Ignore,
    LearnAndShowChrome,
}

fn still_touch_first_run_help_tap_action(
    phase: StillTouchFirstRunHelpPhase,
    command: crate::touch_input::TouchCommand,
) -> StillTouchFirstRunHelpTapAction {
    if phase == StillTouchFirstRunHelpPhase::Ready
        && matches!(
            command,
            crate::touch_input::TouchCommand::ToggleChrome
                | crate::touch_input::TouchCommand::PageSide { .. }
        )
    {
        StillTouchFirstRunHelpTapAction::LearnAndShowChrome
    } else {
        StillTouchFirstRunHelpTapAction::Ignore
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum StillTouchForegroundReclaimAction {
    None,
    ToggleChrome,
    LearnAndShowChrome,
    SetHelpReady,
}

fn still_touch_foreground_reclaim_action(
    help_phase: Option<StillTouchFirstRunHelpPhase>,
    touch_active: bool,
    commands: &[crate::touch_input::TouchCommand],
) -> StillTouchForegroundReclaimAction {
    if let Some(help_phase) = help_phase {
        if commands.iter().copied().any(|command| {
            still_touch_first_run_help_tap_action(help_phase, command)
                == StillTouchFirstRunHelpTapAction::LearnAndShowChrome
        }) {
            return StillTouchForegroundReclaimAction::LearnAndShowChrome;
        }
        if help_phase == StillTouchFirstRunHelpPhase::AwaitingInitialRelease && !touch_active {
            return StillTouchForegroundReclaimAction::SetHelpReady;
        }
        return StillTouchForegroundReclaimAction::None;
    }

    if commands
        .iter()
        .any(|command| *command == crate::touch_input::TouchCommand::ToggleChrome)
    {
        StillTouchForegroundReclaimAction::ToggleChrome
    } else {
        // PageSide, pinch, pan, and all other commands are activation-only
        // no-ops while the existing focus-reclaim early return is active.
        StillTouchForegroundReclaimAction::None
    }
}

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
struct StillTouchChromeLatch {
    fs_idx: usize,
    session_started_at: Option<std::time::Instant>,
}

fn still_touch_chrome_latch_id(ctx: &egui::Context) -> egui::Id {
    egui::Id::new((
        "miv_touch_chrome_latch",
        ctx.viewport_id(),
        crate::touch_correlation::TouchSurface::StillFullscreen,
    ))
}

fn still_touch_chrome_latched(
    ctx: &egui::Context,
    fs_idx: usize,
    session_started_at: Option<std::time::Instant>,
) -> bool {
    // id は closure の**外**で作る。`ctx.data` は egui Context の RwLock を read で握るので、
    // closure の中で `still_touch_chrome_latch_id(ctx)` (= `ctx.viewport_id()`) を呼ぶと
    // 同じ lock を再帰 read することになる。parking_lot の RwLock は writer が待っていると
    // 後続の read を writer の後ろに並ばせるため、**自分が離さない lock を自分で待つ**。
    // 2026-08-26 に実機で、フルスクリーン動画のシーク中に UI スレッドが恒久的に固まった
    // (hung dump の main スレッドがこの経路だった)。
    let latch_id = still_touch_chrome_latch_id(ctx);
    ctx.data(|data| {
        data.get_temp::<StillTouchChromeLatch>(latch_id)
            == Some(StillTouchChromeLatch {
                fs_idx,
                session_started_at,
            })
    })
}

fn toggle_still_touch_chrome_latch(
    ctx: &egui::Context,
    fs_idx: usize,
    session_started_at: Option<std::time::Instant>,
) {
    let latch = StillTouchChromeLatch {
        fs_idx,
        session_started_at,
    };
    let latched = !still_touch_chrome_latched(ctx, fs_idx, session_started_at);
    set_still_touch_chrome_latch(ctx, latch, latched);
}

fn set_still_touch_chrome_latch(ctx: &egui::Context, latch: StillTouchChromeLatch, latched: bool) {
    let id = still_touch_chrome_latch_id(ctx);
    ctx.data_mut(|data| {
        if latched {
            data.insert_temp(id, latch);
        } else if data.get_temp::<StillTouchChromeLatch>(id) == Some(latch) {
            data.remove_temp::<StillTouchChromeLatch>(id);
        }
    });
    ctx.request_repaint();
}

fn fs_rotation_popup_open(ctx: &egui::Context) -> bool {
    egui::Popup::is_id_open(ctx, egui::Id::new("fs_rotation_btn").with("popup"))
}

#[derive(Clone, Copy, Debug, Default, PartialEq)]
struct FullscreenSidePanelRects {
    left: Option<egui::Rect>,
    right: Option<egui::Rect>,
}

impl FullscreenSidePanelRects {
    fn iter(self) -> impl Iterator<Item = egui::Rect> {
        [self.left, self.right].into_iter().flatten()
    }
}

fn fullscreen_side_panel_rects(
    full_rect: egui::Rect,
    chrome_enabled: bool,
    mode: crate::settings::FsSidePanelMode,
    right_panel_visible: bool,
    left_panel_visible: bool,
) -> FullscreenSidePanelRects {
    if !chrome_enabled {
        return FullscreenSidePanelRects::default();
    }
    let click_mode = mode.normalized() == crate::settings::FsSidePanelMode::ClickToShow;
    FullscreenSidePanelRects {
        left: if left_panel_visible {
            Some(adjustment_panel_rect(full_rect))
        } else if click_mode {
            Some(panel_callout_edge_rect(
                full_rect,
                crate::ui_helpers::PanelEdge::Left,
            ))
        } else {
            None
        },
        right: Some(if right_panel_visible {
            metadata_panel_rect(full_rect)
        } else if click_mode {
            panel_callout_edge_rect(full_rect, crate::ui_helpers::PanelEdge::Right)
        } else {
            metadata_panel_hover_activation_rect(full_rect)
        }),
    }
}

fn fullscreen_side_panel_contains_pointer(
    full_rect: egui::Rect,
    pos: egui::Pos2,
    chrome_enabled: bool,
    mode: crate::settings::FsSidePanelMode,
    right_panel_visible: bool,
    left_panel_visible: bool,
    navigator_exclusion: Option<egui::Rect>,
) -> bool {
    if !fullscreen_edge_hover_allowed(pos, navigator_exclusion) {
        return false;
    }
    fullscreen_side_panel_rects(
        full_rect,
        chrome_enabled,
        mode,
        right_panel_visible,
        left_panel_visible,
    )
    .iter()
    .any(|rect| rect.contains(pos))
}

fn music_left_panel_visible_from_inputs(
    mode: crate::settings::FsSidePanelMode,
    hover_active: bool,
    open_state: crate::ui_helpers::MetadataPanelOpenState,
    modal_open: bool,
) -> bool {
    // 左パネル (ブックマーク) に固定は無い。右と同じ判定を共有するので false を渡す。
    music_right_panel_visible_from_inputs(mode, hover_active, open_state, modal_open, false)
}

/// 音楽ビューの右パネルを描くか。**固定中は召喚方法によらず描く。**
///
/// モーダル中だけは描かない (背後クリック漏れ防止)。確保する側と同じ答えでなければ
/// 右に空白の帯が残る (backlog §1.158)。
fn music_right_panel_visible_from_inputs(
    mode: crate::settings::FsSidePanelMode,
    hover_active: bool,
    open_state: crate::ui_helpers::MetadataPanelOpenState,
    modal_open: bool,
    locked: bool,
) -> bool {
    if modal_open {
        return false;
    }
    if locked {
        return true;
    }
    let explicit = crate::ui_helpers::metadata_panel_explicit_shown(mode, open_state);
    match mode.normalized() {
        crate::settings::FsSidePanelMode::Hover => hover_active || explicit,
        crate::settings::FsSidePanelMode::ClickToShow => explicit,
        crate::settings::FsSidePanelMode::Unknown => unreachable!("normalized side panel mode"),
    }
}

/// 音楽ビューがこのフレームで実際に描く操作 UI のうち、カーソル自動非表示を
/// 止めるもの。App に永続させず、描画結果から同じフレームの cursor 判定へ渡す。
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub(crate) struct MusicViewFrameUiState {
    left_panel_visible: bool,
    right_panel_visible: bool,
    modal_open: bool,
}

impl MusicViewFrameUiState {
    fn from_panel_inputs(
        mode: crate::settings::FsSidePanelMode,
        left_hover_active: bool,
        right_hover_active: bool,
        left_open_state: crate::ui_helpers::MetadataPanelOpenState,
        right_open_state: crate::ui_helpers::MetadataPanelOpenState,
        modal_open: bool,
        right_locked: bool,
    ) -> Self {
        Self {
            left_panel_visible: music_left_panel_visible_from_inputs(
                mode,
                left_hover_active,
                left_open_state,
                modal_open,
            ),
            right_panel_visible: music_right_panel_visible_from_inputs(
                mode,
                right_hover_active,
                right_open_state,
                modal_open,
                right_locked,
            ),
            modal_open,
        }
    }

    fn blocks_cursor_auto_hide(self) -> bool {
        self.left_panel_visible || self.right_panel_visible || self.modal_open
    }
}

const MUSIC_TOP_BAR_HEIGHT: f32 = 54.0;

fn music_visualization_side_margin(view_width: f32) -> f32 {
    let edge_trigger = crate::ui_helpers::panel_edge_trigger_px(view_width);
    (edge_trigger + view_width.max(0.0) * 0.03).max(8.0)
}

fn music_touch_panel_handle_rects(full_rect: egui::Rect) -> [egui::Rect; 2] {
    let max_width = music_visualization_side_margin(full_rect.width());
    let rects = [
        touch_panel_handle_rect(
            full_rect,
            crate::ui_helpers::PanelEdge::Left,
            MUSIC_TOP_BAR_HEIGHT,
            crate::ui_music_panels::MUSIC_HUD_HEIGHT,
            max_width,
        ),
        touch_panel_handle_rect(
            full_rect,
            crate::ui_helpers::PanelEdge::Right,
            MUSIC_TOP_BAR_HEIGHT,
            crate::ui_music_panels::MUSIC_HUD_HEIGHT,
            max_width,
        ),
    ];
    if rects[0].width() < MUSIC_TOUCH_PANEL_HANDLE_MIN_WIDTH_PT {
        [egui::Rect::NOTHING; 2]
    } else {
        rects
    }
}

fn visible_music_touch_panel_handle_rects(
    full_rect: egui::Rect,
    handles_enabled: bool,
    left_panel_open: bool,
    right_panel_open: bool,
) -> [egui::Rect; 2] {
    visible_touch_panel_handle_rects(
        music_touch_panel_handle_rects(full_rect),
        handles_enabled,
        left_panel_open,
        right_panel_open,
    )
}

fn music_panel_callout_edges_without_touch_handles(handle_rects: [egui::Rect; 2]) -> [bool; 2] {
    handle_rects.map(|rect| !rect.is_positive())
}

fn music_touch_observed_id(ctx: &egui::Context) -> egui::Id {
    egui::Id::new(("miv_music_touch_observed", ctx.viewport_id()))
}

fn observe_music_touch_for_panel_handles(ctx: &egui::Context, gestures_disabled: bool) -> bool {
    if gestures_disabled {
        return false;
    }
    let id = music_touch_observed_id(ctx);
    if ctx.data(|data| data.get_temp::<bool>(id).unwrap_or(false)) {
        return true;
    }
    let touch_observed = ctx.input(|input| {
        input
            .events
            .iter()
            .any(|event| matches!(event, egui::Event::Touch { .. }))
    });
    if touch_observed {
        ctx.data_mut(|data| data.insert_temp(id, true));
    }
    touch_observed
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum MusicPanelReachSource {
    Pointer,
    TouchHandle,
}

fn music_panel_open_state_after_reach(
    mode: crate::settings::FsSidePanelMode,
    state: crate::ui_helpers::MetadataPanelOpenState,
    source: MusicPanelReachSource,
) -> crate::ui_helpers::MetadataPanelOpenState {
    match source {
        MusicPanelReachSource::Pointer => {
            crate::ui_helpers::toggle_side_panel_by_pointer(mode, state)
        }
        MusicPanelReachSource::TouchHandle => crate::ui_helpers::open_side_panel_by_touch(state),
    }
}

/// 音楽ビューの右パネルが占める帯 — `(確保幅, 右端, パネル幅)`。
///
/// `reserved` は `fullscreen_media_rect` が `rect` から**実際に引いた**幅で、ロックして
/// いなければ 0。**縮んだ `rect` から元の幅を逆算しない。** 逆算式
/// `R.min((rect.width() + R) / 2)` は元幅が `2R` 以上のときしか成り立たず、それ未満の
/// 窓では確保した帯より広いパネルを右へはみ出させる (幅 640pt で 55pt。レビュー F11)。
fn music_right_panel_band(rect: egui::Rect, reserved: f32) -> (f32, f32, f32) {
    let reserved = if reserved.is_finite() {
        reserved.max(0.0)
    } else {
        0.0
    };
    let right_edge = rect.right() + reserved;
    // 帯の幅とパネルの幅は同じ 1 つの答え。ロックしていないときだけ、重ねて描く既定幅を
    // ビュー幅の半分でクランプする (`music_side_panel_contains_pointer` と同じ規則)。
    let width = if reserved > 0.0 {
        reserved
    } else {
        crate::ui_music_panels::MUSIC_RIGHT_PANEL_WIDTH.min(rect.width() * 0.5)
    };
    (reserved, right_edge, width)
}

fn music_side_panel_contains_pointer(
    full_rect: egui::Rect,
    pos: egui::Pos2,
    left_visible: bool,
    right_visible: bool,
) -> bool {
    let band_top = full_rect.top() + MUSIC_TOP_BAR_HEIGHT;
    let band_bottom = full_rect.bottom() - crate::ui_music_panels::MUSIC_HUD_HEIGHT;
    let left_w = crate::ui_music_panels::MUSIC_LEFT_PANEL_WIDTH;
    let right_w = crate::ui_music_panels::MUSIC_RIGHT_PANEL_WIDTH.min(full_rect.width() * 0.5);
    let in_band = pos.y >= band_top && pos.y <= band_bottom;
    (left_visible && in_band && pos.x <= full_rect.left() + left_w)
        || (right_visible && in_band && pos.x >= full_rect.right() - right_w)
}

/// メタデータパネルを「開く」ホバートリガ矩形。画面右端の細いストリップ
/// (`PANEL_EDGE_TRIGGER_WIDTH`) だけを判定に使う。縦方向は従来どおり全高 (上バー / シーク
/// バー帯でも右端ホバーで開ける)。一度開いた後の「維持」判定は `draw_metadata_panel` 側で
/// `panel_rect` + `PANEL_HOVER_SUSTAIN_MARGIN` が担う。
pub(crate) fn metadata_panel_hover_activation_rect(full_rect: egui::Rect) -> egui::Rect {
    let strip =
        crate::ui_helpers::panel_edge_trigger_px(full_rect.width()).min(full_rect.width().max(0.0));
    egui::Rect::from_min_max(
        egui::pos2(full_rect.max.x - strip, full_rect.top()),
        egui::pos2(full_rect.max.x, full_rect.bottom()),
    )
}

/// 右メタデータパネルの端ホバーラッチを現在座標から更新する。
/// 開くときは右端トリガ、開いた後は実描画矩形 + sustain margin を使う。
/// The primary call site now runs before navigator-consumed image input returns; panel drawing
/// repeats the same idempotent update only for modal paths that bypass the general input handler.
pub(crate) fn metadata_panel_hover_active_at(
    full_rect: egui::Rect,
    pointer_pos: Option<egui::Pos2>,
    was_active: bool,
    navigator_exclusion: Option<egui::Rect>,
) -> bool {
    let activation_rect = metadata_panel_hover_activation_rect(full_rect);
    let sustain_rect = metadata_panel_rect(full_rect)
        .expand(crate::ui_helpers::panel_hover_sustain_px(full_rect.width()));
    pointer_pos.is_some_and(|p| {
        fullscreen_edge_hover_allowed(p, navigator_exclusion)
            && (activation_rect.contains(p) || (was_active && sustain_rect.contains(p)))
    })
}

/// 画像用左パネルの端ホバーラッチを現在座標から更新する。
/// 新規表示は左端の細いトリガだけ、表示後は実描画矩形の周囲にヒステリシス余白を持たせる。
/// タブへ斜めに移動する途中でトリガを抜けても、余白内なら閉じない。
fn adjustment_panel_hover_active_at(
    full_rect: egui::Rect,
    pointer_pos: Option<egui::Pos2>,
    was_active: bool,
    navigator_exclusion: Option<egui::Rect>,
) -> bool {
    let strip =
        crate::ui_helpers::panel_edge_trigger_px(full_rect.width()).min(full_rect.width().max(0.0));
    let activation_rect = egui::Rect::from_min_max(
        full_rect.left_top(),
        egui::pos2(full_rect.left() + strip, full_rect.bottom()),
    );
    let sustain_rect = adjustment_panel_rect(full_rect)
        .expand(crate::ui_helpers::panel_hover_sustain_px(full_rect.width()));
    pointer_pos.is_some_and(|pos| {
        fullscreen_edge_hover_allowed(pos, navigator_exclusion)
            && (activation_rect.contains(pos) || (was_active && sustain_rect.contains(pos)))
    })
}

fn adjustment_panel_should_auto_close(
    mode: crate::settings::FsSidePanelMode,
    panel_open: bool,
    dragging: bool,
    hover_active: bool,
    bookmark_title_focused: bool,
    touch_chrome_latched: bool,
) -> bool {
    mode.normalized() == crate::settings::FsSidePanelMode::Hover
        && panel_open
        && !dragging
        && !hover_active
        && !bookmark_title_focused
        && !touch_chrome_latched
}

fn still_passive_side_panel_hover_enabled(cursor_hidden: bool, touch_chrome_latched: bool) -> bool {
    // Touch pointer emulation passes through the physical edge before a
    // visible handle commits. Once touch chrome owns the panel reach path,
    // passive hover must not pre-open a panel and invert its toggle.
    !cursor_hidden && !touch_chrome_latched
}

fn next_fullscreen_cursor_hide_reason(
    current: Option<FsCursorHide>,
    zoom_aiming: bool,
    cursor_active: bool,
    clean: bool,
    idle_hide_ready: bool,
) -> Option<FsCursorHide> {
    if zoom_aiming {
        // ZoomAiming is derived from fs_zoom_aiming every frame and is never latched,
        // so every way aiming can end returns the cursor without its own exit branch.
        return Some(FsCursorHide::ZoomAiming);
    }

    // Idle keeps its pre-existing latch: it survives frames with no pointer activity and
    // is cleared by any activity. Aiming needs no carried-over copy of that fact. The
    // caller restarts the idle countdown on activity, so a hide that predates aiming is
    // re-derived here through `idle_hide_ready` when the pointer really did stay still.
    if clean && ((matches!(current, Some(FsCursorHide::Idle)) && !cursor_active) || idle_hide_ready)
    {
        Some(FsCursorHide::Idle)
    } else {
        None
    }
}

fn should_handle_fullscreen_wheel(
    cursor_in_panel: bool,
    in_video_tile: bool,
    ctrl_held: bool,
    modal_for_keys: bool,
    // 表示モード / フィット / スライドショーのポップアップメニュー表示中は、メニュー上でも画像上でも
    // ホイールを背後のページ送り・連結スクロール・ズームへ流さない (modal と同様に全抑制)。
    popup_open: bool,
) -> bool {
    !modal_for_keys
        && !popup_open
        && (!in_video_tile || !ctrl_held)
        && (ctrl_held || !cursor_in_panel)
}

fn fullscreen_cursor_in_panel_for_wheel(
    cursor_in_panel: bool,
    cursor_in_seek_panel: bool,
    seek_drag_active: bool,
) -> bool {
    if cursor_in_seek_panel && !seek_drag_active {
        false
    } else {
        cursor_in_panel
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum EditBrushRadiusOwner {
    Conceal,
    Erase,
    LocalAdjustment,
}

#[derive(Clone, Copy)]
struct EditBrushRadiusContext {
    canvas_available: bool,
    conceal_tool: Option<crate::conceal::ConcealTool>,
    erase_tool: Option<crate::app::EraseTool>,
    local_adjust_tool: Option<crate::app::LocalAdjustMaskTool>,
}

fn edit_brush_radius_owner(context: EditBrushRadiusContext) -> Option<EditBrushRadiusOwner> {
    if !context.canvas_available {
        return None;
    }
    if context.conceal_tool == Some(crate::conceal::ConcealTool::Brush) {
        Some(EditBrushRadiusOwner::Conceal)
    } else if context.erase_tool == Some(crate::app::EraseTool::Brush) {
        Some(EditBrushRadiusOwner::Erase)
    } else if matches!(
        context.local_adjust_tool,
        Some(
            crate::app::LocalAdjustMaskTool::Brush
                | crate::app::LocalAdjustMaskTool::EdgeBrush
                | crate::app::LocalAdjustMaskTool::GapFillBrush
        )
    ) {
        Some(EditBrushRadiusOwner::LocalAdjustment)
    } else {
        None
    }
}

fn fullscreen_click_nav_delta_for_side(left: bool, rtl: bool) -> i32 {
    let ltr_base = if left { -1 } else { 1 };
    if rtl { -ltr_base } else { ltr_base }
}

/// Return the next pan for a canvas drag, including the frame where egui first
/// promotes a click-and-drag response to the dragged state.
///
/// Sense::click_and_drag deliberately delays drag_started until movement
/// exceeds the click threshold. Treating that promotion frame as a press-only
/// frame drops the entire first (and often only, for coalesced touch input)
/// movement. total_drag_delta is measured from the real pointer press even on
/// that promotion frame, so applying it to the pan captured at drag start
/// preserves the established absolute mouse-pan and clamp behavior without
/// synthesizing another press.
fn fullscreen_drag_pan_proposal(
    response: &egui::Response,
    pan_at_drag_start: egui::Vec2,
) -> Option<egui::Vec2> {
    response
        .dragged_by(egui::PointerButton::Primary)
        .then(|| response.total_drag_delta())
        .flatten()
        .map(|delta| pan_at_drag_start + delta)
}

fn fullscreen_click_nav_base_delta(pos_x: f32, center_x: f32, rtl: bool) -> i32 {
    fullscreen_click_nav_delta_for_side(pos_x < center_x, rtl)
}

fn should_zoom_fullscreen_wheel(ctrl_held: bool, overlay_edit_mode: bool) -> bool {
    ctrl_held || overlay_edit_mode
}

/// Whether a click on the canvas belongs to the view rather than to turning the page.
///
/// **Pan is deliberately not part of this.** A page that fits the window can be dragged too, so
/// counting pan here would mean that nudging the image even slightly stops clicks from turning
/// pages - with the way back (double-click to reset) unmarked, which is a worse dead end than the
/// one that made panning always available in the first place. A drag is kept from being read as a
/// click at the call site.
fn fullscreen_click_belongs_to_view(zoom: f32, free_rotation: f32) -> bool {
    zoom > ZOOM_NEAR_ONE || free_rotation.abs() > TRANSFORM_EPSILON
}

fn should_suppress_egui_wheel_for_native_detached_video(
    is_video: bool,
    detached: bool,
    native_presenter_active: bool,
    music_view_active: bool,
) -> bool {
    is_video && detached && native_presenter_active && !music_view_active
}

