fn fullscreen_pointer_pos_from_viewport(
    raw_pos: egui::Pos2,
    viewport_inner: Option<egui::Rect>,
    full_rect: egui::Rect,
) -> egui::Pos2 {
    if full_rect.contains(raw_pos) {
        return raw_pos;
    }

    if let Some(inner) = viewport_inner {
        // Depending on the viewport path, egui can report pointer positions either
        // in viewport-local points or in virtual-desktop points. Try both mappings
        // before falling back to a visible clamped position.
        let candidates = [
            raw_pos - inner.min.to_vec2() + full_rect.min.to_vec2(),
            raw_pos + inner.min.to_vec2(),
            raw_pos - full_rect.min.to_vec2(),
            raw_pos + full_rect.min.to_vec2(),
        ];
        for candidate in candidates {
            if full_rect.contains(candidate) {
                return candidate;
            }
        }
    }

    egui::pos2(
        raw_pos.x.clamp(full_rect.min.x, full_rect.max.x),
        raw_pos.y.clamp(full_rect.min.y, full_rect.max.y),
    )
}

fn fullscreen_pointer_pos_or(
    ctx: &egui::Context,
    full_rect: egui::Rect,
    fallback: egui::Pos2,
) -> egui::Pos2 {
    ctx.input(|i| {
        i.pointer
            .interact_pos()
            .or_else(|| i.pointer.latest_pos())
            .or_else(|| i.pointer.hover_pos())
            .map(|pos| {
                fullscreen_pointer_pos_from_viewport(pos, i.viewport().inner_rect, full_rect)
            })
            .unwrap_or(fallback)
    })
}

/// 中ボタンドラッグズーム: 縦 N px で倍率 2 倍/半分になる感度 (v0.8.1)。
/// 100 px で 2 倍 (= 上へ 200 px で 4 倍)。ホイール 1 ノッチ ≈ 10% と比べて粗めだが、
/// 縦フル (1080 px) ストロークすれば 2^10 ≈ 1000 倍まで届くので十分。
const MIDDLE_DRAG_UNIT_PX: f32 = 100.0;
/// 中ボタン押下から「ドラッグ開始」とみなす最小移動量。
/// この距離以下ならズームは触らない (クリックのみとの区別 / 暴発防止)。
pub(crate) const MIDDLE_DRAG_THRESHOLD_PX: f32 = 4.0;
/// ズーム倍率の下限
const ZOOM_MIN: f32 = 0.1;
/// ズーム倍率の上限
const ZOOM_MAX: f32 = 50.0;
/// 連結読み: ホイール 1 ノッチ相当として扱う raw scroll delta。
const CONTINUOUS_READING_WHEEL_REFERENCE_DELTA: f32 = 120.0;
/// 連結読み: PageUp/PageDown で進む画面長の割合。
const VERTICAL_READING_PAGE_SCROLL_FRAC: f32 = 0.85;
/// 連結読み: 同時に画面に入るページ数の上限。
const VERTICAL_READING_MAX_VISIBLE_PAGES: usize = 16;
/// 連結読み: 厳密可視ユニットの前後で final pipeline を先行準備する幅。
const VERTICAL_READING_PREPARE_BAND_UNITS: usize = 1;
/// 連結読み: 可視範囲の前後に保持する先読みページ数。
const VERTICAL_READING_PREFETCH_PAD: usize = 2;
/// 連結読み: fs_cache に残すページ数上限。
const VERTICAL_READING_MAX_CACHE_PAGES: usize = 20;
/// 連結読み: final composite / comic 合成を新規生成するページ数の 1 フレーム上限。
const VERTICAL_READING_PROCESSED_UPLOADS_PER_FRAME: usize = 1;
/// ズームが 1.0 とみなせるしきい値
const ZOOM_NEAR_ONE: f32 = 1.001;
/// 回転・パンがゼロとみなせるしきい値
const TRANSFORM_EPSILON: f32 = 0.001;
/// パンがゼロとみなせるしきい値（length_sq）
const PAN_EPSILON_SQ: f32 = 0.25;

/// 共有 pool 由来の HIGH を超えた場合だけ trim を開始し、遠い非可視 unit を何個外せば
/// LOW 以下に到達するかを返す。候補が足りなければ全候補を返し、可視 unit と準備帯は
/// 呼び出し側で除外する。0% (無制限) では HIGH/LOW が `None` なので trim を無効化する。
fn vertical_reading_texel_trim_plan(
    loaded_texels: usize,
    removable_texels: impl IntoIterator<Item = usize>,
    watermarks: crate::vram_budget::VramWatermarks,
) -> (usize, usize) {
    let (Some(high_texels), Some(low_texels)) = (watermarks.high_texels, watermarks.low_texels)
    else {
        return (0, loaded_texels);
    };
    if loaded_texels <= high_texels {
        return (0, loaded_texels);
    }
    let mut remaining = loaded_texels;
    let mut remove_count = 0usize;
    for texels in removable_texels {
        remaining = remaining.saturating_sub(texels);
        remove_count += 1;
        if remaining <= low_texels {
            break;
        }
    }
    (remove_count, remaining)
}

fn vertical_reading_trim_removable_positions(
    keep_positions: &[usize],
    visible_positions: &std::collections::HashSet<usize>,
    prepare_positions: &std::collections::HashSet<usize>,
) -> Vec<usize> {
    keep_positions
        .iter()
        .copied()
        .filter(|pos| !visible_positions.contains(pos) && !prepare_positions.contains(pos))
        .collect()
}

/// バー内ボタンのサイズ
/// 上バーのポップアップ内で、アイコン列の右にテキストを置き始める位置。
const PANORAMA_PROJECTION_POPUP_TEXT_LEFT: f32 = 48.0;

/// 上バーのポップアップ余白 (画面端との最小距離)。
const BAR_POPUP_SCREEN_MARGIN: f32 = 8.0;

/// 上バーのボタンから吊り下がるポップアップを画面内へ収める。
///
/// ボタンは右端から左へ並ぶので、**右寄りのボタンでは左寄せのままだと画面外へ出る**
/// (360 表示中の投影ボタンは × / 鍵の隣で、実際に切れていた)。左上を動かすだけで、
/// 大きさは変えない。画面より大きいポップアップは左上に貼り付けて、はみ出す側を
/// 右下に寄せる (縮めると中身が読めなくなるため)。
fn clamp_bar_popup_rect(
    full_rect: egui::Rect,
    anchor_x: f32,
    top: f32,
    size: egui::Vec2,
) -> egui::Rect {
    let margin = BAR_POPUP_SCREEN_MARGIN;
    let min_x = full_rect.min.x + margin;
    let max_x = full_rect.max.x - margin - size.x;
    // 画面が狭くて収まらない場合は max_x < min_x になる。左端優先で貼る。
    let x = anchor_x.min(max_x).max(min_x);
    let min_y = full_rect.min.y + margin;
    let max_y = full_rect.max.y - margin - size.y;
    let y = top.min(max_y).max(min_y);
    egui::Rect::from_min_size(egui::pos2(x, y), size)
}

pub(crate) const BAR_BUTTON_SIZE: f32 = 32.0;
/// バー内ボタンの上下マージン
pub(crate) const BAR_BUTTON_MARGIN: f32 = 6.0;
/// バー内ボタン間の隙間
const BAR_BUTTON_GAP: f32 = 4.0;

#[cfg(windows)]
pub(crate) fn detached_image_window_bar_close_button_rect(full_rect: egui::Rect) -> egui::Rect {
    let bar_rect =
        egui::Rect::from_min_size(full_rect.min, egui::vec2(full_rect.width(), TOP_BAR_HEIGHT));
    egui::Rect::from_min_size(
        egui::pos2(
            bar_rect.max.x - BAR_BUTTON_SIZE - BAR_BUTTON_MARGIN,
            bar_rect.min.y + BAR_BUTTON_MARGIN,
        ),
        egui::vec2(BAR_BUTTON_SIZE, BAR_BUTTON_SIZE),
    )
}

