fn scale_sns_split_frames_to_export_pixels(
    frames: &[crate::export_crop::CropRect],
    source_size: [usize; 2],
    target_size: [usize; 2],
) -> Result<Vec<crate::export_crop::CropRect>, String> {
    if frames.is_empty() {
        return Ok(Vec::new());
    }
    let source_width = source_size[0].max(1) as f64;
    let source_height = source_size[1].max(1) as f64;
    let target_width = target_size[0].max(1);
    let target_height = target_size[1].max(1);
    let scale_x = target_width as f64 / source_width;
    let scale_y = target_height as f64 / source_height;

    // source の共有境界を同じ最近傍丸めで target へ写す。先頭枠の幅を全枠へ
    // 複製すると、割り切れない余り (832 / 3 など) が末尾から失われる。
    let frame_count = frames.len();
    if target_width < frame_count {
        return Err("最終合成の解像度が小さすぎて SNS 分割枠を配置できません".to_string());
    }

    let scale_boundary = |value: f32, scale: f64, limit: usize| -> Option<usize> {
        let scaled = f64::from(value) * scale;
        scaled
            .is_finite()
            .then(|| scaled.round().clamp(0.0, limit as f64) as usize)
    };
    let mut scaled = Vec::with_capacity(frame_count);
    for frame in frames {
        let Some(min_x) = scale_boundary(frame.min_x, scale_x, target_width) else {
            return Err("SNS 分割枠の座標が不正です".to_string());
        };
        let Some(max_x) = scale_boundary(frame.max_x, scale_x, target_width) else {
            return Err("SNS 分割枠の座標が不正です".to_string());
        };
        let Some(min_y) = scale_boundary(frame.min_y, scale_y, target_height) else {
            return Err("SNS 分割枠の座標が不正です".to_string());
        };
        let Some(max_y) = scale_boundary(frame.max_y, scale_y, target_height) else {
            return Err("SNS 分割枠の座標が不正です".to_string());
        };
        if max_x <= min_x || max_y <= min_y {
            return Err("最終合成の解像度が小さすぎて SNS 分割枠を配置できません".to_string());
        }
        scaled.push(crate::export_crop::CropRect {
            min_x: min_x as f32,
            min_y: min_y as f32,
            max_x: max_x as f32,
            max_y: max_y as f32,
        });
    }
    Ok(scaled)
}

fn export_batch_selection_update(
    sns_split: bool,
    original_selection: [bool; 5],
    selection: [bool; 5],
    has_conceal_mask: bool,
    preset_slots: &crate::conceal::ConcealPresetSlots,
) -> Option<[bool; 5]> {
    if sns_split {
        return None;
    }

    let mut next_selection = original_selection;
    for i in 0..selection.len() {
        if selection[i] {
            next_selection[i] = true;
        }
    }
    for i in 0..selection.len() {
        let env_disabled = i > 0 && (!has_conceal_mask || preset_slots[i - 1].is_none());
        if !selection[i] && !env_disabled {
            next_selection[i] = false;
        }
    }
    Some(next_selection)
}

#[cfg(windows)]
struct NativeFocusClaim {
    foreground_hwnd: usize,
    post_foreground_hwnd: usize,
    target_hwnd: usize,
    set_foreground_ok: bool,
    attach_thread_input_ok: bool,
    set_active_ok: bool,
    set_focus_ok: bool,
}

#[cfg(windows)]
struct NativeFocusTarget {
    foreground_hwnd: usize,
    target_hwnd: usize,
}

#[cfg(windows)]
fn native_window_under_cursor_focus_target() -> NativeFocusTarget {
    use windows::Win32::Foundation::POINT;
    use windows::Win32::UI::WindowsAndMessaging::{
        GA_ROOT, GetAncestor, GetCursorPos, GetForegroundWindow, WindowFromPoint,
    };

    unsafe {
        let mut pt = POINT::default();
        if GetCursorPos(&mut pt).is_err() {
            return NativeFocusTarget {
                foreground_hwnd: GetForegroundWindow().0 as usize,
                target_hwnd: 0,
            };
        }
        let hovered = WindowFromPoint(pt);
        let foreground = GetForegroundWindow();
        if hovered.0.is_null() {
            return NativeFocusTarget {
                foreground_hwnd: foreground.0 as usize,
                target_hwnd: 0,
            };
        }
        let root = GetAncestor(hovered, GA_ROOT);
        let target = if root.0.is_null() { hovered } else { root };
        NativeFocusTarget {
            foreground_hwnd: foreground.0 as usize,
            target_hwnd: target.0 as usize,
        }
    }
}

#[cfg(windows)]
fn claim_native_window_focus(target_hwnd: usize) -> NativeFocusClaim {
    let report = crate::video::native_window::claim_foreground(target_hwnd as u64);
    NativeFocusClaim {
        foreground_hwnd: report.foreground_hwnd as usize,
        post_foreground_hwnd: report.post_foreground_hwnd as usize,
        target_hwnd: report.target_hwnd as usize,
        set_foreground_ok: report.set_foreground_ok,
        attach_thread_input_ok: report.attach_thread_input_ok,
        set_active_ok: report.set_active_ok,
        set_focus_ok: report.set_focus_ok,
    }
}

