impl App {
    pub(crate) fn start_bucket_region_flash(
        &mut self,
        ctx: &egui::Context,
        fs_idx: usize,
        preview: crate::mask_db::BucketRegionPreview,
    ) {
        let [w, h] = preview.size;
        let expected_len = w.saturating_mul(h);
        if w == 0 || h == 0 || preview.mask.len() < expected_len {
            self.bucket_region_flash = None;
            return;
        }
        let mut rgba = vec![0_u8; expected_len * 4];
        for (idx, inside) in preview.mask.into_iter().take(expected_len).enumerate() {
            if inside {
                rgba[idx * 4] = 250;
                rgba[idx * 4 + 1] = 210;
                rgba[idx * 4 + 2] = 60;
                rgba[idx * 4 + 3] = 150;
            }
        }
        let texture = ctx.load_texture(
            format!("bucket-region-flash-{fs_idx}"),
            egui::ColorImage::from_rgba_unmultiplied([w, h], &rgba),
            egui::TextureOptions::NEAREST,
        );
        self.bucket_region_flash = Some(crate::app::BucketRegionFlash {
            fs_idx,
            texture,
            started_at: ctx.input(|input| input.time),
        });
        ctx.request_repaint();
    }

    pub(crate) fn draw_bucket_region_flash(
        &mut self,
        ui: &egui::Ui,
        ctx: &egui::Context,
        transform: &DisplayedImageTransform,
    ) {
        const VISIBLE_SECONDS: f64 = 1.0;
        const FADE_SECONDS: f64 = 0.3;

        let now = ctx.input(|input| input.time);
        let Some(flash) = self.bucket_region_flash.as_ref() else {
            return;
        };
        let elapsed = (now - flash.started_at).max(0.0);
        if elapsed >= VISIBLE_SECONDS || self.fullscreen_idx != Some(flash.fs_idx) {
            self.bucket_region_flash = None;
            return;
        }
        let opacity = if elapsed <= VISIBLE_SECONDS - FADE_SECONDS {
            1.0
        } else {
            ((VISIBLE_SECONDS - elapsed) / FADE_SECONDS).clamp(0.0, 1.0)
        };
        let tint = egui::Color32::from_white_alpha((opacity * 255.0).round() as u8);
        let painter = ui.painter().with_clip_rect(transform.viewport_rect);
        transform.paint_texture(&painter, flash.texture.id(), tint);
        ctx.request_repaint_after(std::time::Duration::from_millis(16));
    }

    /// 分析モードを解除し、関連する状態をリセットする。
    pub(crate) fn reset_analysis_mode(&mut self) {
        let restore_idx = self.fullscreen_idx;
        self.analysis_mode = false;
        // post-filter バイパスを解除 (消しゴム or 隠蔽加工モード中ならそちらが保持する)
        if self.post_filter_bypassed && !self.is_overlay_edit_mode_active() {
            let needs_post_filter_restore = restore_idx
                .map(|idx| {
                    self.effective_params(idx).post_filter != crate::adjustment::PostFilter::None
                })
                .unwrap_or(false);
            self.post_filter_bypassed = false;
            if needs_post_filter_restore {
                if let Some(idx) = restore_idx {
                    self.clear_adjustment_render_caches_for_bypass(idx);
                }
            }
        }
        self.analysis_hover_color = None;
        self.analysis_pinned_color = None;
        self.analysis_grayscale = false;
        self.analysis_mosaic_grid = false;
        self.analysis_filter_mag = 0;
        self.analysis_guide_drag = None;
    }

    /// 分析モード ON 時に post-filter を一時バイパスする。Z キーハンドラから呼ぶ。
    pub(crate) fn enter_analysis_mode_bypass(&mut self) {
        if !self.post_filter_bypassed {
            self.post_filter_bypassed = true;
            if let Some(idx) = self.fullscreen_idx {
                if self.effective_params(idx).post_filter != crate::adjustment::PostFilter::None {
                    self.clear_adjustment_render_caches_for_bypass(idx);
                }
            }
        }
    }

    /// 分析モードを ON/OFF トグルする。**Z キーとホバーバー分析ボタンの共通経路** (Codex P1:
    /// ボタンが `analysis_mode` を直接反転して副作用 = ズーム/パン引き継ぎ・post-filter
    /// bypass の enter/exit・補正パネル排他 を飛ばしていた退行を防ぐ)。
    pub(crate) fn toggle_analysis_mode(&mut self) {
        if self.analysis_mode {
            // 分析→通常: ズーム/パンを引き継ぐ
            self.fs_zoom = self.analysis_zoom;
            let proposed_pan = self.analysis_pan;
            self.reset_analysis_mode();
            self.set_fs_pan_from_input(self.fs_zoom, proposed_pan);
        } else {
            // 通常→分析: ズーム/パンを引き継ぐ
            self.analysis_zoom = self.fs_zoom;
            self.analysis_pan = self.fs_pan;
            self.analysis_mode = true;
            self.enter_analysis_mode_bypass();
            // 補正パネルと排他
            self.persist_pending_view_trim_state();
            self.adjustment_mode = crate::ui_helpers::MetadataPanelOpenState::Closed;
            self.cache_current_edit_preview_if_ready();
            self.local_adjust_mode = false;
            self.fold_local_adjust_edit_state();
            self.local_adjust_repair_point_pick_active = None;
            self.local_adjust_add_layer_dialog_open = false;
            self.local_adjust_change_mask_dialog_open = false;
            self.local_adjust_effect_picker_dialog_open = false;
        }
    }

    /// `idx` に対する「現在表示できる最良の既存テクスチャ」を Arc::clone で取り出す。
    /// 優先順: Animated 現フレーム → final composite cache → edit cache → fs_cache (Static)
    /// → サムネ (`include_thumb=true` のときのみ)。
    ///
    /// `prepare_fullscreen_state` の高解像度 tex 解決と `capture_fs_display_unit`
    /// が同じチェーンを 2 回書いていた重複を集約する。ここでは既存 cache の lookup
    /// だけを行い、MI-GAN や隠蔽合成の新規生成は走らせない。生成を伴う通常描画は
    /// `resolve_fs_processed_texture` を使う。
    ///
    /// Whatever the chain settles on is checked against what the texture was made to show before
    /// it is handed back. Each cache below judges its own entry, and each has to be taught identity
    /// separately - which is how a composite belonging to another document came to be presented
    /// while every store involved considered itself correct. Asking the texture covers all of them
    /// at once, including ones added later. A mismatch is refused rather than displayed: the page
    /// falls back to a holdover or a loading state, and the viewer tells the user to restart.
    pub(crate) fn resolve_fs_display_tex(
        &self,
        idx: usize,
        include_thumb: bool,
    ) -> Option<egui::TextureHandle> {
        let texture = self.resolve_fs_display_tex_from_caches(idx, include_thumb)?;
        self.display_texture_matches_page(&texture, idx)
            .then_some(texture)
    }

    fn resolve_fs_display_tex_from_caches(
        &self,
        idx: usize,
        include_thumb: bool,
    ) -> Option<egui::TextureHandle> {
        if self.fs_entry_is_animated(idx) {
            return self.current_animated_frame_texture(idx);
        }
        // comic 注釈は最前面 (D1)。holdover / display-tex 解決でも最優先で拾う。
        if let Some(tex) = self.current_comic_composite_texture(idx) {
            return Some(tex);
        }
        if let Some(tex) = self.current_final_composite_texture(idx) {
            return Some(tex);
        }
        // カラー化または Creative LUT で実際に見た目が変わるページでは、raw / edit /
        // thumbnail を「表示可能な代替」として返さない。final-effect worker の完成前に
        // ここへ落ちると、ページ切替時に未適用画素が1フレームだけ露出する。
        // 通常ページ送りは別途、直前ページの holdover を使う。
        if self.colorize_display_requires_final_effect(idx) {
            return None;
        }
        if let Some(tex) = self.current_edit_result_texture(idx) {
            return Some(tex);
        }
        if let Some(entry) = self.conceal_cache.get(&idx) {
            if entry.generation == self.conceal_generation {
                return Some(entry.texture.clone());
            }
        }
        if let Some(tex) = self.current_local_adjust_texture(idx) {
            return Some(tex);
        }
        if let Some(tex) = self.current_erase_result_texture(idx) {
            return Some(tex);
        }
        match self.fs_cache.get(&idx) {
            Some(FsCacheEntry::Static { tex, .. }) => return Some(tex.clone()),
            Some(FsCacheEntry::Video { .. }) => {
                // 動画は native presenter が独立 HWND に描画するため、
                // ここから取り出せる egui TextureHandle はない。サムネイルへ
                // フォールバックする。
            }
            _ => {}
        }
        if include_thumb {
            if let Some(crate::grid_item::ThumbnailState::Loaded { tex, .. }) =
                self.thumbnails.get(idx)
            {
                return Some(tex.clone());
            }
        }
        None
    }

    pub(crate) fn fullscreen_paint_resource_for_texture(
        &self,
        idx: usize,
        texture: egui::TextureHandle,
    ) -> crate::gpu_lanczos::FullscreenPaintResource {
        let is_thumbnail = self.thumbnails.get(idx).is_some_and(|thumbnail| {
            matches!(thumbnail, ThumbnailState::Loaded { tex, .. } if tex.id() == texture.id())
        });
        if self.fs_entry_is_animated(idx) || is_thumbnail {
            crate::gpu_lanczos::FullscreenPaintResource::direct(texture)
        } else {
            crate::gpu_lanczos::FullscreenPaintResource::resampleable(
                idx,
                texture,
                crate::gpu_lanczos::FullscreenPaintSourceGeneration {
                    items: self.items_generation,
                    input: self.input_generation.get(&idx).copied().unwrap_or(0),
                },
            )
        }
    }

    pub(crate) fn prepare_fullscreen_paint_resource(
        &mut self,
        resource: &crate::gpu_lanczos::FullscreenPaintResource,
        logical_scale: f32,
        pixels_per_point: f32,
        visible_region: Option<crate::displayed_image_transform::VisibleRegionRequest>,
    ) -> crate::gpu_lanczos::FullscreenPaintResource {
        let post_filter = self.fullscreen_paint_post_filter(resource);
        self.prepare_fullscreen_paint_resource_with_filter(
            resource,
            logical_scale,
            pixels_per_point,
            visible_region,
            post_filter,
            true,
        )
    }

    fn fullscreen_paint_post_filter(
        &self,
        resource: &crate::gpu_lanczos::FullscreenPaintResource,
    ) -> crate::adjustment::PostFilter {
        if self.post_filter_bypassed {
            crate::adjustment::PostFilter::None
        } else {
            resource
                .page_idx()
                .map(|idx| self.effective_params(idx).post_filter)
                .unwrap_or(crate::adjustment::PostFilter::None)
        }
    }

    #[allow(clippy::too_many_arguments)]
    fn prepare_fullscreen_paint_resource_with_filter(
        &mut self,
        resource: &crate::gpu_lanczos::FullscreenPaintResource,
        logical_scale: f32,
        pixels_per_point: f32,
        visible_region: Option<crate::displayed_image_transform::VisibleRegionRequest>,
        post_filter: crate::adjustment::PostFilter,
        trace_current_item_key: bool,
    ) -> crate::gpu_lanczos::FullscreenPaintResource {
        let render_state = self.wgpu_render_state.clone();
        let (prepared, perf_event) = self.fs_lanczos_cache.resolve(
            render_state.as_ref(),
            resource,
            logical_scale,
            pixels_per_point,
            visible_region,
            post_filter,
            self.settings.downscale_smoothing_percent,
            self.settings.anime_upscale_source_limit,
        );
        if let Some(perf_event) = perf_event
            && crate::perf::is_enabled()
        {
            let key = trace_current_item_key
                .then(|| resource.page_idx().and_then(|idx| self.perf_item_key(idx)))
                .flatten();
            match perf_event {
                crate::gpu_lanczos::LanczosPerfEvent::Generated(stats) => {
                    // Every resampler branch shares one event name and is told apart by the
                    // scale_branch field. Splitting the name would let a log query written for
                    // one branch report zero for another and read as "nothing was generated" -
                    // which is how the upscale path was found to be dead in the first place.
                    crate::perf::event(
                        "gpu",
                        "lanczos_regenerate",
                        key.as_deref(),
                        self.input_seq,
                        &[
                            ("source_w", stats.source_size[0].into()),
                            ("source_h", stats.source_size[1].into()),
                            ("target_w", stats.target_size[0].into()),
                            ("target_h", stats.target_size[1].into()),
                            ("scale_branch", stats.scale_branch.as_str().into()),
                            (
                                "visible_source_x",
                                stats
                                    .visible_source_region
                                    .map(|region| region[0].into())
                                    .unwrap_or(serde_json::Value::Null),
                            ),
                            (
                                "visible_source_y",
                                stats
                                    .visible_source_region
                                    .map(|region| region[1].into())
                                    .unwrap_or(serde_json::Value::Null),
                            ),
                            (
                                "visible_source_w",
                                stats
                                    .visible_source_region
                                    .map(|region| region[2].into())
                                    .unwrap_or(serde_json::Value::Null),
                            ),
                            (
                                "visible_source_h",
                                stats
                                    .visible_source_region
                                    .map(|region| region[3].into())
                                    .unwrap_or(serde_json::Value::Null),
                            ),
                            ("smoothing_percent", stats.smoothing_percent.into()),
                            ("blur_factor", f64::from(stats.blur_factor).into()),
                            ("texture_fetches", stats.texture_fetches.into()),
                            ("encode_submit_cpu_ms", stats.encode_submit_cpu_ms.into()),
                            ("regeneration_count", stats.regeneration_count.into()),
                        ],
                    );
                }
                crate::gpu_lanczos::LanczosPerfEvent::UpscaleLimitFallback(stats) => {
                    crate::perf::event(
                        "gpu",
                        "lanczos_upscale_limit_fallback",
                        key.as_deref(),
                        self.input_seq,
                        &[
                            ("source_w", stats.source_size[0].into()),
                            ("source_h", stats.source_size[1].into()),
                            ("target_w", stats.target_size[0].into()),
                            ("target_h", stats.target_size[1].into()),
                            ("max_dimension", stats.max_dimension.into()),
                            ("max_pixels", stats.max_pixels.into()),
                            ("scale_branch", stats.scale_branch.as_str().into()),
                        ],
                    );
                }
            }
        }
        prepared
    }

    pub(crate) fn colorize_display_requires_final_effect(&self, idx: usize) -> bool {
        if self.post_filter_bypassed
            || self.fs_entry_is_animated(idx)
            || !matches!(
                self.items.get(idx),
                Some(GridItem::Image(_))
                    | Some(GridItem::ZipImage { .. })
                    | Some(GridItem::PdfPage { .. })
            )
        {
            return false;
        }

        let params = self.effective_params(idx);
        // Creative LUT もカラー化と同じ「色が変わる最終段」なので、LUT 単独のページでも待つ。
        // 待たないと LUT 未適用の絵が 1 フレーム見えてから色が変わる (ユーザー報告 2026-07-29)。
        //
        // 待っている間の Ctrl+↑↓ は捨てずに folder-nav の accumulator が受け取る
        // (`handle_fullscreen_ctrl_nav_context` の lock 分岐と `press_multiplicity`)。
        // 一度この gate を LUT から外したのは押下が捨てられていたためだが、原因は
        // accumulator 側にあり別途修正済み。
        if self.creative_lut_requires_final_effect(params) {
            return true;
        }
        match params.colorize.mode {
            crate::colorize::ColorizeMode::Disabled => false,
            crate::colorize::ColorizeMode::AllImages => true,
            // final AI is assumed not to flip near-monochrome applicability.
            // A color adjustment that changes the classifier input, or a
            // missing/stale full-size summary, remains conservatively gated.
            crate::colorize::ColorizeMode::MonochromeOnly => self
                .known_monochrome_only_applicability(idx, params)
                .unwrap_or(true),
        }
    }

    /// Perf trace 用に、実際に選ばれた fullscreen テクスチャの所有元を特定する。
    /// 通常時は呼ばれず、perf ログ有効時の診断だけで cache lookup を行う。
    fn fs_texture_source_for_trace(
        &self,
        idx: usize,
        texture: &egui::TextureHandle,
        provenance: FsDisplayUnitPageProvenance,
    ) -> &'static str {
        let texture_id = texture.id();
        if provenance == FsDisplayUnitPageProvenance::Holdover {
            return "holdover";
        }
        if self.is_passthrough_rendition_texture(texture) {
            return "thumbnail";
        }
        if self
            .current_comic_composite_texture(idx)
            .is_some_and(|tex| tex.id() == texture_id)
        {
            return "final_comic_composite";
        }
        if self
            .current_final_composite_texture(idx)
            .is_some_and(|tex| tex.id() == texture_id)
        {
            return "final_composite";
        }
        if self
            .current_edit_result_texture(idx)
            .is_some_and(|tex| tex.id() == texture_id)
        {
            return "edit";
        }
        if self.conceal_cache.get(&idx).is_some_and(|entry| {
            entry.generation == self.conceal_generation && entry.texture.id() == texture_id
        }) {
            return "conceal";
        }
        if self
            .current_local_adjust_texture(idx)
            .is_some_and(|tex| tex.id() == texture_id)
        {
            return "local_adjust";
        }
        if self
            .current_erase_result_texture(idx)
            .is_some_and(|tex| tex.id() == texture_id)
        {
            return "erase";
        }
        if self.fs_cache.get(&idx).is_some_and(|entry| match entry {
            FsCacheEntry::Static { tex, .. } => tex.id() == texture_id,
            FsCacheEntry::Animated {
                frames,
                current_frame,
                ..
            } => frames
                .get(*current_frame)
                .is_some_and(|(tex, _)| tex.id() == texture_id),
            FsCacheEntry::Video { .. } | FsCacheEntry::Failed => false,
        }) {
            return "fs_cache";
        }
        if self.thumbnails.get(idx).is_some_and(|thumbnail| {
            matches!(thumbnail, ThumbnailState::Loaded { tex, .. } if tex.id() == texture_id)
        }) {
            return "thumbnail";
        }
        "processed_other"
    }

    /// `perf` JSONL に「その描画で実際に選んだ供給元」を残す。
    /// 通常実行では `perf::is_enabled()` の早期 return だけで、ログ I/O は発生しない。
    fn trace_fs_texture_choice(
        &self,
        branch: &'static str,
        source: &'static str,
        idx: Option<usize>,
        texture: &egui::TextureHandle,
    ) {
        if !crate::perf::is_enabled() {
            return;
        }
        let held_page = self
            .fs_holdover_tex
            .as_ref()
            .and_then(|holdover| holdover.page_for_texture_id(texture.id()));
        let key = match held_page {
            Some(page) => page.trace_key.clone(),
            None => idx.and_then(|idx| self.perf_item_key(idx)),
        };
        crate::perf::event(
            "fs",
            "texture_choice",
            key.as_deref(),
            self.input_seq,
            &[
                ("branch", serde_json::Value::from(branch)),
                ("source", serde_json::Value::from(source)),
                (
                    "idx",
                    idx.map(|idx| serde_json::Value::from(idx as u64))
                        .unwrap_or(serde_json::Value::Null),
                ),
                (
                    "items_generation",
                    serde_json::Value::from(self.items_generation),
                ),
                (
                    "locked_generation",
                    self.fs_nav_locked_gen
                        .map(serde_json::Value::from)
                        .unwrap_or(serde_json::Value::Null),
                ),
                (
                    "texture_id",
                    serde_json::Value::from(format!("{:?}", texture.id())),
                ),
            ],
        );
    }

    /// Record every page slot drawn in continuous reading, with the texture it actually used.
    ///
    /// The existing `continuous_page` trace only fires when the drawn texture matches a page
    /// transition, so an ordinary slot leaves no record at all. That is why a report of "the
    /// first page shows the previous document while the rest are correct" could not be located:
    /// index 0 simply stopped appearing in the trace while 1 and 2 continued, and there was
    /// nothing to say what index 0 was drawing instead.
    ///
    /// `key` is resolved the same way `trace_fs_texture_choice` resolves it - through the holdover
    /// if this texture is one the holdover owns - so a slot drawing a held page from another
    /// document names that document rather than the one on screen.
    fn trace_fs_continuous_page_draw(&self, idx: usize, texture: Option<&egui::TextureHandle>) {
        if !crate::perf::is_enabled() {
            return;
        }
        let held_page = texture.and_then(|texture| {
            self.fs_holdover_tex
                .as_ref()
                .and_then(|holdover| holdover.page_for_texture_id(texture.id()))
        });
        let from_holdover = held_page.is_some();
        let key = match held_page {
            Some(page) => page.trace_key.clone(),
            None => self.perf_item_key(idx),
        };
        crate::perf::event(
            "fs",
            "continuous_draw",
            key.as_deref(),
            self.input_seq,
            &[
                ("idx", serde_json::Value::from(idx as u64)),
                (
                    "items_generation",
                    serde_json::Value::from(self.items_generation),
                ),
                ("from_holdover", serde_json::Value::from(from_holdover)),
                (
                    "texture_id",
                    texture
                        .map(|texture| serde_json::Value::from(format!("{:?}", texture.id())))
                        .unwrap_or(serde_json::Value::Null),
                ),
            ],
        );
    }

    pub(crate) fn fs_display_unit_page_indices(&mut self, idx: usize) -> Vec<usize> {
        match self.resolve_spread_pair(idx) {
            SpreadPair::Single => vec![idx],
            SpreadPair::Double { left, right } => vec![left, right],
        }
    }

    pub(crate) fn capture_fs_display_unit(&mut self, idx: usize) -> Option<FsDisplayUnitHoldover> {
        self.capture_fs_display_unit_with_rendition(None, idx)
    }

    fn capture_fs_navigation_display_unit(
        &mut self,
        ctx: &egui::Context,
        idx: usize,
    ) -> Option<FsDisplayUnitHoldover> {
        let visible_pair = self.resolve_visible_spread_pair(idx);
        self.capture_fs_display_unit_with_rendition_for_pair(Some(ctx), idx, visible_pair)
    }

    fn capture_fs_display_unit_with_rendition(
        &mut self,
        rendition_ctx: Option<&egui::Context>,
        idx: usize,
    ) -> Option<FsDisplayUnitHoldover> {
        let pair = self.resolve_spread_pair(idx);
        self.capture_fs_display_unit_with_rendition_for_pair(rendition_ctx, idx, pair)
    }

    fn capture_fs_display_unit_with_rendition_for_pair(
        &mut self,
        rendition_ctx: Option<&egui::Context>,
        idx: usize,
        pair: SpreadPair,
    ) -> Option<FsDisplayUnitHoldover> {
        match pair {
            SpreadPair::Single => {
                let rotation = self.get_rotation(idx);
                let trim = rotation
                    .is_none()
                    .then(|| self.view_trim_single_content_bbox(idx))
                    .flatten();
                let content_bbox = self.fs_page_content_bbox(idx, rotation, trim);
                let page =
                    self.capture_fs_display_unit_page(rendition_ctx, idx, rotation, content_bbox)?;
                Some(FsDisplayUnitHoldover { pages: vec![page] })
            }
            SpreadPair::Double { left, right } => {
                let left_rotation = self.get_rotation(left);
                let right_rotation = self.get_rotation(right);
                let (left_content_bbox, right_content_bbox) =
                    if left_rotation.is_none() && right_rotation.is_none() {
                        self.view_trim_spread_content_bboxes(left, right)
                    } else {
                        (
                            if left_rotation.is_none() {
                                self.view_trim_spread_content_bbox(
                                    left,
                                    crate::view_trim::ViewTrimSpreadSide::Left,
                                )
                            } else {
                                None
                            },
                            if right_rotation.is_none() {
                                self.view_trim_spread_content_bbox(
                                    right,
                                    crate::view_trim::ViewTrimSpreadSide::Right,
                                )
                            } else {
                                None
                            },
                        )
                    };
                let left_page = self.capture_fs_display_unit_page(
                    rendition_ctx,
                    left,
                    left_rotation,
                    left_content_bbox,
                )?;
                let right_page = self.capture_fs_display_unit_page(
                    rendition_ctx,
                    right,
                    right_rotation,
                    right_content_bbox,
                )?;
                Some(FsDisplayUnitHoldover {
                    pages: vec![left_page, right_page],
                })
            }
        }
    }

    fn capture_fs_display_unit_page(
        &mut self,
        rendition_ctx: Option<&egui::Context>,
        idx: usize,
        rotation: crate::rotation_db::Rotation,
        content_bbox: Option<egui::Rect>,
    ) -> Option<FsDisplayUnitHoldoverPage> {
        let texture = self.resolve_fs_display_tex(idx, true).or_else(|| {
            rendition_ctx.and_then(|ctx| self.ensure_passthrough_rendition(ctx, idx))
        })?;
        let texture = self.fullscreen_paint_resource_for_texture(idx, texture);
        let source_size = self
            .source_dims_for_idx(idx)
            .map(|(width, height)| egui::vec2(width, height));
        let layout_size = self
            .fs_page_layout_source_size(idx)
            .or(source_size)
            .unwrap_or_else(|| texture.size_vec2());
        let post_filter = self.fullscreen_paint_post_filter(&texture);
        let trace_key = self.perf_item_key(idx);
        let trace_load_seq = self
            .fs_cache
            .get(&idx)
            .map(|entry| entry.load_seq())
            .unwrap_or(0);
        Some(FsDisplayUnitHoldoverPage {
            idx,
            texture,
            rotation,
            layout_size,
            post_filter,
            trace_key,
            trace_load_seq,
            source_size,
            content_bbox,
        })
    }

    pub(crate) fn clear_final_effect_source_reload_holdover(&mut self) {
        if matches!(
            self.fs_holdover_tex,
            Some(FsHoldover::FinalEffectSourceReload(_))
        ) {
            self.fs_holdover_tex = None;
        }
    }

    /// 同じ表示ユニットの source reload 中に、旧 final-effect 表示を出すかを原子的に決める。
    /// 見開きは両ページが表示可能になるまで旧 unit を維持し、両方が揃った
    /// frame で typed state を解放して一括で切り替える。
    pub(crate) fn final_effect_source_reload_holdover_for_draw(
        &mut self,
        fs_idx: usize,
        spread_pair: SpreadPair,
        original_preview_active: bool,
    ) -> Option<FsDisplayUnitHoldover> {
        if !self.reading_flow.is_paged()
            || self.fs_display_bypasses_final_pipeline(original_preview_active)
        {
            return None;
        }

        let (target_idx, previous) = match self.fs_holdover_tex.as_ref() {
            Some(FsHoldover::FinalEffectSourceReload(holdover)) => {
                (holdover.target_idx, holdover.previous.clone())
            }
            _ => return None,
        };
        if target_idx != fs_idx {
            self.clear_final_effect_source_reload_holdover();
            return None;
        }

        let target_pages = match spread_pair {
            SpreadPair::Single => vec![fs_idx],
            SpreadPair::Double { left, right } => vec![left, right],
        };
        if !target_pages
            .iter()
            .any(|&idx| self.colorize_display_requires_final_effect(idx))
        {
            self.clear_final_effect_source_reload_holdover();
            return None;
        }

        let target_unit_ready = target_pages.iter().all(|&idx| {
            self.resolve_fs_display_tex(idx, true).is_some()
                || matches!(self.fs_cache.get(&idx), Some(FsCacheEntry::Failed))
        });
        if target_unit_ready {
            self.clear_final_effect_source_reload_holdover();
            None
        } else {
            Some(previous)
        }
    }

    /// 現在 fullscreen 表示中の画像 (Static) が透過 (alpha<255) を含むか。
    /// 透過がある画像でのみ Shift+B の背景切替が意味を持つ (不透明画像は背景が画像の裏に
    /// 隠れて見た目が変わらない)。Static 以外 (アニメ / 動画 / 未ロード) は判定せず `true` を
    /// 返し、従来どおり切替を許可する (誤って無効化しないため)。
    pub(crate) fn fs_image_has_alpha(&self, idx: usize) -> bool {
        match self.fs_cache.get(&idx) {
            Some(FsCacheEntry::Static { pixels, .. }) => pixels.pixels.iter().any(|p| p.a() < 255),
            _ => true,
        }
    }

    /// 元画像表示の ModifierHold が成立している間だけ、mIV 側の派生表示
    /// (補正 / AI / 消しゴム補完) を迂回して raw decode の元画像テクスチャを選ぶ。
    ///
    /// フォーカスは `ctx.input(|i| i.viewport().focused)` ではなく
    /// `self.fs_prev_focused` で確認する: この関数の呼び出し元
    /// `prepare_fullscreen_state` は `show_viewport_immediate` の **外側** で
    /// 呼ばれているので、ここでの ctx はメインビューポートのもの = フルスクリーンが
    /// OS フォーカスを持っている間は常に `Some(false)` を返してしまう。
    /// `fs_prev_focused` はフルスクリーン viewport closure 内で毎フレーム更新される
    /// ので、フルスクリーン側の前フレーム focus 状態を反映する。`GetAsyncKeyState`
    /// 単体だと動画/アニメ駆動の repaint 中に他アプリの割り当てキーを拾うリスクがあるので、
    /// 必ずフォーカス gate と AND させる。
    ///
    /// Shift 検出も `ctx.input(|i| i.modifiers.shift)` ではなく OS API を使う。
    /// `prepare_fullscreen_state` は `show_viewport_immediate` の外側で呼ばれるため、
    /// ここでの ctx はメインビューポートのもの。フルスクリーンが OS フォーカスを
    /// 持っている間、メイン ctx の modifier event は届かない
    /// (= `i.modifiers.shift` が常に false)。元画像表示の修飾キー検出と同じ理由。
    fn original_preview_active(&self, ctx: &egui::Context, idx: usize) -> bool {
        // 比較表示中は元画像表示を無効にする (利用者判断 2026-08-13、§1.79)。
        //
        // 比較は加工済みピクセルから合成した対を描くので、元画像表示はもともと画面に効かない。
        // それでいて有効なままにすると、比較用 source が確定していない扱いになって
        // 「比較表示を準備中」トーストが出たり、組み上がった対が捨てられたりする。
        // 見た目が変わらないのに副作用だけ起きる状態なので、ここで断つ。
        //
        // 「ワイプを保ったまま両側を元画像にする」形にするなら §1.79 を実装する。
        // その場合はこの早期 return を外し、元画像版の対を用意する経路へ差し替える。
        if !matches!(self.compare_view_mode, crate::app::CompareViewMode::Off) {
            return false;
        }
        if self.fs_navigation_sequence_blocks_new_target() {
            // シーケンス進行中に画面へ出ているのは holdover (前の表示単位) であり、現ページでは
            // ない。「現ページの元画像を見せる」約束は対象が画面に無いので成立しない。
            //
            // 利用者判断 (2026-08-17): 元画像ホールドは静止して画像を見ているときに元を確認する
            // 用途である。移動中に補正が乗っていることは仕様として問題ない。
            return false;
        }
        let focus_viewport = if self.fullscreen_embedded_still_active() {
            ctx.viewport_id()
        } else {
            self.fullscreen_viewport_id()
        };
        #[cfg(windows)]
        if self
            .fs_page_turn_physical_input_for_frame(ctx, focus_viewport)
            .held
        {
            // A held page-turn input still means navigation between typed sequences. Showing the
            // original here would flicker and would also clear the burst through its blocker.
            return false;
        }
        if !self.fs_prev_focused {
            return false;
        }
        if self.any_modal_dialog_open_for_fullscreen_keys() {
            return false;
        }
        let Some(level_permit) = crate::keyboard_input::focused_key_state_permit_for_viewport(
            focus_viewport,
            self.fs_prev_focused,
        ) else {
            return false;
        };
        // この位置の ctx は main viewport のため、そこに残った FocusedUi/TextInput owner を
        // 元画像表示の抑止条件にはできない。実際の fullscreen focus と modal は上で明示的に
        // gate 済みなので、この呼び出しだけ keymap owner 判定を迂回して OS 状態を解決する。
        if !self.keymap.modifier_held_action_for_external_viewport(
            ctx,
            level_permit,
            KeyAction::FsOriginalPreviewHold,
        ) {
            return false;
        }
        // 補正レイヤー固有の Ctrl+Shift バイパスだけを優先する。元画像表示を
        // RightShift / Alt などへ変更した場合、Shift 単独で抑止してはならない。
        if self.local_adjust_mode
            && ctrl_held_via_os(level_permit)
            && shift_held_via_os(level_permit)
        {
            return false;
        }
        matches!(
            self.items.get(idx),
            Some(GridItem::Image(_))
                | Some(GridItem::ZipImage { .. })
                | Some(GridItem::PdfPage { .. })
        )
    }

    /// OS キー状態は同じ frame の producer gate / readiness / draw で一度だけ読む。
    /// egui の一時データなので viewer context をまたいだ状態は App に追加しない。
    fn original_preview_frame_observation(
        &self,
        ctx: &egui::Context,
        idx: usize,
    ) -> FsOriginalPreviewFrameObservation {
        let frame_nr = ctx.cumulative_frame_nr();
        let observed_pass_nr = ctx.cumulative_pass_nr();
        let viewport = if self.fullscreen_embedded_still_active() {
            ctx.viewport_id()
        } else {
            self.fullscreen_viewport_id()
        };
        let order_id = egui::Id::new(("fs_original_preview_call_order", viewport));
        let observed_call_order = ctx.data_mut(|data| {
            let mut order = data
                .get_temp::<FsOriginalPreviewFrameCallOrder>(order_id)
                .filter(|order| order.frame_nr == frame_nr)
                .unwrap_or(FsOriginalPreviewFrameCallOrder {
                    frame_nr,
                    next_call_order: 0,
                });
            order.next_call_order = order.next_call_order.saturating_add(1);
            data.insert_temp(order_id, order);
            order.next_call_order
        });
        let cache_id = egui::Id::new(("fs_original_preview_active", viewport));
        if let Some(sample) = ctx
            .data(|data| data.get_temp::<FsOriginalPreviewFrameSample>(cache_id))
            .filter(|sample| {
                sample.frame_nr == frame_nr
                    && sample.items_generation == self.items_generation
                    && sample.idx == idx
            })
        {
            return FsOriginalPreviewFrameObservation {
                sample,
                cache_hit: true,
                observed_frame_nr: frame_nr,
                observed_pass_nr,
                observed_call_order,
            };
        }

        let sequence_blocks_new_target_at_write = self.fs_navigation_sequence_blocks_new_target();
        let active = self.original_preview_active(ctx, idx);
        let sample = FsOriginalPreviewFrameSample {
            frame_nr,
            items_generation: self.items_generation,
            idx,
            active,
            written_pass_nr: observed_pass_nr,
            written_call_order: observed_call_order,
            sequence_blocks_new_target_at_write,
        };
        ctx.data_mut(|data| {
            data.insert_temp(cache_id, sample);
        });
        FsOriginalPreviewFrameObservation {
            sample,
            cache_hit: false,
            observed_frame_nr: frame_nr,
            observed_pass_nr,
            observed_call_order,
        }
    }

    fn original_preview_active_for_frame(&self, ctx: &egui::Context, idx: usize) -> bool {
        self.original_preview_frame_observation(ctx, idx)
            .sample
            .active
    }

    /// 現在の表示が final pipeline (補正 / AI / カラー化合成) を迂回するか。
    ///
    /// 元画像表示と分析モードは raw `fs_cache` を直接描くため、
    /// 描画側 (`resolve_fs_processed_texture`) と nav lock 解放側
    /// (`poll_fs_nav_lock`) は必ずこの述語を共有する。片方だけ更新すると
    /// 「表示は出ているのに lock が解放されない」型のデッドロックになる。
    ///
    /// `original_preview_active` は OS キー状態を読むため、呼び出し側で一度だけ
    /// 評価した値を渡す。
    fn fs_display_bypasses_final_pipeline(&self, original_preview_active: bool) -> bool {
        original_preview_active || self.analysis_mode
    }

    /// Gated: continuous reading and the detached snapshot both take this straight to the screen.
    fn resolve_original_preview_tex(&self, idx: usize) -> Option<egui::TextureHandle> {
        let texture = match self.fs_cache.get(&idx) {
            Some(FsCacheEntry::Static { tex, .. }) => Some(tex.clone()),
            _ => self.current_animated_frame_texture(idx),
        }?;
        self.display_texture_matches_page(&texture, idx)
            .then_some(texture)
    }

    /// 編集プレビューの下地になる source 解像度レイヤを解決する。
    fn resolve_fs_pre_overlay_texture(&self, idx: usize) -> Option<egui::TextureHandle> {
        match self.fs_cache.get(&idx) {
            Some(FsCacheEntry::Static { tex, .. }) => Some(tex.clone()),
            _ => self.current_animated_frame_texture(idx),
        }
    }

    /// 補正レイヤー直前の source 解像度入力テクスチャを解決する。
    /// 優先順: erase result → raw fs。
    fn resolve_local_adjust_source_texture(
        &mut self,
        ctx: &egui::Context,
        idx: usize,
    ) -> Option<egui::TextureHandle> {
        if let Some(tex) = self.ensure_erase_result_texture(ctx, idx) {
            return Some(tex);
        }
        if self.mask_pages.contains(&idx) {
            return None;
        }
        self.resolve_fs_pre_overlay_texture(idx)
    }

    /// フルスクリーン描画で使う最終表示テクスチャを解決する共通入口。
    ///
    /// 単ページ / 見開き / ルーペの全てがここを通ることで、加工レイヤを追加した
    /// ときの横展開漏れを防ぐ。通常表示は edit result に AdjustParams / AI /
    /// post_filter を最終段で適用した final composite を使う。
    ///
    /// 注意: 本関数は `prepare_fullscreen_state` 経由でメインビューポート ctx が
    /// 渡される経路がある。Modifier 状態は `ctx.input(|i| i.modifiers)` ではなく
    /// 必ず `*_held_via_os()` 系で取ること。
    ///
    /// Like [`Self::resolve_fs_display_tex`], whatever this settles on is checked against what the
    /// texture was made to show before it is handed back. Both resolvers are gated because both
    /// reach the screen: this one is the ordinary single-page, spread and continuous-reading path,
    /// and the other one covers holdover capture and the fallbacks. See
    /// [`crate::item_identity::TextureIdentityLedger`].
    pub(crate) fn resolve_fs_processed_texture(
        &mut self,
        ctx: &egui::Context,
        idx: usize,
        original_preview_active: bool,
    ) -> Option<egui::TextureHandle> {
        let texture =
            self.resolve_fs_processed_texture_from_caches(ctx, idx, original_preview_active)?;
        self.display_texture_matches_page(&texture, idx)
            .then_some(texture)
    }

    fn resolve_fs_processed_texture_from_caches(
        &mut self,
        ctx: &egui::Context,
        idx: usize,
        original_preview_active: bool,
    ) -> Option<egui::TextureHandle> {
        let is_video = matches!(self.items.get(idx), Some(GridItem::Video(_)));
        if is_video {
            return None;
        }
        if self.fs_entry_is_animated(idx) {
            return self.current_animated_frame_texture(idx);
        }
        // Z 分析モードは AI / 補正 / 注釈 / 隠蔽 / 消しゴム / 局所補正をすべてバイパスして
        // **raw 元画像**を表示する (original preview と同じ経路)。分析パネルの色取得・
        // ヒストグラム・グレースケール/拡大鏡オーバーレイは raw fs_cache を読むので、表示も raw に
        // 揃えることで「クリックした見た目の色 = 分析値」が一致する (Codex 指摘 + ユーザー要望)。
        if self.fs_display_bypasses_final_pipeline(original_preview_active) {
            return self.resolve_original_preview_tex(idx);
        }

        if self.erase_mode {
            if !self.erase_preview_active {
                return self.ensure_erase_base_texture(ctx, idx);
            }
            let preview_tex = self
                .erase_preview_cache
                .get(&idx)
                .map(|e| e.texture.clone());
            return preview_tex
                .or_else(|| self.resolve_fs_pre_overlay_texture(idx))
                .or_else(|| self.ensure_erase_base_texture(ctx, idx));
        }

        if self.local_adjust_mode {
            // 判定は副作用ゼロの `decide_local_adjust_preview_action` に集約 (= unit
            // test できる)。caller である本関数は OS API 読み・cache lookup・worker
            // spawn・source texture フォールバックの責務だけを持つ。
            //
            // `prepare_fullscreen_state` 経由では ctx がメインビューポートのものになり、
            // フルスクリーンが OS フォーカスを持つ間は modifier event が届かないため、
            // `original_preview_active` と同じく OS キー状態を見る (fs_prev_focused
            // ガードは decide 関数内に集約済み)。
            self.maybe_start_local_adjust_render(idx);
            let total_layers = self
                .local_adjust_page_layers
                .get(&idx)
                .map(|layers| layers.len())
                .unwrap_or(0);
            let focus_viewport = if self.fullscreen_embedded_still_active() {
                ctx.viewport_id()
            } else {
                self.fullscreen_viewport_id()
            };
            let level_permit = crate::keyboard_input::focused_key_state_permit_for_viewport(
                focus_viewport,
                self.fs_prev_focused,
            );
            let action = decide_local_adjust_preview_action(
                self.fs_prev_focused,
                level_permit.is_some_and(ctrl_held_via_os),
                level_permit.is_some_and(shift_held_via_os),
                self.local_adjust_show_source,
                self.local_adjust_preview_to_selected_layer,
                total_layers > 0,
                self.selected_local_adjust_layer_idx(idx),
                total_layers,
            );
            match action {
                LocalAdjustPreviewAction::ShowSource => {
                    return self.resolve_local_adjust_source_texture(ctx, idx);
                }
                LocalAdjustPreviewAction::BypassLayer { layer_idx } => {
                    self.maybe_start_local_adjust_layer_bypass_preview(idx, layer_idx);
                    if let Some(tex) =
                        self.current_local_adjust_layer_bypass_texture(idx, layer_idx)
                    {
                        return Some(tex);
                    }
                    return self.resolve_local_adjust_source_texture(ctx, idx);
                }
                LocalAdjustPreviewAction::PrefixPreview { layer_count } => {
                    self.maybe_start_local_adjust_prefix_preview(idx, layer_count);
                    if let Some(tex) =
                        self.current_local_adjust_prefix_preview_texture(idx, layer_count)
                    {
                        return Some(tex);
                    }
                    return self.resolve_local_adjust_source_texture(ctx, idx);
                }
                LocalAdjustPreviewAction::FullComposite => {
                    if let Some(local_adjust_tex) = self.current_local_adjust_texture(idx) {
                        return Some(local_adjust_tex);
                    }
                    return self.resolve_local_adjust_source_texture(ctx, idx);
                }
            }
        }

        if self.conceal_mode && !self.conceal_preview_active {
            if let Some(local_adjust_tex) = self.current_local_adjust_texture(idx) {
                return Some(local_adjust_tex);
            }
            if let Some(erase_result_tex) = self.ensure_erase_result_texture(ctx, idx) {
                return Some(erase_result_tex);
            }
            return self.resolve_fs_pre_overlay_texture(idx);
        }

        // comic (テキスト注釈) は最前面 = パイプライン最終段 (D1)。注釈が無ければ
        // None なので素の final composite にフォールバック (非注釈画像はゼロ
        // オーバーヘッド・退行なし)。
        if let Some(comic) = self.ensure_comic_composite_texture(ctx, idx) {
            return Some(comic);
        }
        if let Some(texture) = self.ensure_final_composite_texture(ctx, idx) {
            return Some(texture);
        }
        if self.colorize_display_requires_final_effect(idx) {
            // raw / edit / unprocessed-thumbnail gate は維持する。ページ単位表示は
            // color-faithful rendition、source reload は display-unit holdover、
            // 連結読みは従来どおりページ別 transition が完成までを橋渡しする。
            return None;
        }
        self.resolve_fs_pre_overlay_texture(idx)
    }

    pub(crate) fn fs_navigation_sequence_blocks_new_target(&self) -> bool {
        self.fs_holdover_tex
            .as_ref()
            .and_then(FsHoldover::navigation_sequence)
            .is_some_and(FsNavigationSequence::blocks_new_target)
    }

    /// Record that a navigation request was dropped, and why.
    ///
    /// Dropping repeats while a target is unresolved is the intended behaviour, so this must not
    /// be noisy: it logs once per distinct blocking state, then only the running count. What it
    /// buys is the difference between "a target is taking a moment" and "a target can no longer
    /// retire", which is otherwise invisible from outside - the 2026-08-14 report was 14 inputs
    /// over 21.8 seconds with nothing in the log to say they had been refused.
    fn note_fullscreen_nav_request_dropped(&mut self) {
        let Some(sequence) = self
            .fs_holdover_tex
            .as_ref()
            .and_then(FsHoldover::navigation_sequence)
        else {
            return;
        };
        let signature = format!(
            "{} fs_idx={:?} items_generation={}",
            sequence.describe_block(),
            self.fullscreen_idx,
            self.items_generation
        );
        if self.fs_nav_dropped_block_signature.as_deref() == Some(signature.as_str()) {
            self.fs_nav_dropped_block_count += 1;
            // Powers of two keep a genuinely wedged sequence visible without flooding a log
            // during the ordinary case of a few repeats arriving inside one page turn.
            if self.fs_nav_dropped_block_count.is_power_of_two() {
                crate::logger::log(format!(
                    "[fs-nav] dropped {} requests against the same unresolved target: {signature}",
                    self.fs_nav_dropped_block_count
                ));
            }
            return;
        }
        self.fs_nav_dropped_block_signature = Some(signature.clone());
        self.fs_nav_dropped_block_count = 1;
        crate::logger::log(format!("[fs-nav] dropped request: {signature}"));
    }

    pub(crate) fn begin_fs_folder_navigation_sequence(
        &mut self,
        ctx: &egui::Context,
        fs_idx: usize,
    ) {
        let previous = self
            .fs_holdover_tex
            .as_ref()
            .and_then(FsHoldover::navigation_sequence)
            .filter(|sequence| !sequence.blocks_new_target())
            .and_then(|sequence| sequence.previous.clone())
            .or_else(|| self.capture_fs_navigation_display_unit(ctx, fs_idx));
        self.fs_holdover_tex = Some(FsHoldover::NavigationSequence(FsNavigationSequence {
            previous,
            opened_at: std::time::Instant::now(),
            target: FsNavigationSequenceTarget::FolderItems {
                accepted_generation: self.items_generation,
            },
        }));
        self.fs_nav_locked_gen = Some(self.items_generation);
    }

    fn begin_fs_page_navigation_sequence(
        &mut self,
        ctx: &egui::Context,
        current_idx: usize,
        target_idx: usize,
        accept_rendition: bool,
    ) -> bool {
        if self.continuous_reading_active_for_idx(current_idx) {
            return true;
        }
        if self.fs_navigation_sequence_blocks_new_target() {
            return false;
        }
        let mut pages = self.fs_display_unit_page_indices(target_idx);
        pages.sort_unstable();
        if pages
            .iter()
            .any(|page| !self.items.get(*page).is_some_and(GridItem::has_page_data))
        {
            // A Display target is retired only by the page renderer's presentation trace.
            // Native media presenters never emit that trace, so opening a sequence for a unit
            // they own would leave every later page-navigation target blocked permanently.
            return true;
        }
        let previous = self
            .fs_holdover_tex
            .as_ref()
            .and_then(FsHoldover::navigation_sequence)
            .and_then(|sequence| sequence.previous.clone())
            .or_else(|| self.capture_fs_navigation_display_unit(ctx, current_idx));
        self.fs_holdover_tex = Some(FsHoldover::NavigationSequence(FsNavigationSequence {
            previous,
            opened_at: std::time::Instant::now(),
            target: FsNavigationSequenceTarget::Display(FsNavigationDisplayTarget {
                items_generation: self.items_generation,
                pages,
                phase: FsNavigationTargetPhase::Awaiting { accept_rendition },
            }),
        }));
        true
    }

    pub(crate) fn bind_fs_navigation_sequence_to_current_target(&mut self) -> bool {
        let Some(idx) = self.fullscreen_idx else {
            return false;
        };
        let awaiting_folder = self
            .fs_holdover_tex
            .as_ref()
            .and_then(FsHoldover::navigation_sequence)
            .is_some_and(|sequence| {
                matches!(
                    sequence.target,
                    FsNavigationSequenceTarget::FolderItems { .. }
                )
            });
        if !awaiting_folder {
            return false;
        }
        let mut pages = self.fs_display_unit_page_indices(idx);
        pages.sort_unstable();
        if pages
            .iter()
            .any(|page| !self.items.get(*page).is_some_and(GridItem::has_page_data))
        {
            let previous = self
                .fs_holdover_tex
                .as_ref()
                .and_then(FsHoldover::navigation_sequence)
                .and_then(|sequence| sequence.previous.clone());
            self.fs_holdover_tex = previous.map(FsHoldover::FolderNavigation);
            return false;
        }
        if let Some(sequence) = self
            .fs_holdover_tex
            .as_mut()
            .and_then(FsHoldover::navigation_sequence_mut)
        {
            sequence.target = FsNavigationSequenceTarget::Display(FsNavigationDisplayTarget {
                items_generation: self.items_generation,
                pages,
                phase: FsNavigationTargetPhase::Awaiting {
                    accept_rendition: true,
                },
            });
            return true;
        }
        false
    }

    fn resolve_fs_navigation_sequence_target(
        &mut self,
        ctx: &egui::Context,
        fs_idx: usize,
        original_preview_active: bool,
    ) {
        let Some(target) = self
            .fs_holdover_tex
            .as_ref()
            .and_then(FsHoldover::navigation_sequence)
            .and_then(|sequence| match &sequence.target {
                FsNavigationSequenceTarget::Display(target) => Some(target.clone()),
                FsNavigationSequenceTarget::FolderItems { .. } => None,
            })
        else {
            return;
        };
        let accept_rendition = match target.phase {
            FsNavigationTargetPhase::Awaiting { accept_rendition } => accept_rendition,
            FsNavigationTargetPhase::RenditionFailed => false,
            FsNavigationTargetPhase::Ready(_) | FsNavigationTargetPhase::Presenting(_) => {
                return;
            }
        };
        if target.items_generation != self.items_generation || !target.pages.contains(&fs_idx) {
            return;
        }

        if accept_rendition {
            self.ensure_navigation_target_thumbnail_requests(ctx, &target.pages);
        }
        let bypasses_final_pipeline =
            self.fs_display_bypasses_final_pipeline(original_preview_active);
        let materialized_ready = target.pages.iter().all(|idx| {
            if bypasses_final_pipeline {
                // この frame は描画側も raw source を明示的に選ぶ。通常表示では下の final
                // pipeline gate を維持するため、白黒からカラーへの途中切替を見せない契約は
                // 緩めず、利用者が元画像を要求した frame だけ readiness source を揃える。
                self.resolve_original_preview_tex(*idx).is_some()
            } else {
                self.resolve_fs_display_tex(*idx, true).is_some()
                    || (!self.items.get(*idx).is_some_and(GridItem::has_page_data)
                        && matches!(
                            self.thumbnails.get(*idx),
                            Some(ThumbnailState::Loaded { .. })
                        ))
            }
        });
        let materialized_failed = target
            .pages
            .iter()
            .any(|idx| matches!(self.fs_cache.get(idx), Some(FsCacheEntry::Failed)));
        let rendition_ready = accept_rendition
            && target
                .pages
                .iter()
                .all(|idx| self.ensure_passthrough_rendition(ctx, *idx).is_some());
        let rendition_failed = accept_rendition
            && target
                .pages
                .iter()
                .any(|idx| matches!(self.thumbnails.get(*idx), Some(ThumbnailState::Failed)));

        let next_phase = navigation_target_next_phase(
            materialized_ready,
            rendition_ready,
            materialized_failed,
            rendition_failed,
        );
        // Which branch above won, recorded where all four inputs are still in scope.
        //
        // The decision probe downstream cannot tell these apart: it sees only
        // `passthrough_rendition_ready == false`, which is equally true of a target that resolved
        // to the real page and one that is still waiting for anything at all. Those are opposite
        // situations - the first is the fast path declining a stand-in it does not need, the
        // second is the stand-in failing to appear - and a report that renders them identically
        // is how a direction-dependent difference stayed invisible.
        if crate::perf::is_enabled() {
            crate::perf::event(
                "fs",
                "navigation_target_phase",
                self.perf_item_key(fs_idx).as_deref(),
                self.input_seq,
                &[
                    ("idx", serde_json::Value::from(fs_idx)),
                    (
                        "accept_rendition",
                        serde_json::Value::from(accept_rendition),
                    ),
                    (
                        "materialized_ready",
                        serde_json::Value::from(materialized_ready),
                    ),
                    ("rendition_ready", serde_json::Value::from(rendition_ready)),
                    (
                        "materialized_failed",
                        serde_json::Value::from(materialized_failed),
                    ),
                    (
                        "rendition_failed",
                        serde_json::Value::from(rendition_failed),
                    ),
                    (
                        "pages",
                        serde_json::Value::from(
                            target.pages.iter().copied().collect::<Vec<usize>>(),
                        ),
                    ),
                    (
                        "next_phase",
                        serde_json::Value::from(match next_phase {
                            Some(FsNavigationTargetPhase::Ready(
                                FsNavigationPresentation::Materialized,
                            )) => "ready_materialized",
                            Some(FsNavigationTargetPhase::Ready(
                                FsNavigationPresentation::Rendition,
                            )) => "ready_rendition",
                            Some(FsNavigationTargetPhase::Ready(
                                FsNavigationPresentation::Failure,
                            )) => "ready_failure",
                            Some(FsNavigationTargetPhase::RenditionFailed) => "rendition_failed",
                            Some(FsNavigationTargetPhase::Awaiting { .. })
                            | Some(FsNavigationTargetPhase::Presenting(_)) => "unchanged",
                            None => "still_awaiting",
                        }),
                    ),
                ],
            );
        }
        let Some(next_phase) = next_phase else {
            return;
        };
        let terminal_rendition_failure =
            matches!(next_phase, FsNavigationTargetPhase::RenditionFailed);
        if let Some(FsNavigationSequenceTarget::Display(current)) = self
            .fs_holdover_tex
            .as_mut()
            .and_then(FsHoldover::navigation_sequence_mut)
            .map(|sequence| &mut sequence.target)
            && *current == target
        {
            current.phase = next_phase;
            if terminal_rendition_failure {
                self.fs_nav_locked_gen = None;
            }
            ctx.request_repaint();
        }
    }

    fn fs_navigation_sequence_rendition_state(&self, fs_idx: usize) -> (bool, bool) {
        let Some(target) = self
            .fs_holdover_tex
            .as_ref()
            .and_then(FsHoldover::navigation_sequence)
            .and_then(|sequence| match &sequence.target {
                FsNavigationSequenceTarget::Display(target)
                    if target.items_generation == self.items_generation
                        && target.pages.contains(&fs_idx) =>
                {
                    Some(target)
                }
                FsNavigationSequenceTarget::FolderItems { .. }
                | FsNavigationSequenceTarget::Display(_) => None,
            })
        else {
            return (false, false);
        };
        match target.phase {
            FsNavigationTargetPhase::Awaiting {
                accept_rendition: true,
            } => (true, false),
            FsNavigationTargetPhase::Ready(FsNavigationPresentation::Rendition)
            | FsNavigationTargetPhase::Presenting(FsNavigationPresentation::Rendition) => {
                (true, true)
            }
            FsNavigationTargetPhase::Awaiting {
                accept_rendition: false,
            }
            | FsNavigationTargetPhase::Ready(_)
            | FsNavigationTargetPhase::Presenting(_)
            | FsNavigationTargetPhase::RenditionFailed => (false, false),
        }
    }

    pub(crate) fn fs_navigation_rendition_target_pages(&self, fs_idx: usize) -> Option<Vec<usize>> {
        self.fs_holdover_tex
            .as_ref()
            .and_then(FsHoldover::navigation_sequence)
            .and_then(|sequence| match &sequence.target {
                FsNavigationSequenceTarget::Display(target)
                    if target.items_generation == self.items_generation
                        && target.pages.contains(&fs_idx)
                        && matches!(
                            target.phase,
                            FsNavigationTargetPhase::Awaiting {
                                accept_rendition: true
                            } | FsNavigationTargetPhase::Ready(FsNavigationPresentation::Rendition)
                                | FsNavigationTargetPhase::Presenting(
                                    FsNavigationPresentation::Rendition
                                )
                        ) =>
                {
                    Some(target.pages.clone())
                }
                FsNavigationSequenceTarget::FolderItems { .. }
                | FsNavigationSequenceTarget::Display(_) => None,
            })
    }

    /// `fs_nav_locked_gen.is_some()` の薄いラッパー。
    /// 入力ハンドラ・描画パスから「現在 nav ロック中か」を簡潔に問い合わせるため。
    pub(crate) fn fs_nav_is_locked(&self) -> bool {
        self.fs_nav_locked_gen.is_some()
    }

    pub(crate) fn fs_nav_deferred_reopen_wait_active(&self) -> bool {
        self.fs_nav_after_pdf_enumerate.is_some()
            || self.archive_convert_deferred_fullscreen_active()
    }

    /// 描画側で使ってよい Ctrl+↑↓ nav holdover を返す。
    ///
    /// `fs_holdover_tex` は旧ページの見た目を一時的に残すビュー単位の状態。
    /// ページ枠の fallback には渡さず、描画側が `image_rect` 全体へ旧単ページ、または
    /// 画面順の旧見開き 2 ページを 1 unit としてオーバーレイする。
    fn fs_nav_holdover_decision(&self) -> FsNavHoldoverDecision {
        if let Some(sequence) = self
            .fs_holdover_tex
            .as_ref()
            .and_then(FsHoldover::navigation_sequence)
        {
            if let FsNavigationSequenceTarget::Display(target) = &sequence.target {
                match target.phase {
                    FsNavigationTargetPhase::Ready(presentation) => {
                        return FsNavHoldoverDecision::TargetReady(presentation);
                    }
                    FsNavigationTargetPhase::Presenting(_) => {
                        return FsNavHoldoverDecision::Unavailable;
                    }
                    FsNavigationTargetPhase::Awaiting { .. }
                    | FsNavigationTargetPhase::RenditionFailed => {}
                }
            }
            return sequence
                .previous
                .clone()
                .map(FsNavHoldoverDecision::Draw)
                .unwrap_or(FsNavHoldoverDecision::Unavailable);
        }
        let Some(locked_gen) = self.fs_nav_locked_gen else {
            return FsNavHoldoverDecision::Unavailable;
        };
        if let Some(idx) = self.fullscreen_idx
            && self.items_generation > locked_gen
        {
            // 新フォルダの items が入り、新しい `fullscreen_idx` も有効になった後。
            // ここで holdover を即座に切ると、新 idx の full / サムネがまだデコード
            // できていない数フレームの間が黒 / loading になる。borderless 全画面では
            // 目立たないが、装飾付きの detached window では「次のファイルへ移るたびに
            // 一瞬ちらつく」症状になる (v2.2.0 比の体感差。詳細は
            // docs/detached-viewer-lifecycle-redesign-proposal.md)。
            //
            // 新 idx の表示物が用意できた / デコード失敗が確定した時点で
            // ビュー単位の holdover overlay を止める。それまでは旧ビューを
            // 1 display unit として維持して黒を挟まず滑らかに繋ぐ。
            let new_content_ready = self.resolve_fs_display_tex(idx, true).is_some();
            let new_content_failed = matches!(self.fs_cache.get(&idx), Some(FsCacheEntry::Failed));
            if new_content_ready || new_content_failed {
                return FsNavHoldoverDecision::TargetReady(FsNavigationPresentation::Materialized);
            }
        }
        self.fs_holdover_tex
            .as_ref()
            .and_then(FsHoldover::folder_navigation_display_unit)
            .cloned()
            .map(FsNavHoldoverDecision::Draw)
            .unwrap_or(FsNavHoldoverDecision::Unavailable)
    }

    /// 描画直前の呼び出しでは `TargetReady` を一方向ラッチへ変換する。
    /// readiness probe は `fs_nav_holdover_without_latching` を使い、実描画前に
    /// unit が所有する handle を破棄しない。
    pub(crate) fn fs_nav_holdover_for_draw(&mut self) -> Option<FsDisplayUnitHoldover> {
        match self.fs_nav_holdover_decision() {
            FsNavHoldoverDecision::TargetReady(presentation) => {
                if let Some(sequence) = self
                    .fs_holdover_tex
                    .as_mut()
                    .and_then(FsHoldover::navigation_sequence_mut)
                    && let FsNavigationSequenceTarget::Display(target) = &mut sequence.target
                    && matches!(target.phase, FsNavigationTargetPhase::Ready(_))
                {
                    target.phase = FsNavigationTargetPhase::Presenting(presentation);
                    if matches!(presentation, FsNavigationPresentation::Failure) {
                        self.fs_nav_locked_gen = None;
                        self.fs_holdover_tex = None;
                    }
                    return None;
                }
                // 一方向ラッチ: 新 generation の表示物を選べた描画フレームで旧フォルダの
                // texture handle 自体を破棄する。AI final の差し替えで次フレームの
                // resolve が一時的に None へ戻っても、旧画像を再選択できなくする。
                self.fs_holdover_tex = None;
                None
            }
            FsNavHoldoverDecision::Draw(unit) => Some(unit),
            FsNavHoldoverDecision::Unavailable => None,
        }
    }

    fn fs_nav_holdover_without_latching(&self) -> Option<FsDisplayUnitHoldover> {
        match self.fs_nav_holdover_decision() {
            FsNavHoldoverDecision::Draw(unit) => Some(unit),
            FsNavHoldoverDecision::Unavailable | FsNavHoldoverDecision::TargetReady(_) => None,
        }
    }

    /// nav ロックと holdover を強制解除する。`poll_fs_nav_lock` の通常解除条件
    /// (items_generation 進行 + 新ページの tex 用意) に到達しないケース
    /// (DFS が境界に当たって path=None / 画像・動画フォルダに着地できず !hit_image_folder /
    /// ユーザーが Esc でフルスクリーンを抜けて DFS をキャンセル) で明示的に呼ぶ。
    /// これをやらないと `fs_nav_locked_gen` が永続化して以降の Ctrl+↑↓ がすべて
    /// 無視される (Codex P1)。
    pub(crate) fn release_fs_nav_lock(&mut self) {
        self.fs_nav_locked_gen = None;
        self.fs_holdover_tex = None;
        // The dedup describes the sequence being released, so the next block is reported afresh
        // instead of being folded into this one's running count.
        self.fs_nav_dropped_block_signature = None;
        self.fs_nav_dropped_block_count = 0;
        #[cfg(windows)]
        {
            self.detached_viewer_folder_nav_reuse_window_once = false;
        }
    }

    /// Ctrl+↑↓ ナビ発火直前に `fs_holdover_tex` を仕込み、`items_generation` を
    /// ロック取得時点で記録する。ナビによる items 入れ替えで fs_cache が drop されても、
    /// ロック解除まで holdover Arc を Render パスから参照することで画面が真っ白に
    /// なるのを防ぐ。`items_generation` のスナップショットは `poll_fs_nav_lock` の
    /// 「items が入れ替わる前にロックを解除しない」判定に使う。
    pub(crate) fn capture_fs_nav_holdover(&mut self, fs_idx: usize) {
        self.fs_holdover_tex = self
            .capture_fs_display_unit(fs_idx)
            .map(FsHoldover::FolderNavigation);
        self.fs_nav_locked_gen = Some(self.items_generation);
    }

    /// 毎フレーム呼び出され、ナビロックの解除条件を満たしたら lock を解除する。
    /// 解除条件: ① items が入れ替わって `items_generation` が進んだ
    /// (= `install_new_items` で新フォルダの items が導入された) かつ
    /// ② 現表示が final pipeline を使うカラー化ページなら complete composite が、
    /// pipeline を迂回する元画像表示 / 分析モードまたはカラー化なしなら
    /// thumbnail / raw fs_cache が表示可能になった状態。
    /// 「items が進む前」(= 旧ページがロード済み判定で誤って解除される) のを
    /// items_generation チェックで防ぐ。
    pub(crate) fn poll_fs_nav_lock(&mut self, ctx: &egui::Context) {
        if let Some(sequence) = self
            .fs_holdover_tex
            .as_ref()
            .and_then(FsHoldover::navigation_sequence)
        {
            let accepted_generation = match sequence.target {
                FsNavigationSequenceTarget::FolderItems {
                    accepted_generation,
                } => Some(accepted_generation),
                FsNavigationSequenceTarget::Display(_) => None,
            };
            if let Some(accepted_generation) = accepted_generation {
                if self.items_generation <= accepted_generation {
                    return;
                }
                if self.fullscreen_idx.is_none() {
                    if self.fs_nav_deferred_reopen_wait_active() {
                        return;
                    }
                    self.release_fs_nav_lock();
                    return;
                }
                self.bind_fs_navigation_sequence_to_current_target();
            }
            if let Some(idx) = self.fullscreen_idx {
                let original_preview_active = self.original_preview_active_for_frame(ctx, idx);
                self.resolve_fs_navigation_sequence_target(ctx, idx, original_preview_active);
            }
            return;
        }
        let Some(locked_gen) = self.fs_nav_locked_gen else {
            return;
        };
        // items_generation が進んでいない = まだ items 入れ替えが起きていない
        // (または確認なしアーカイブ変換中) ので旧 fs_idx のテクスチャが残っているのは
        // 当然。ここで解除すると holdover が失われて一覧/黒画面が露出するので保留する。
        if self.items_generation <= locked_gen {
            return;
        }
        let Some(idx) = self.fullscreen_idx else {
            // 通常は `apply_folder_nav_result` 内で close_fullscreen → open_fullscreen が
            // 同フレームで連続実行されるので fs_idx は Some に戻る。例外は **PDF/ZIP の
            // async enumerate 待ち**: PDF メタキャッシュ hit で `try_apply_pdf_meta_cache`
            // が placeholder grid を install (= items_generation++) するが、
            // `reopen_fullscreen_after_folder_nav_load` は `pdf_enumerate_pending` が
            // 残っているため "enumerate_defer" で抜け、fullscreen_idx は None のまま
            // 数フレーム経過する。この window で holdover を解放してしまうと、
            // `keep_fullscreen_viewport_alive` (viewport mode) と
            // `render_embedded_fs_nav_holdover` (in-window mode) の defer 描画から
            // 直前ページ画像が消えて真っ黒のフラッシュになる。
            // `fs_nav_deferred_reopen_wait_active` の間はユーザーがフルスクリーン
            // 継続を意図しているので、解除を保留して deferred reopen 完了まで待つ。
            if self.fs_nav_deferred_reopen_wait_active() {
                return;
            }
            // 上記以外で fullscreen_idx = None = ユーザーが Esc 等で抜けた。
            self.fs_nav_locked_gen = None;
            self.fs_holdover_tex = None;
            return;
        };
        let has_full = matches!(
            self.fs_cache.get(&idx),
            Some(FsCacheEntry::Static { .. })
                | Some(FsCacheEntry::Animated { .. })
                | Some(FsCacheEntry::Video { .. })
        );
        let has_thumb = matches!(
            self.thumbnails.get(idx),
            Some(crate::grid_item::ThumbnailState::Loaded { .. })
        );
        // 新 idx のデコードが失敗確定 (Failed) の場合も lock を解放する。さもないと
        // holdover (旧画像) が残り続け、以降の Ctrl+↑↓ が lock でブロックされる。
        let has_failed = matches!(self.fs_cache.get(&idx), Some(FsCacheEntry::Failed));
        let original_preview_active = self.original_preview_active_for_frame(ctx, idx);
        let requires_final_effect = !self
            .fs_display_bypasses_final_pipeline(original_preview_active)
            && self.colorize_display_requires_final_effect(idx);
        let display_ready = if requires_final_effect {
            self.resolve_fs_display_tex(idx, true).is_some()
                && self.current_final_composite_is_complete(idx)
        } else {
            has_full || has_thumb
        };
        if display_ready || has_failed {
            self.fs_nav_locked_gen = None;
            self.fs_holdover_tex = None;
        }
    }

    /// フルスクリーン通常モードのズーム/パンが有効なら返す。
    /// 閾値以下なら None (描画側で無変換パスに流れるよう明示するため)。
    pub(crate) fn fs_zoom_pan(&self) -> Option<(f32, egui::Vec2)> {
        if self.fs_zoom > ZOOM_NEAR_ONE || self.fs_pan.length_sq() > PAN_EPSILON_SQ {
            Some((self.fs_zoom, self.fs_pan))
        } else {
            None
        }
    }

    /// ZipPla 風全画面ズームモードが何らかの形で動作中か (照準 or ズーム+パン中)。
    pub(crate) fn fs_zoom_mode_engaged(&self) -> bool {
        self.fs_zoom_active || self.fs_zoom_aiming
    }

    /// フルスクリーンの現ページが FsVideo コンテキストか (動画 / 音声 / 動画→音声モード)。
    ///
    /// keymap は同じキーを FsImage と FsVideo の両方へ割り当てても衝突扱いしない
    /// (既定の Z = `FsZoomMode` / `VideoToggleAudioMode`、keymap.rs の default_chords 参照)。
    /// 実行時に「今どちらのコンテキストか」を表す状態は無いので、キーを消費する側が
    /// 自分の所有でないキーを取らないためにこれを見る。
    fn fs_video_key_context_active(&self, fs_idx: usize) -> bool {
        matches!(
            self.items.get(fs_idx),
            Some(GridItem::Video(_)) | Some(GridItem::Audio(_))
        )
    }

    fn fs_zoom_mode_context_ok(&self, fs_idx: usize) -> bool {
        self.reading_flow.is_paged()
            && !self.is_panorama_mode_active(fs_idx)
            && !self.analysis_mode
            // 消しゴム / 補正レイヤー / 隠蔽 / 切り取り / 注釈 をまとめて除外 (Codex P2: 切り取り
            // モード漏れ防止のため手書き列挙でなく is_overlay_edit_mode_active を使う)。
            && !self.is_overlay_edit_mode_active()
            // 比較表示中は通常閲覧外 (Double では比較描画が優先され入力と表示がずれるため、Codex P3)。
            && matches!(self.compare_view_mode, crate::app::CompareViewMode::Off)
            // 音声 (音楽ビュー) も対象外。除外しないと Z (VideoToggleAudioMode の既定と同じキー) が
            // ここで fs_zoom_active をラッチし、音楽ビューでは見た目の変化がないまま
            // 次に画像へナビした瞬間に全画面ズームモードで表示される (review-v2.3.0 P2-10)。
            // 動画→音声モードは item が Video なので下の Video 除外で既に守られている。
            // キー経路は fs_video_key_context_active で消費前に返るため、ここへ Video / Audio が
            // 来るのはキー edge を扱わない Ring / マウス経路。
            && !matches!(
                self.items.get(fs_idx),
                Some(GridItem::Video(_)) | Some(GridItem::Audio(_))
            )
    }

    /// Ring / mouse button などの一発操作から ZipPla 風ズームを切り替える。
    /// KeyHold ではないので照準表示はスキップし、現在のカーソル位置で即ズーム状態に入る。
    pub(crate) fn toggle_fs_zoom_mode_action(&mut self, ctx: &egui::Context, fs_idx: usize) {
        if !self.fs_zoom_mode_context_ok(fs_idx) {
            self.fs_zoom_reset();
            if !self.show_continuous_reading_shortcut_noop(
                ctx,
                fs_idx,
                true,
                FsContinuousReadingUnavailableFeature::Zoom,
            ) {
                self.show_feedback_toast("この表示では全画面ズームモードを使えません".to_string());
            }
            ctx.request_repaint();
            return;
        }
        if self.fs_zoom_mode_engaged() {
            self.fs_zoom_reset();
        } else {
            self.fs_zoom_active = true;
            self.fs_zoom_aiming = false;
            self.fs_zoom_exit_pending = false;
            self.fs_zoom_z_was_down = false;
        }
        ctx.request_repaint();
    }

    /// ズームモードを解除し、エッジ検出状態もリセットする (倍率はセッション保持のため残す)。
    pub(crate) fn fs_zoom_reset(&mut self) {
        self.fs_zoom_active = false;
        self.fs_zoom_aiming = false;
        self.fs_zoom_exit_pending = false;
        self.fs_zoom_z_was_down = false;
        self.fs_zoom_pdf_rerender_idx = None;
    }

    /// 一時状態 (照準中 + エッジ検出) だけリセットする。確定済みズーム (`fs_zoom_active`) は残す。
    /// フォーカス喪失 / モーダル表示でキー処理を飛ばす直前に呼び、復帰時に Z 離しが誤って
    /// ズーム確定したり stale エッジが残ったりするのを防ぐ (Codex P2)。
    pub(crate) fn fs_zoom_reset_transient(&mut self) {
        self.fs_zoom_aiming = false;
        self.fs_zoom_exit_pending = false;
        self.fs_zoom_z_was_down = false;
    }

    /// ZipPla 風全画面ズームのキー状態機械を 1 フレーム進める。Z (修飾なし) のホールド/離しを
    /// OS 直読みのエッジで検出する。fit 状態で押下=照準開始、離す=ズーム確定、ズーム中の押下=解除。
    /// 通常閲覧 (単ページ / 見開き) で動く (連結/パノラマ/動画/分析/編集モードは対象外)。
    fn update_fs_zoom_mode_keys(
        &mut self,
        ctx: &egui::Context,
        fs_idx: usize,
        level_permit: Option<crate::keyboard_input::FocusedKeyStatePermit>,
    ) {
        if self.fs_video_key_context_active(fs_idx) {
            // 同じキーは FsVideo の action (既定 Z = VideoToggleAudioMode) の所有物なので
            // edge を消費しない。消費すると音楽ビューの Z が届かず、音声モードから動画へ
            // 戻れなくなる (backlog §4.2)。
            //
            // 状態だけは畳む: Z ホールド中に画像→動画へ移ったとき、ズームがラッチしたまま
            // 残るのを防ぐ (今の除外分岐が fs_zoom_reset していたのと同じ理由)。ラッチは
            // OS 直読み (非消費) で現在の押下レベルに合わせ、動画から画像へ戻った瞬間に
            // 押しっぱなしの Z が rising edge として照準を始めないようにする。
            self.fs_zoom_reset();
            if let Some(permit) = level_permit {
                self.fs_zoom_z_was_down =
                    self.keymap
                        .key_held_action(ctx, permit, KeyAction::FsZoomMode);
            }
            return;
        }

        // FsZoomMode (KeyHold、既定 Z) の押下/離しを (a) egui イベント (b) OS 直読みの両方から取る。
        // FsImage 内で現在使えない場合も先に edge を消費し、連結表示では無言抑止せず
        // rising edge に一度だけ理由を表示する。`fs_zoom_z_was_down` のラッチでホールド中の
        // 連打を防ぐ。FsVideo 所有の edge は上の所有権判定で消費前に返している。
        let (z_press_event, z_release_event) =
            self.keymap.take_key_hold_edges(ctx, KeyAction::FsZoomMode);
        // A routed Z edge is still drained after focus loss, but KeyHold is a
        // focus-scoped state machine: do not recreate aiming from that edge or
        // sample another application's current key level.
        let Some(level_permit) = level_permit else {
            self.fs_zoom_reset_transient();
            return;
        };
        let z_down = self
            .keymap
            .key_held_action(ctx, level_permit, KeyAction::FsZoomMode);
        let rising = z_press_event || (z_down && !self.fs_zoom_z_was_down);
        let falling = z_release_event || (!z_down && self.fs_zoom_z_was_down);
        if !self.fs_zoom_mode_context_ok(fs_idx) {
            // コンテキスト外: ズーム解除し、エッジ状態もリセット
            // (Z 押しっぱで対象外へ移った時の誤発火を防ぐ)。
            self.fs_zoom_reset();
            self.fs_zoom_z_was_down = z_down;
            self.show_continuous_reading_shortcut_noop(
                ctx,
                fs_idx,
                rising,
                FsContinuousReadingUnavailableFeature::Zoom,
            );
            return;
        }
        // イベントは高速タップ (同フレーム内の押下+離し) を取りこぼさず、OS 直読みは FS ビュー
        // ポートで KeyUp が届かず stale 化したホールドを救う (Codex P2)。割当キーは keymap で
        // カスタマイズ可。エッジ取得時に該当キーイベントは消費して他経路へ漏らさない。
        if rising {
            if self.fs_zoom_active {
                // ズーム中の Z 押下 = 解除 (照準しない)。離すまでラッチして再照準を抑止。
                self.fs_zoom_active = false;
                self.fs_zoom_aiming = false;
                self.fs_zoom_exit_pending = true;
            } else if !self.fs_zoom_exit_pending {
                self.fs_zoom_aiming = true;
            }
        }
        if falling {
            if self.fs_zoom_aiming {
                self.fs_zoom_aiming = false;
                self.fs_zoom_active = true;
            }
            self.fs_zoom_exit_pending = false;
        }
        self.fs_zoom_z_was_down = z_down;
        // 照準中 / Z ホールド中だけ連続描画して離しのエッジを取りこぼさない。確定後のズーム
        // (静止画) はマウス移動 → egui 自動再描画でパンが追従するので、連続再描画はしない
        // (idle 中の busy loop を避ける、Codex P2)。
        if self.fs_zoom_aiming || z_down {
            ctx.request_repaint();
        }
    }

    /// ズームモード中のホイールで倍率を変える (照準中・ズーム中の両方)。上回転=拡大。
    /// 変化したら true。倍率は 1.0 (cover) 〜 16.0 に clamp。
    fn adjust_fs_zoom_factor(&mut self, wheel_y: f32) -> bool {
        if wheel_y.abs() < 0.5 {
            return false;
        }
        let mult = if wheel_y > 0.0 { 1.25 } else { 1.0 / 1.25 };
        // 下限は 0.05 まで許可 (ズームアウト)。実際の下限 (contain) は描画側で画像ごとに
        // factor を clamp して dead zone を防ぐので、ここは広めの安全網にする。
        let new_factor = (self.fs_zoom_factor * mult).clamp(0.05, 16.0);
        if (new_factor - self.fs_zoom_factor).abs() < f32::EPSILON {
            return false;
        }
        self.fs_zoom_factor = new_factor;
        true
    }

    /// ZipPla 風全画面ズームモードの描画。照準中はページ全体フィット + 枠、ズーム中は cover に
    /// `fs_zoom_factor` を掛けた範囲をカーソル位置でパンして描く。既存 `draw_fs_image` を
    /// ページ全体フィット指定で再利用する (新描画パスは足さない)。単ページ画像専用。
    fn draw_fs_zoom_mode(
        &mut self,
        ui: &mut egui::Ui,
        ctx: &egui::Context,
        image_rect: egui::Rect,
        fs_idx: usize,
        state: &FsFrameState,
    ) -> Option<DisplayedImageTransform> {
        let rotation = self.get_rotation(fs_idx);
        let paint_resource = state
            .tex
            .clone()
            .map(|texture| self.fullscreen_paint_resource_for_texture(fs_idx, texture));
        let active = self.fs_zoom_active;
        let pixel_grid = self.fs_pixel_grid_enabled;
        let tex_size = state
            .tex
            .as_ref()
            .or(state.thumb_tex.as_ref())
            .map(egui::TextureHandle::size_vec2);
        let cursor = ctx
            .input(|i| i.pointer.hover_pos())
            .unwrap_or_else(|| image_rect.center());
        let no_limits = FullscreenFitScaleLimits {
            pixels_per_point: ctx.pixels_per_point(),
            ..FullscreenFitScaleLimits::default()
        };
        let Some(tex_size) = tex_size else {
            // テクスチャ未ロード: 通常のプレースホルダ描画へ委ねる。
            let bg_style = self.fs_bg_style(ctx);
            return self.draw_fs_image(
                ui,
                image_rect,
                fs_idx,
                None,
                FsPageLayoutSource::CurrentItem,
                None,
                paint_resource.as_ref(),
                state.thumb_tex.as_ref(),
                state.is_video,
                state.vst3_waiting_for_video,
                state.fs_load_failed,
                rotation,
                None,
                0.0,
                &bg_style,
                &state.location_display,
                false,
                FullscreenFitMode::Page,
                no_limits,
                None,
            );
        };
        // 表示トリムが有効ならズーム対象をトリム後 bbox に絞る (切り落とした余白を見せない)。
        // 回転ページは draw_fs_image 側で bbox を使わないので通常どおり全体を対象にする。
        // mut 借用 (view_trim_single_content_bbox) を bg_style の immutable 借用より前に済ませる。
        // 正規化 bbox は照準オーバービューの draw_fs_image にも渡す (= 余白を出さずトリム後を表示)。
        // Z ズームの寄せ先を決めるので、ここでは分割も反映した矩形が要る
        // (`draw_fs_image` の解決より前に倍率と中心を決めるため)。
        let trim = rotation
            .is_none()
            .then(|| self.view_trim_single_content_bbox(fs_idx))
            .flatten();
        let trim_bbox = self.fs_page_content_bbox(fs_idx, rotation, trim);
        // パン操作帯: 上下のホバーバー (上部バー / 下部シークバー) 分を内側へ詰め、カーソルが
        // そこへ入る前にコンテンツ領域の上端・下端へ到達できるようにする (実機 FB 2026-06-21)。
        // 左右はズーム中にパネルを抑止するので全幅を使う。小画面で帯が潰れないよう高さ 25% で頭打ち。
        let top_m = TOP_BAR_HOVER_Y.min(image_rect.height() * 0.25);
        let bottom_m = (FS_SEEK_BAR_HEIGHT + 8.0).min(image_rect.height() * 0.25);
        let pan_band = egui::Rect::from_min_max(
            egui::pos2(image_rect.left(), image_rect.top() + top_m),
            egui::pos2(image_rect.right(), image_rect.bottom() - bottom_m),
        );
        let source_size = self
            .source_dims_for_idx(fs_idx)
            .map(|(w, h)| egui::vec2(w, h))
            .or_else(|| {
                state
                    .image_dims
                    .map(|(w, h)| egui::vec2(w as f32, h as f32))
            })
            .unwrap_or(tex_size);
        let resolved = ResolvedZTransform::resolve(ZTransformInput {
            image: DisplayedImageTransformInput {
                pixel_fit: RectPixelFit::Texels,
                page_idx: fs_idx,
                viewport_rect: image_rect,
                source_size,
                texture_size: tex_size,
                rotation,
                free_rotation_rad: 0.0,
                content_bbox: trim_bbox,
                fit_mode: FullscreenFitMode::Page,
                fit_scale_limits: no_limits,
                pixels_per_point: ctx.pixels_per_point(),
                placement: ResolvedDisplayPlacement::Z {
                    active,
                    factor: self.fs_zoom_factor,
                    zoom_pan: None,
                },
            },
            active,
            factor: self.fs_zoom_factor,
            cursor,
            pan_band,
        })?;
        self.fs_zoom_factor = resolved.factor;
        let zoom_pan = match resolved.transform.placement {
            ResolvedDisplayPlacement::Z { zoom_pan, .. } => zoom_pan,
            ResolvedDisplayPlacement::Normal { .. } => None,
        };
        let bg_style = self.fs_bg_style(ctx);
        // **返すのは実際に描いた transform。** `draw_fs_image` は渡した矩形をテクスチャに
        // 合わせ直してから貼るので、ここで自分の中間枠を返すと、当たり判定・ナビゲータ・
        // カーソル写像が「画面に出ていない矩形」を基準にする (backlog §1.0h)。
        // 通常表示の枝 (`single_transform = self.draw_fs_image(...)`) は元からこうなっている。
        let painted = self.draw_fs_image(
            ui,
            image_rect,
            fs_idx,
            Some(source_size),
            FsPageLayoutSource::CurrentItem,
            Some(resolved.transform),
            paint_resource.as_ref(),
            state.thumb_tex.as_ref(),
            false,
            false,
            state.fs_load_failed,
            rotation,
            zoom_pan,
            0.0,
            &bg_style,
            &state.location_display,
            pixel_grid && active,
            FullscreenFitMode::Page,
            no_limits,
            trim_bbox,
        );
        if active {
            // Phase C: PDF ページはズーム後の実効倍率で高解像度へ再レンダ (鮮明化)。毎フレ呼ぶと
            // in-flight 要求をキャンセルし続けて完了しないので (Codex P1)、(idx, zoom) が変わった
            // ときだけ要求する。判定は画面上の拡大率に比例する full-image 基準 zoom_full を使う。
            let rerender = self.fs_zoom_pdf_rerender_idx != Some(fs_idx)
                || (resolved.full_image_zoom - self.fs_zoom_pdf_rerender_zoom).abs()
                    > self.fs_zoom_pdf_rerender_zoom.max(1.0) * 0.02;
            if rerender {
                self.fs_zoom_pdf_rerender_idx = Some(fs_idx);
                self.fs_zoom_pdf_rerender_zoom = resolved.full_image_zoom;
                self.maybe_rerender_pdf(resolved.full_image_zoom);
            }
        } else if let Some(frame) = resolved.aim_frame {
            // 照準: トリム後コンテンツを contain 表示してズーム範囲の枠を重ねる。
            let painter = ui.painter().with_clip_rect(image_rect);
            let dim = egui::Color32::from_black_alpha(120);
            for r in capture_region_outside_rects(image_rect, frame) {
                painter.rect_filled(r, 0.0, dim);
            }
            painter.rect_stroke(
                frame,
                0.0,
                egui::Stroke::new(2.0, ui.visuals().selection.bg_fill),
                egui::StrokeKind::Outside,
            );
        }
        painted
    }

    /// 利用者入力から通常表示の pan を変更する唯一の入口。
    ///
    /// Z ズームと連結読みはそれぞれ専用制約を持つため、このクランプを適用しない。
    fn set_fs_pan_from_input(&mut self, proposed_zoom: f32, proposed_pan: egui::Vec2) {
        self.fs_pan = if self.fs_zoom_mode_engaged() {
            proposed_pan
        } else {
            clamp_fullscreen_pan_from_layout(
                &self.fullscreen_page_layout,
                proposed_zoom,
                proposed_pan,
            )
        };
    }

    /// Apply a recognizer-provided touch scale at its screen-space pivot.
    /// Input recognition stays separate from the existing zoom/pan ownership:
    /// this thin adapter reuses the same clamps as wheel and drag input.
    /// いま画面のズーム / パンを実際に握っている状態。
    ///
    /// フルスクリーンには**ズームの持ち主が 4 通り**あり、どれを動かすかの判定が
    /// 入力手段ごとに書かれていた。その結果、入力を足すたびに取りこぼしが出ている:
    /// ホイールは 360 を知っていたがピンチは知らず、中ボタンは分析を知っていたが
    /// 360 を知らない。**書き先を間違えても画面は静止するだけ**なので、見えない値が
    /// 動くだけで誰も気付かない (利用者報告 2026-08-13、360 と分析の両方)。
    ///
    /// 判定はここ 1 か所に集める。新しい入力を足すときは必ずこれを通すこと。
    pub(crate) fn fs_zoom_owner(&self) -> FsZoomOwner {
        if self.fs_zoom_mode_engaged() {
            return FsZoomOwner::ZoomMode;
        }
        if self
            .fullscreen_idx
            .is_some_and(|idx| self.is_panorama_mode_active(idx))
        {
            return FsZoomOwner::Panorama;
        }
        if self.analysis_mode {
            return FsZoomOwner::Analysis;
        }
        FsZoomOwner::Image
    }

    /// 分析モードは右パネルの分だけ画像が左へ寄るので、ピボットの基準矩形が違う。
    fn fs_zoom_pivot_rect(
        &self,
        full_rect: egui::Rect,
        default_image_rect: egui::Rect,
    ) -> egui::Rect {
        match self.fs_zoom_owner() {
            FsZoomOwner::Analysis => analysis_image_rect(full_rect),
            _ => default_image_rect,
        }
    }

    /// 360 度ビューは `fs_zoom` / `fs_pan` を一切見ない (yaw / pitch / fov_y が視点の正)。
    ///
    /// ピンチをそのまま `fs_zoom` へ流すと、**画面には何も起きないのに見えない値だけが動く**。
    /// ホイールが 360 中に FOV 操作へ転用されるのと同じ扱いにする。
    /// 拡大 (factor > 1) は視野を狭める方向なので割る。
    fn apply_panorama_touch_zoom(&mut self, factor: f32) -> bool {
        if !self
            .fullscreen_idx
            .is_some_and(|idx| self.is_panorama_mode_active(idx))
        {
            return false;
        }
        let Some(pano) = self.panorama_state.as_mut() else {
            return false;
        };
        let Some(fov_y) = panorama_touch_zoom_fov(pano.fov_y, factor, pano.projection) else {
            return false;
        };
        pano.fov_y = fov_y;
        pano.sanitize();
        true
    }

    /// ピンチ中の 2 本指の平行移動。1 本指ドラッグと同じ「掴んで引っ張る」向きで
    /// yaw / pitch を回す。`fs_pan` へ流すと 360 では不可視のまま値だけがずれる。
    fn apply_panorama_touch_pan(&mut self, delta: egui::Vec2, viewport_h: f32) -> bool {
        if !self
            .fullscreen_idx
            .is_some_and(|idx| self.is_panorama_mode_active(idx))
        {
            return false;
        }
        let Some(pano) = self.panorama_state.as_mut() else {
            return false;
        };
        let Some((yaw, pitch)) =
            panorama_touch_pan_pose(pano.yaw, pano.pitch, pano.fov_y, delta, viewport_h)
        else {
            return false;
        };
        pano.yaw = yaw;
        pano.pitch = pitch;
        pano.sanitize();
        true
    }

    fn apply_touch_zoom_factor_about_pivot(
        &mut self,
        factor: f32,
        pivot: egui::Pos2,
        rect_center: egui::Pos2,
    ) -> bool {
        if !factor.is_finite() || factor <= 0.0 {
            return false;
        }
        // 分析モードは自前の zoom / pan を持つ。fs_zoom へ書くと画面は静止したまま
        // 見えない値だけが動く (利用者報告 2026-08-13)。
        let analysis = matches!(self.fs_zoom_owner(), FsZoomOwner::Analysis);
        let old_zoom = if analysis {
            self.analysis_zoom
        } else {
            self.fs_zoom
        };
        let new_zoom = (old_zoom * factor).clamp(ZOOM_MIN, ZOOM_MAX);
        if (new_zoom - old_zoom).abs() <= f32::EPSILON {
            return false;
        }
        let start_pan = if analysis {
            self.analysis_pan
        } else {
            self.fs_pan
        };
        let proposed_pan = zoom_preserve_pivot(pivot, rect_center, start_pan, old_zoom, new_zoom);
        if analysis {
            self.analysis_zoom = new_zoom;
            self.analysis_pan = proposed_pan;
        } else {
            self.fs_zoom = new_zoom;
            self.set_fs_pan_from_input(new_zoom, proposed_pan);
        }
        true
    }

    /// ピンチ中の 2 本指平行移動を、いまの持ち主の pan へ流す。
    fn apply_touch_pan_delta(&mut self, delta: egui::Vec2, full_rect: egui::Rect) {
        match self.fs_zoom_owner() {
            FsZoomOwner::Panorama => {
                self.apply_panorama_touch_pan(delta, full_rect.height());
            }
            FsZoomOwner::Analysis => {
                self.analysis_pan += delta;
            }
            FsZoomOwner::ZoomMode | FsZoomOwner::Image => {
                self.set_fs_pan_from_input(self.fs_zoom, self.fs_pan + delta);
            }
        }
    }

    /// 中ボタンドラッグズームを処理する。
    ///
    /// ホイール押し込み + 上下ドラッグで fs_zoom / analysis_zoom を連続的に変える。
    /// 分析モード中は analysis_zoom/pan、それ以外は fs_zoom/pan を書き換える
    /// (どちらに書き込むかはドラッグ開始時点の `analysis_mode` で決まる)。
    /// 戻り値は「このフレームで中ボタンがアクティブに使われていた」か。true なら
    /// 呼び出し側はこの後の左クリック/右クリックの解釈をスキップしてよい。
    fn handle_middle_drag_zoom(&mut self, ctx: &egui::Context, full_rect: egui::Rect) -> bool {
        // ZipPla 風ズーム (照準中 / 確定中) は専用描画経路で fs_zoom/fs_pan を使わない。
        // 中ボタンドラッグで不可視の fs_zoom を書き換えず、専用の fs_zoom_factor を動かす。
        if self.fs_zoom_mode_engaged() {
            return self.handle_zoom_mode_middle_drag(ctx);
        }
        // 360 度ビューも自前の視点を持つ。ここを塞がないと、中ボタンドラッグが
        // 画面に何も起こさないまま fs_zoom を動かす (ピンチと同じ取りこぼし)。
        // FOV はホイールが担当しているので、ここでは何もせず入力だけ消費する。
        if matches!(self.fs_zoom_owner(), FsZoomOwner::Panorama) {
            self.fs_middle_zoom_drag = None;
            return ctx.input(|i| i.pointer.button_down(egui::PointerButton::Middle));
        }
        let (is_down, is_pressed, is_released, current_pos) = ctx.input(|i| {
            (
                i.pointer.button_down(egui::PointerButton::Middle),
                i.pointer.button_pressed(egui::PointerButton::Middle),
                i.pointer.button_released(egui::PointerButton::Middle),
                i.pointer.interact_pos(),
            )
        });

        // 押下開始フレーム: 現在のズーム/パン/ピボットをスナップショット。
        // 同フレームで既にドラッグ中なら無視 (重複開始を防ぐ)。
        if is_pressed && self.fs_middle_zoom_drag.is_none() {
            if let Some(pos) = current_pos {
                // 分析モードでは画像エリアが右パネル分左にずれるので中心が違う
                let rect_center = if self.analysis_mode {
                    analysis_image_rect(full_rect).center()
                } else {
                    full_rect.center()
                };
                let (start_zoom, start_pan) = if self.analysis_mode {
                    (self.analysis_zoom, self.analysis_pan)
                } else {
                    (self.fs_zoom, self.fs_pan)
                };
                self.fs_middle_zoom_drag = Some(MiddleZoomDrag {
                    pivot: pos,
                    start_zoom,
                    start_pan,
                    rect_center,
                    is_analysis: self.analysis_mode,
                });
            }
        }

        // ドラッグ中: 押しっぱなしの間、毎フレーム pivot からの差分で新しいズームを計算。
        if is_down {
            if let (Some(drag), Some(pos)) = (self.fs_middle_zoom_drag.clone(), current_pos) {
                let dy = pos.y - drag.pivot.y;
                if dy.abs() < MIDDLE_DRAG_THRESHOLD_PX {
                    // しきい値以下: ズーム変更なし (クリック暴発防止)
                    return true;
                }
                // 上方向 (dy < 0) で拡大、下方向で縮小
                let factor = 2.0_f32.powf(-dy / MIDDLE_DRAG_UNIT_PX);
                let new_zoom = (drag.start_zoom * factor).clamp(ZOOM_MIN, ZOOM_MAX);
                // pivot 位置が画面上で動かないように pan を補正。ホイールズームと違い
                // 差分累積ではなく毎回 start 値基準で計算することで、dy が元に戻れば
                // pan も完全に元へ戻る (累積誤差が発生しない)。
                let new_pan = zoom_preserve_pivot(
                    drag.pivot,
                    drag.rect_center,
                    drag.start_pan,
                    drag.start_zoom,
                    new_zoom,
                );
                // 書き戻し先はドラッグ開始時の is_analysis で固定
                // (途中でモードが切り替わっても書き先がブレないように)
                if drag.is_analysis {
                    self.analysis_zoom = new_zoom;
                    self.analysis_pan = new_pan;
                } else {
                    self.fs_zoom = new_zoom;
                    self.set_fs_pan_from_input(new_zoom, new_pan);
                }
                return true;
            }
        }

        // リリース: PDF のときだけ新倍率で再レンダリング要求 (ドラッグ中は発行しない)。
        if is_released {
            if let Some(drag) = self.fs_middle_zoom_drag.take() {
                let final_zoom = if drag.is_analysis {
                    self.analysis_zoom
                } else {
                    self.fs_zoom
                };
                if (final_zoom - drag.start_zoom).abs() > f32::EPSILON {
                    self.maybe_rerender_pdf(final_zoom);
                }
                return true;
            }
        }

        false
    }

    fn handle_zoom_mode_middle_drag(&mut self, ctx: &egui::Context) -> bool {
        let (is_down, is_pressed, is_released, current_pos) = ctx.input(|i| {
            (
                i.pointer.button_down(egui::PointerButton::Middle),
                i.pointer.button_pressed(egui::PointerButton::Middle),
                i.pointer.button_released(egui::PointerButton::Middle),
                i.pointer.interact_pos(),
            )
        });

        if is_pressed && self.fs_middle_zoom_drag.is_none() {
            if let Some(pos) = current_pos {
                self.fs_middle_zoom_drag = Some(MiddleZoomDrag {
                    pivot: pos,
                    start_zoom: self.fs_zoom_factor,
                    start_pan: egui::Vec2::ZERO,
                    rect_center: egui::Pos2::ZERO,
                    is_analysis: false,
                });
            }
        }

        if is_down {
            if let (Some(drag), Some(pos)) = (self.fs_middle_zoom_drag.clone(), current_pos) {
                let dy = pos.y - drag.pivot.y;
                if dy.abs() < MIDDLE_DRAG_THRESHOLD_PX {
                    return true;
                }
                let factor = 2.0_f32.powf(-dy / MIDDLE_DRAG_UNIT_PX);
                self.fs_zoom_factor = (drag.start_zoom * factor).clamp(0.05, 16.0);
                ctx.request_repaint();
                return true;
            }
        }

        if is_released && self.fs_middle_zoom_drag.take().is_some() {
            ctx.request_repaint();
            return true;
        }

        false
    }

    /// Overlay editing tools share Photoshop-style temporary pan: hold Space and
    /// drag with the primary button. `can_start` should be false over tool panels,
    /// but an already-started pan continues if the pointer crosses a panel.
    pub(crate) fn handle_overlay_space_pan_drag(
        &mut self,
        ctx: &egui::Context,
        space_held: bool,
        can_start: bool,
        primary_pressed: bool,
        primary_down: bool,
        primary_released: bool,
        pointer_pos: Option<egui::Pos2>,
    ) -> bool {
        let active = self.fs_pan_drag_start.is_some();
        if !space_held {
            if active {
                self.fs_pan_drag_start = None;
            }
            return false;
        }
        if !active && !can_start {
            return false;
        }

        if primary_pressed && !active {
            if let Some(pos) = pointer_pos {
                self.fs_pan_drag_start = Some((pos, self.fs_pan));
            }
        } else if primary_down
            && let (Some((start_pos, start_pan)), Some(pos)) = (self.fs_pan_drag_start, pointer_pos)
        {
            self.set_fs_pan_from_input(self.fs_zoom, start_pan + (pos - start_pos));
        }
        if primary_released {
            self.fs_pan_drag_start = None;
        }
        ctx.set_cursor_icon(if primary_down {
            egui::CursorIcon::Grabbing
        } else {
            egui::CursorIcon::Grab
        });
        true
    }

    /// ホイールによるマウス位置固定ズームを適用する。ズームが変化したら true を返す。
    pub(crate) fn apply_wheel_zoom(
        zoom: &mut f32,
        pan: &mut egui::Vec2,
        wheel_y: f32,
        mouse: Option<egui::Pos2>,
        rect_center: egui::Pos2,
    ) -> bool {
        let factor = 1.1_f32.powf(wheel_y / WHEEL_SENSITIVITY);
        let old_zoom = *zoom;
        *zoom = (old_zoom * factor).clamp(ZOOM_MIN, ZOOM_MAX);
        if let Some(mouse) = mouse {
            *pan = zoom_preserve_pivot(mouse, rect_center, *pan, old_zoom, *zoom);
        }
        *zoom != old_zoom
    }

    /// 現在のフルスクリーン画像が PDF ページなら、指定ズームで再レンダリングを要求する。
    pub(crate) fn maybe_rerender_pdf(&mut self, zoom: f32) {
        if let Some(idx) = self.fullscreen_idx {
            if matches!(self.items.get(idx), Some(GridItem::PdfPage { .. })) {
                // 表示中ページのズーム由来再レンダなので priority レーン (即応)。
                self.request_pdf_rerender(idx, zoom, true);
            }
        }
    }

    pub(crate) fn apply_gamepad_fullscreen_zoom(&mut self, amount: f32, dt: f32) -> bool {
        // ZipPla 風ズーム中は専用経路なので、ゲームパッドで不可視の fs_zoom を動かさない。
        if self.analysis_mode || self.fs_zoom_mode_engaged() || amount.abs() < 0.01 || dt <= 0.0 {
            return false;
        }
        let old_zoom = self.fs_zoom;
        let factor = 2.0_f32.powf(amount * dt);
        self.fs_zoom = (self.fs_zoom * factor).clamp(ZOOM_MIN, ZOOM_MAX);
        if (self.fs_zoom - old_zoom).abs() <= f32::EPSILON {
            return false;
        }
        self.set_fs_pan_from_input(self.fs_zoom, self.fs_pan);
        self.maybe_rerender_pdf(self.fs_zoom);
        true
    }

    pub(crate) fn apply_gamepad_fullscreen_pan(&mut self, delta: egui::Vec2) -> bool {
        if self.analysis_mode
            || self.fs_zoom_mode_engaged()
            || delta.length_sq() <= f32::EPSILON
            || self.fs_zoom <= ZOOM_NEAR_ONE
        {
            return false;
        }
        self.set_fs_pan_from_input(self.fs_zoom, self.fs_pan + delta);
        true
    }
}

/// ピボット点 (`mouse`) が画面上で動かないように、zoom 変化に合わせて pan を補正した
/// 新しい pan を返す。`apply_wheel_zoom` と `handle_middle_drag_zoom` が共用する。
///
/// 式: new_pan = base_pan + (mouse - (rect_center + base_pan)) * (1 - new_zoom / base_zoom)
fn zoom_preserve_pivot(
    mouse: egui::Pos2,
    rect_center: egui::Pos2,
    base_pan: egui::Vec2,
    base_zoom: f32,
    new_zoom: f32,
) -> egui::Vec2 {
    let center = rect_center + base_pan;
    let cx = mouse.x - center.x;
    let cy = mouse.y - center.y;
    let ratio = new_zoom / base_zoom;
    egui::vec2(
        base_pan.x + cx * (1.0 - ratio),
        base_pan.y + cy * (1.0 - ratio),
    )
}

fn should_draw_fs_pixel_grid(
    pixel_grid_enabled: bool,
    using_full_texture: bool,
    zoom_pan: Option<(f32, egui::Vec2)>,
) -> bool {
    pixel_grid_enabled
        && using_full_texture
        && zoom_pan.is_some_and(|(zoom, _)| zoom > ZOOM_NEAR_ONE)
}

/// 中ボタンドラッグズームのスナップショット状態 (v0.8.1)。
/// ドラッグ開始フレームで固定し、以降はここからの差分でズームを計算する。
#[derive(Clone)]
pub(crate) struct MiddleZoomDrag {
    /// ドラッグ開始時のカーソル位置 (このピボットが画面上で動かないように pan を補正)
    pub pivot: egui::Pos2,
    /// 開始時の zoom (fs_zoom または analysis_zoom のいずれか)
    pub start_zoom: f32,
    /// 開始時の pan
    pub start_pan: egui::Vec2,
    /// ピボット計算に使う画像エリアの中心 (通常モードは full_rect.center()、
    /// 分析モードは analysis_image_rect.center())
    pub rect_center: egui::Pos2,
    /// ドラッグ開始時に分析モードだったか (途中でモード切替されても書き戻し先を固定)
    pub is_analysis: bool,
}

/// 分析モード時の画像表示領域（パネル分を右側に確保した残り）を返す。
fn analysis_image_rect(full_rect: egui::Rect) -> egui::Rect {
    let panel_w = 360.0_f32.clamp(full_rect.width() * 0.20, full_rect.width() * 0.35);
    egui::Rect::from_min_max(
        full_rect.min,
        egui::pos2(full_rect.max.x - panel_w, full_rect.max.y),
    )
}

/// コンテンツ領域 (`content_size`) を cover する倍率 × `factor` で、画面に映る範囲サイズ (画像
/// ピクセル) と、その中心 (コンテンツ領域内へ clamp 済み・`content_min` 相対) を返す。
/// 照準枠・ズームパンの共通土台。
#[cfg(test)]
#[allow(dead_code)]
fn zip_visible_src(
    view: egui::Vec2,
    content_size: egui::Vec2,
    factor: f32,
    cursor_in_content: egui::Vec2,
) -> (egui::Vec2, egui::Vec2) {
    crate::displayed_image_transform::z_visible_source(
        view,
        content_size,
        factor,
        cursor_in_content,
    )
}

/// ZipPla 風全画面ズーム: コンテンツ領域 (`content_min`/`content_size`、表示トリム時は bbox、
/// 通常は `(0, display_size)`) を cover する倍率 × `factor` を、`draw_fs_image` の `zoom_pan`
/// (= ページ全体フィット `display_size` に対する倍率, パン) として返す。表示範囲はコンテンツ
/// 領域内へ clamp する (= 余白 / 切り落とした領域を見せない)。
#[cfg(test)]
fn zip_cover_zoom_pan(
    view: egui::Vec2,
    display_size: egui::Vec2,
    content_min: egui::Vec2,
    content_size: egui::Vec2,
    factor: f32,
    cursor_img: egui::Vec2,
) -> (f32, egui::Vec2) {
    crate::displayed_image_transform::z_cover_zoom_pan(
        view,
        display_size,
        content_min,
        content_size,
        factor,
        cursor_img,
    )
}

/// `zip_cover_zoom_pan` が返す **full-image 基準** (ページ全体フィット `display_size` に対する)
/// `(zoom, pan)` を、`draw_fs_image` に **content_bbox を渡したとき同じ img_rect になる bbox 基準**の
/// `(zoom, pan)` へ変換する。
///
/// `draw_fs_image` は `content_bbox` 指定時に「bbox を contain フィット → ×zoom → bbox 中心寄せ」で
/// 描くため、full-image 基準の値をそのまま渡すと位置がずれる。本変換で **位置 (img_rect) を保ったまま
/// content_bbox による UV クロップだけを得る** (= ズームアウトで contain まで縮めても切り落とした余白を
/// 再表示しない、Codex P2)。トリム無し (`content_min = 0`, `content_size = display_size`) では恒等変換。
#[cfg(test)]
fn zip_bbox_zoom_pan_from_full(
    zoom_full: f32,
    pan_full: egui::Vec2,
    view: egui::Vec2,
    display_size: egui::Vec2,
    content_min: egui::Vec2,
    content_size: egui::Vec2,
) -> (f32, egui::Vec2) {
    crate::displayed_image_transform::z_bbox_zoom_pan_from_full(
        zoom_full,
        pan_full,
        view,
        display_size,
        content_min,
        content_size,
    )
}

/// 照準 (Z 押下中) で表示する枠のスクリーン矩形。オーバービューは**トリム後コンテンツ**を
/// contain 表示している前提で (draw_fs_image に content_bbox を渡すのと同じ配置)、そのコンテンツ
/// 表示矩形の中に表示範囲を枠として描く。離した瞬間の `zip_cover_zoom_pan` の表示範囲と一致する。
/// トリムが無いとき (`content_min = 0`, `content_size = display_size`) は従来の全体表示と一致する。
#[cfg(test)]
fn zip_aim_frame_rect(
    aim_basis: &ZAimBasis,
    content_min: egui::Vec2,
    content_size: egui::Vec2,
    factor: f32,
    cursor_img: egui::Vec2,
) -> egui::Rect {
    crate::displayed_image_transform::z_aim_frame_rect(
        aim_basis,
        content_min,
        content_size,
        factor,
        cursor_img,
    )
}

/// 見開き (合成ページ) 用 ZipPla ズーム。可視幅 = 単ページ幅 × 1.2 / factor を狙い (ZipPla の
/// 見開き既定 ≈ 単ページ幅 1.2 倍)、余白が出ないよう cover で下限を取る。`draw_fs_spread` の
/// `zoom_pan` 用に (zoom = total/fit_scale, pan) を返す。`vis` / `center` は照準枠用。
/// `view` = 見開き描画領域サイズ、`composite` = 合成ページサイズ (左右幅合計 × 高さ)、
/// `cursor_comp` = composite px のカーソル位置 (共通 Z aim basis で写像済み)。
fn zip_spread_zoom_pan(
    view: egui::Vec2,
    composite: egui::Vec2,
    single_page_w: f32,
    factor: f32,
    fit_scale: f32,
    cursor_comp: egui::Vec2,
) -> (f32, egui::Vec2, egui::Vec2, egui::Vec2) {
    if composite.x <= 0.0 || composite.y <= 0.0 || view.x <= 0.0 || view.y <= 0.0 {
        return (1.0, egui::Vec2::ZERO, view, composite * 0.5);
    }
    let target_vis_w = (1.2 * single_page_w.max(1.0) / factor.max(f32::EPSILON)).max(1.0);
    // ズームアウト下限 = contain (合成ページの片方の軸が画面に収まる点)。factor < 1.0 で
    // target_vis_w が広がり、cover を下回って contain まで縮小できる。
    let contain = (view.x / composite.x).min(view.y / composite.y);
    let total = (view.x / target_vis_w).max(contain).max(f32::EPSILON);
    let (pan, vis, center) = zip_spread_pan_for_total(view, composite, total, cursor_comp);
    let zoom = if fit_scale > 0.0 {
        total / fit_scale
    } else {
        1.0
    };
    (zoom, pan, vis, center)
}

fn zip_spread_pan_for_total(
    view: egui::Vec2,
    composite: egui::Vec2,
    total_scale: f32,
    cursor_comp: egui::Vec2,
) -> (egui::Vec2, egui::Vec2, egui::Vec2) {
    let total = total_scale.max(f32::EPSILON);
    let vis = egui::vec2(
        (view.x / total).min(composite.x),
        (view.y / total).min(composite.y),
    );
    let cx = cursor_comp
        .x
        .clamp(vis.x / 2.0, (composite.x - vis.x / 2.0).max(vis.x / 2.0));
    let cy = cursor_comp
        .y
        .clamp(vis.y / 2.0, (composite.y - vis.y / 2.0).max(vis.y / 2.0));
    let pan = egui::vec2(
        (composite.x / 2.0 - cx) * total,
        (composite.y / 2.0 - cy) * total,
    );
    (pan, vis, egui::vec2(cx, cy))
}

#[derive(Clone, Copy, Debug)]
struct SpreadZipZoomResult {
    zoom_pan: Option<(f32, egui::Vec2)>,
    aim_frame: Option<egui::Rect>,
    factor: f32,
}

#[allow(clippy::too_many_arguments)]
fn resolve_spread_zip_zoom(
    image_rect: egui::Rect,
    pan_band: egui::Rect,
    cursor: egui::Pos2,
    fit_size: egui::Vec2,
    spread_gap: f32,
    fit_scale: f32,
    factor: f32,
    active: bool,
) -> SpreadZipZoomResult {
    let gap_page = spread_gap / fit_scale.max(f32::EPSILON);
    let composite = egui::vec2(fit_size.x + gap_page, fit_size.y);
    let single_page_w = fit_size.x * 0.5;
    let z_contain = (image_rect.width() / composite.x).min(image_rect.height() / composite.y);
    let factor_min = if image_rect.width() > 0.0 {
        (1.2 * single_page_w * z_contain / image_rect.width()).min(1.0)
    } else {
        1.0
    };
    let factor = factor.clamp(factor_min, 16.0);
    let aim_basis = ZAimBasis::resolve(image_rect, pan_band, composite, fit_scale);
    let cursor_comp = z_cursor_image_px(&aim_basis, egui::Vec2::ZERO, composite, cursor);
    let (zoom, pan, vis, center_comp) = zip_spread_zoom_pan(
        image_rect.size(),
        composite,
        single_page_w,
        factor,
        fit_scale,
        cursor_comp,
    );
    if active {
        SpreadZipZoomResult {
            zoom_pan: Some((zoom, pan)),
            aim_frame: None,
            factor,
        }
    } else {
        let frame_min = aim_basis.content_rect().min
            + egui::vec2(center_comp.x - vis.x / 2.0, center_comp.y - vis.y / 2.0)
                * aim_basis.content_fit();
        SpreadZipZoomResult {
            zoom_pan: None,
            aim_frame: Some(egui::Rect::from_min_size(
                frame_min,
                vis * aim_basis.content_fit(),
            )),
            factor,
        }
    }
}

fn capture_region_outside_rects(bounds: egui::Rect, hole: egui::Rect) -> [egui::Rect; 4] {
    let hole = hole.intersect(bounds);
    [
        egui::Rect::from_min_max(bounds.min, egui::pos2(bounds.max.x, hole.min.y)),
        egui::Rect::from_min_max(egui::pos2(bounds.min.x, hole.max.y), bounds.max),
        egui::Rect::from_min_max(
            egui::pos2(bounds.min.x, hole.min.y),
            egui::pos2(hole.min.x, hole.max.y),
        ),
        egui::Rect::from_min_max(
            egui::pos2(hole.max.x, hole.min.y),
            egui::pos2(bounds.max.x, hole.max.y),
        ),
    ]
}

/// 補正パネル (adjustment panel) のオーバーレイ矩形を返す。
///
/// 設計幅 `LEFT_PANEL_WIDTH` (260px) のまま画像に重ねる。以前は
/// `full_rect.width() * 0.3` で縮小していたが、in-window 表示の狭い窓では
/// 設計幅を下回り、中の文字が折り返し・重なって崩れた (窓幅は min_inner_size で
/// 640 以上に保証されるため縮小は不要)。
///
/// 描画 (`draw_adjustment_panel`) と当たり判定 (ホバー閉じ / ホイール /
/// クリック抑制) は必ずこの関数の rect を使うこと。幅がずれると「見えているのに
/// 枠外扱い」になり、パネルが閉じる・操作がページ送りに化ける。
fn adjustment_panel_rect(full_rect: egui::Rect) -> egui::Rect {
    egui::Rect::from_min_max(
        egui::pos2(full_rect.min.x, full_rect.min.y + TOP_BAR_HEIGHT),
        egui::pos2(
            full_rect.min.x + crate::ui_adjustment_panel::LEFT_PANEL_WIDTH,
            // 下端のページシークバーと重ならないよう、元の下端マージンとシークバー高さの
            // 大きい方だけ下端を空ける。
            full_rect.max.y
                - crate::ui_adjustment_panel::LEFT_PANEL_BOTTOM_MARGIN.max(FS_SEEK_BAR_HEIGHT),
        ),
    )
}

fn fullscreen_seek_panel_rect(full_rect: egui::Rect) -> egui::Rect {
    egui::Rect::from_min_max(
        egui::pos2(full_rect.left(), full_rect.bottom() - FS_SEEK_BAR_HEIGHT),
        full_rect.right_bottom(),
    )
    .intersect(full_rect)
}

fn fullscreen_seek_separator_y(panel_rect: egui::Rect, locked: bool) -> f32 {
    if locked {
        panel_rect.top() + 0.5
    } else {
        panel_rect.top()
    }
}

/// 上部バーの区切り線 y。固定時は線をバーの内側 (上) へ寄せる。
///
/// 1px stroke は指定 y を中心に描かれるので、バーの境界にそのまま置くと半分が画像側に載る。
/// 固定時は画像がその境界まで来るため、下端が「画像上の明るい線」として見える。
fn fullscreen_top_bar_separator_y(bar_rect: egui::Rect, locked: bool) -> f32 {
    if locked {
        bar_rect.bottom() - 0.5
    } else {
        bar_rect.bottom()
    }
}

fn fullscreen_seek_fraction_from_x(track_rect: egui::Rect, pointer_x: f32, rtl: bool) -> f32 {
    let raw = ((pointer_x - track_rect.left()) / track_rect.width().max(1.0)).clamp(0.0, 1.0);
    if rtl { 1.0 - raw } else { raw }
}

fn fullscreen_seek_knob_x(track_rect: egui::Rect, fraction: f32, rtl: bool) -> f32 {
    let fraction = fraction.clamp(0.0, 1.0);
    if rtl {
        track_rect.right() - track_rect.width() * fraction
    } else {
        track_rect.left() + track_rect.width() * fraction
    }
}

/// Compare wipe fractions are always measured across the fitted, zoomed and panned image rect.
/// A fraction of 0 is the rect's left edge and 1 is its right edge.
fn compare_wipe_screen_x(draw_rect: egui::Rect, fraction: f32) -> f32 {
    draw_rect.left() + draw_rect.width() * fraction.clamp(0.0, 1.0)
}

fn compare_wipe_line_visible(
    draw_rect: egui::Rect,
    pointer_hover_pos: Option<egui::Pos2>,
    fraction: f32,
    dragging: bool,
    ctrl_held: bool,
) -> bool {
    if dragging {
        return !ctrl_held;
    }
    pointer_hover_pos.is_some_and(|pos| compare_wipe_grab_hit(draw_rect, pos, fraction))
}

fn compare_wipe_fraction_from_screen_x(
    draw_rect: egui::Rect,
    viewport_rect: egui::Rect,
    screen_x: f32,
) -> Option<f32> {
    let (visible, _) = compare_shader_visible_region(draw_rect, viewport_rect)?;
    let visible_x = screen_x.clamp(visible.left(), visible.right());
    Some(((visible_x - draw_rect.left()) / draw_rect.width().max(f32::EPSILON)).clamp(0.0, 1.0))
}

fn compare_wipe_grab_hit(draw_rect: egui::Rect, pointer: egui::Pos2, fraction: f32) -> bool {
    draw_rect.contains(pointer)
        && (pointer.x - compare_wipe_screen_x(draw_rect, fraction)).abs()
            <= COMPARE_WIPE_GRAB_HALF_WIDTH
}

fn align_compare_color_image_to_canvas(
    pixels: &egui::ColorImage,
    target_size: [usize; 2],
) -> Result<Vec<u8>, String> {
    let rgba = crate::capture::color_image_to_rgba(pixels);
    crate::capture::align_rgba_to_canvas_lanczos(
        pixels.size[0] as u32,
        pixels.size[1] as u32,
        &rgba,
        target_size[0] as u32,
        target_size[1] as u32,
        egui::Color32::BLACK,
    )
}

/// Restrict the compare callback to the viewport and map its local UVs back into the full image.
fn compare_shader_visible_region(
    draw_rect: egui::Rect,
    viewport_rect: egui::Rect,
) -> Option<(egui::Rect, [f32; 4])> {
    let visible = draw_rect.intersect(viewport_rect);
    if !draw_rect.is_positive() || !visible.is_positive() {
        return None;
    }
    let size = draw_rect.size();
    let uv_min = (visible.min - draw_rect.min) / size;
    let uv_max = (visible.max - draw_rect.min) / size;
    Some((visible, [uv_min.x, uv_min.y, uv_max.x, uv_max.y]))
}

/// 固定表示中の上下バーと、ロック中の右情報パネルを除いた画像の表示領域。
///
/// **画像の矩形を決めるのはここ 1 か所。** 描画・ズーム・パン・hit-test・ルーペ・
/// ナビゲータ・範囲コピーは、ここから解いた矩形か `fullscreen_page_layout` を見る。
/// 見た目だけ画像を寄せて、入力座標を旧位置に残さないための境界である (backlog §1.158)。
///
/// `right_panel_width` は 0 でなければ右端を空ける。パネル自身の矩形と同じ値を渡すこと
/// (別々に clamp すると幅が食い違う)。
fn fullscreen_rect_excluding_fixed_bars(
    full_rect: egui::Rect,
    top_locked: bool,
    seek_locked: bool,
    fixed_bar_gap_px: u32,
    right_panel_width: f32,
) -> egui::Rect {
    let gap = fixed_bar_gap_px.min(crate::settings::FULLSCREEN_FIXED_BAR_GAP_MAX_PX) as f32;
    let top = if top_locked {
        (full_rect.top() + TOP_BAR_HEIGHT + gap).min(full_rect.bottom() - 1.0)
    } else {
        full_rect.top()
    };
    let bottom = if seek_locked {
        (full_rect.bottom() - FS_SEEK_BAR_HEIGHT - gap).max(top + 1.0)
    } else {
        full_rect.bottom()
    };
    // 幅が足りなくても画像領域を潰さない。上下バーと同じ形で 1px は残す。
    let right = if right_panel_width > 0.0 {
        (full_rect.right() - right_panel_width).max(full_rect.left() + 1.0)
    } else {
        full_rect.right()
    };
    egui::Rect::from_min_max(egui::pos2(full_rect.left(), top), egui::pos2(right, bottom))
}

/// VST3 コンパクト表示モード時の動画表示領域 (= 右上 1/4 = 幅・高さ各 1/2)。
/// 残った左下 3/4 は黒背景のままなのでプラグイン GUI ウィンドウを置きやすい。
fn vst3_compact_image_rect(full_rect: egui::Rect) -> egui::Rect {
    let half_w = full_rect.width() * 0.5;
    let half_h = full_rect.height() * 0.5;
    egui::Rect::from_min_max(
        egui::pos2(full_rect.max.x - half_w, full_rect.min.y),
        egui::pos2(full_rect.max.x, full_rect.min.y + half_h),
    )
}

/// ナビゲーション可能アイテムのインデックスリストを作成する。
/// `adjacent_navigable_idx` と同じフィルタ条件。
fn build_nav_indices(items: &[GridItem], visible_indices: &[usize]) -> Vec<usize> {
    visible_indices
        .iter()
        .copied()
        .filter(|&i| {
            matches!(
                items.get(i),
                Some(GridItem::Image(_))
                    | Some(GridItem::Video(_))
                    | Some(GridItem::ZipImage { .. })
                    | Some(GridItem::PdfPage { .. })
            )
        })
        .collect()
}

fn is_spread_pairable_item(item: Option<&GridItem>) -> bool {
    matches!(
        item,
        Some(GridItem::Image(_)) | Some(GridItem::ZipImage { .. }) | Some(GridItem::PdfPage { .. })
    )
}

pub(crate) fn navigable_delta_between(
    items: &[GridItem],
    display_order: &[usize],
    current: usize,
    target: usize,
) -> Option<i32> {
    let nav = build_nav_indices(items, display_order);
    let current_pos = nav.iter().position(|&idx| idx == current)?;
    let target_pos = nav.iter().position(|&idx| idx == target)?;
    let delta = target_pos as i32 - current_pos as i32;
    (delta != 0).then_some(delta)
}

/// スライドショーが使う並びを試験から引くための入口。生成規則は本体と同じものを通す。
#[cfg(test)]
pub(crate) fn build_image_reading_indices_for_test(
    items: &[GridItem],
    visible_indices: &[usize],
) -> Vec<usize> {
    build_image_reading_indices(items, visible_indices)
}

fn build_image_reading_indices(items: &[GridItem], visible_indices: &[usize]) -> Vec<usize> {
    crate::ui_helpers::still_image_display_indices(items, visible_indices)
}

fn count_seek_overlay_non_image_items(items: &[GridItem], nav_indices: &[usize]) -> (usize, usize) {
    nav_indices
        .iter()
        .fold((0usize, 0usize), |(videos, others), &idx| {
            match items.get(idx) {
                Some(GridItem::Video(_)) => (videos + 1, others),
                Some(GridItem::Image(_))
                | Some(GridItem::ZipImage { .. })
                | Some(GridItem::PdfPage { .. }) => (videos, others),
                Some(_) | None => (videos, others + 1),
            }
        })
}

/// Remote の静止画 viewer へ、本体 seek overlay と同じ nav item 内訳を公開する。
pub(crate) fn seek_overlay_media_counts(items: &[GridItem]) -> (usize, usize, usize) {
    let display_order = (0..items.len()).collect::<Vec<_>>();
    let image_count = build_image_reading_indices(items, &display_order).len();
    let nav_indices = build_nav_indices(items, &display_order);
    let (video_count, other_count) = count_seek_overlay_non_image_items(items, &nav_indices);
    (image_count, video_count, other_count)
}

/// unit の中心を、隣り合う端と端が `gap` だけ離れるように並べる。
///
/// **1 段ごとに丸めない。** `heights` は既に描画が置く物理ピクセル数ちょうどで、`gap` も
/// 整数画素なので、中心間の距離は「整数画素 + 半画素」になり得る。ここで走行合計を
/// 丸めると、その半画素が段ごとに違う向きへ倒れて**端と端の距離が 1px ずれる**
/// (backlog §1.159)。丸めずに置けば、隣との差はちょうど整数画素になり、各 unit の貼り先を
/// 物理ピクセルへ寄せる段階 (§1.161) を通しても差は保たれる — 整数だけずらした値の
/// 丸めは、丸めてから同じだけずらした値に等しいからである。
///
/// かつては「全 unit の倍率が整数近傍のときだけ丸める」ゲートを持っていた。矩形を寄せて
/// いない倍率では位置を寄せても意味が無い、という当時の前提によるもので、その前提は
/// §1.161 で消えた。
///
/// **積算は物理ピクセルの f64 で行う。** 丸めをやめた代わりに、points の f32 で足し続けると
/// 1 段あたり数 µpx の誤差が段数に比例して積もる (257 段で 0.03px を実測)。長い本ほど効く
/// うえ、丸めで消すと上の半画素問題に戻る。整数・半整数の px を f64 で足せばどちらも起きない。
fn vertical_reading_offsets(
    heights: &[f32],
    gap: f32,
    current_pos: usize,
    pixels_per_point: f32,
) -> Vec<f32> {
    if heights.is_empty() || current_pos >= heights.len() {
        return Vec::new();
    }
    let ppp = if pixels_per_point.is_finite() && pixels_per_point > 0.0 {
        f64::from(pixels_per_point)
    } else {
        1.0
    };
    let gap_px = f64::from(quantize_points_to_physical_pixels(
        gap.max(0.0),
        pixels_per_point,
    )) * ppp;
    let height_px = |pos: usize| f64::from(heights[pos]) * ppp;
    let mut offsets_px = vec![0.0_f64; heights.len()];
    for pos in current_pos + 1..heights.len() {
        offsets_px[pos] =
            offsets_px[pos - 1] + (height_px(pos - 1) + height_px(pos)) * 0.5 + gap_px;
    }
    for pos in (0..current_pos).rev() {
        offsets_px[pos] =
            offsets_px[pos + 1] - (height_px(pos) + height_px(pos + 1)) * 0.5 - gap_px;
    }
    offsets_px
        .into_iter()
        .map(|offset_px| (offset_px / ppp) as f32)
        .collect()
}

fn clamp_vertical_reading_scroll(
    scroll: f32,
    offsets: &[f32],
    heights: &[f32],
    viewport_h: f32,
) -> f32 {
    match vertical_reading_scroll_range(offsets, heights, viewport_h) {
        Some((min_scroll, max_scroll)) if min_scroll < max_scroll => {
            scroll.clamp(min_scroll, max_scroll)
        }
        Some((min_scroll, max_scroll)) => (min_scroll + max_scroll) * 0.5,
        None => 0.0,
    }
}

fn vertical_reading_scroll_range(
    offsets: &[f32],
    heights: &[f32],
    viewport_h: f32,
) -> Option<(f32, f32)> {
    if offsets.is_empty() || heights.is_empty() || offsets.len() != heights.len() {
        return None;
    }
    let center_y = viewport_h.max(1.0) * 0.5;
    let min_scroll = center_y + offsets[0] - heights[0] * 0.5;
    let last = offsets.len() - 1;
    let max_scroll = center_y + offsets[last] + heights[last] * 0.5 - viewport_h.max(1.0);
    Some(if min_scroll <= max_scroll {
        (min_scroll, max_scroll)
    } else {
        let centered = (min_scroll + max_scroll) * 0.5;
        (centered, centered)
    })
}

fn vertical_reading_visible_positions(
    offsets: &[f32],
    heights: &[f32],
    scroll: f32,
    viewport_h: f32,
) -> Vec<usize> {
    if offsets.len() != heights.len() {
        return Vec::new();
    }
    let center_y = viewport_h * 0.5;
    offsets
        .iter()
        .zip(heights.iter())
        .enumerate()
        .filter_map(|(pos, (&offset, &height))| {
            let page_center_y = center_y - scroll + offset;
            let top = page_center_y - height * 0.5;
            let bottom = page_center_y + height * 0.5;
            (bottom >= 0.0 && top <= viewport_h).then_some(pos)
        })
        .collect()
}

fn vertical_reading_prepare_positions(
    unit_count: usize,
    visible_positions: &[usize],
    band_units: usize,
) -> Vec<usize> {
    if unit_count == 0 || visible_positions.is_empty() || band_units == 0 {
        return Vec::new();
    }
    let mut visible = visible_positions
        .iter()
        .copied()
        .filter(|&pos| pos < unit_count)
        .collect::<Vec<_>>();
    visible.sort_unstable();
    visible.dedup();
    let (Some(&first_visible), Some(&last_visible)) = (visible.first(), visible.last()) else {
        return Vec::new();
    };
    let first_prepare = first_visible.saturating_sub(band_units);
    let last_prepare = last_visible.saturating_add(band_units).min(unit_count - 1);
    (first_prepare..=last_prepare)
        .filter(|pos| visible.binary_search(pos).is_err())
        .collect()
}

fn vertical_reading_process_indices_for_pages<F>(
    pages: &[VerticalReadingPage],
    current_idx: usize,
    image_rect: egui::Rect,
    reading_flow: ReadingFlow,
    mut processed_texture_cached: F,
) -> std::collections::HashSet<usize>
where
    F: FnMut(usize) -> bool,
{
    let mut candidates = pages.iter().collect::<Vec<_>>();
    let horizontal = reading_flow.is_horizontal();
    let center = image_rect.center();
    candidates.sort_by(|a, b| {
        let a_current = a.idx != current_idx;
        let b_current = b.idx != current_idx;
        let a_dist = if horizontal {
            (a.rect.center().x - center.x).abs()
        } else {
            (a.rect.center().y - center.y).abs()
        };
        let b_dist = if horizontal {
            (b.rect.center().x - center.x).abs()
        } else {
            (b.rect.center().y - center.y).abs()
        };
        a_current.cmp(&b_current).then_with(|| {
            a_dist
                .partial_cmp(&b_dist)
                .unwrap_or(std::cmp::Ordering::Equal)
        })
    });

    let mut process = std::collections::HashSet::new();
    for page in candidates {
        if processed_texture_cached(page.idx) {
            continue;
        }
        process.insert(page.idx);
        if process.len() >= VERTICAL_READING_PROCESSED_UPLOADS_PER_FRAME {
            break;
        }
    }
    process
}

#[derive(Copy, Clone, Debug, PartialEq, Eq)]
enum ContinuousProcessedAttempt {
    NotAttempted,
    Resolved,
    /// 保存済み編集マーカーの不整合を同期的に整理したため、次フレームでもう一度解決する。
    StateChanged,
    /// 解決できなかった。非同期 owner の有無をこの呼び出し元だけでは完全に判別できないため、
    /// 実機で確認された「読み込み中…」固着を避ける側へ倒して次フレームでも再試行する。
    Unresolved,
}

/// 連結表示が次フレームを必要とするか。
///
/// 純粋な色調補正は同フレームで final composite まで同期生成され `Resolved` になる。一方、
/// 実機で観測された未解決状態の owner をコード上で確定できていないため、`Unresolved` も再描画を
/// 継続する。終端 `None` では idle repaint が残り得るが、既知の表示固着を再発させないことを優先する。
fn continuous_reading_needs_repaint(
    any_raw_work_pending: bool,
    has_deferred_processed: bool,
    selected_processed_attempt: ContinuousProcessedAttempt,
) -> bool {
    if any_raw_work_pending {
        return true;
    }
    match selected_processed_attempt {
        ContinuousProcessedAttempt::NotAttempted | ContinuousProcessedAttempt::Resolved => {
            has_deferred_processed
        }
        ContinuousProcessedAttempt::StateChanged => true,
        ContinuousProcessedAttempt::Unresolved => true,
    }
}

fn continuous_reading_shortcut_noop_reason(
    continuous_reading: bool,
    pressed: bool,
    feature: FsContinuousReadingUnavailableFeature,
) -> Option<FsNavNoOpReason> {
    (continuous_reading && pressed)
        .then_some(FsNavNoOpReason::ContinuousReadingUnavailable(feature))
}

fn vertical_reading_nearest_position(offsets: &[f32], scroll: f32) -> Option<usize> {
    offsets
        .iter()
        .enumerate()
        .min_by(|(_, a), (_, b)| {
            (*a - scroll)
                .abs()
                .partial_cmp(&(*b - scroll).abs())
                .unwrap_or(std::cmp::Ordering::Equal)
        })
        .map(|(pos, _)| pos)
}

fn vertical_reading_reanchor_scroll(scroll: f32, old_offsets: &[f32], new_pos: usize) -> f32 {
    old_offsets
        .get(new_pos)
        .map(|offset| scroll - *offset)
        .unwrap_or(scroll)
}

#[derive(Clone, Copy, Debug, PartialEq)]
struct ContinuousReadingDragDelta {
    scroll: f32,
    pan: egui::Vec2,
}

#[derive(Clone, Copy, Debug, Default, PartialEq)]
enum ContinuousReadingDragState {
    #[default]
    Idle,
    Active {
        session_started_at: std::time::Instant,
        applied_total: egui::Vec2,
    },
    Completed {
        session_started_at: std::time::Instant,
        terminal_frame: u64,
        applied_total: egui::Vec2,
    },
}

impl ContinuousReadingDragState {
    fn advance(
        self,
        session_started_at: std::time::Instant,
        app_frame: u64,
        dragged: bool,
        stopped: bool,
        pointer_down: bool,
        total_delta: Option<egui::Vec2>,
    ) -> (Self, egui::Vec2) {
        let state = match self {
            Self::Active {
                session_started_at: stored_session,
                ..
            }
            | Self::Completed {
                session_started_at: stored_session,
                ..
            } if stored_session != session_started_at => Self::Idle,
            Self::Completed { terminal_frame, .. } if terminal_frame != app_frame => Self::Idle,
            state => state,
        };

        // A terminal response can be replayed by a later egui pass in the same
        // app frame. Keep the applied cumulative total until that frame ends so
        // the replay contributes zero instead of re-applying the entire drag.
        if matches!(
            state,
            Self::Completed {
                terminal_frame,
                ..
            } if terminal_frame == app_frame
        ) {
            return (state, egui::Vec2::ZERO);
        }

        if (dragged || stopped)
            && let Some(total_delta) = total_delta
        {
            let previous_total = match state {
                Self::Active { applied_total, .. } => applied_total,
                Self::Idle | Self::Completed { .. } => egui::Vec2::ZERO,
            };
            let incremental_delta = total_delta - previous_total;
            let next = if stopped || !pointer_down {
                Self::Completed {
                    session_started_at,
                    terminal_frame: app_frame,
                    applied_total: total_delta,
                }
            } else {
                Self::Active {
                    session_started_at,
                    applied_total: total_delta,
                }
            };
            return (next, incremental_delta);
        }

        if matches!(state, Self::Active { .. }) && !pointer_down {
            let applied_total = match state {
                Self::Active { applied_total, .. } => applied_total,
                Self::Idle | Self::Completed { .. } => egui::Vec2::ZERO,
            };
            return (
                Self::Completed {
                    session_started_at,
                    terminal_frame: app_frame,
                    applied_total,
                },
                egui::Vec2::ZERO,
            );
        }

        (state, egui::Vec2::ZERO)
    }
}

/// Whether a continuous-reading drag should consume this frame.
///
/// The mouse must actually be dragging. `pointer.delta()` is non-zero for plain
/// hover movement, so admitting the mouse on a non-zero delta alone would scroll
/// the page whenever the cursor crosses the image with no button held.
///
/// A correlated touch stream may open the branch on its cumulative delta instead,
/// because a coalesced press-move-release arrives in one frame and the response
/// reports no ongoing drag by the time it is read.
fn continuous_reading_drag_consumes_frame(
    response_dragged: bool,
    touch_activity: bool,
    touch_delta: egui::Vec2,
) -> bool {
    response_dragged || (touch_activity && touch_delta != egui::Vec2::ZERO)
}

fn continuous_reading_response_drag_delta(
    ctx: &egui::Context,
    response: &egui::Response,
    coalesced_touch_total: Option<egui::Vec2>,
    session_started_at: Option<std::time::Instant>,
    app_frame: u64,
    enabled: bool,
    pointer_down: bool,
) -> egui::Vec2 {
    let state_id = egui::Id::new(("continuous_reading_drag_state", ctx.viewport_id()));
    let Some(session_started_at) = session_started_at.filter(|_| enabled) else {
        ctx.data_mut(|data| data.remove_temp::<ContinuousReadingDragState>(state_id));
        return egui::Vec2::ZERO;
    };
    // Response::total_drag_delta reads Context input internally, so collect
    // every response fact before taking the temp-data write lock below.
    let response_dragged = response.dragged_by(egui::PointerButton::Primary);
    let response_stopped = response.drag_stopped_by(egui::PointerButton::Primary);
    let response_total = response.total_drag_delta();
    ctx.data_mut(|data| {
        let state = data
            .get_temp::<ContinuousReadingDragState>(state_id)
            .unwrap_or_default();
        // A complete touch stream can be delivered in one RawInput. egui then
        // observes the final pointer as idle and exposes no Response drag even
        // though the ordered touch/pointer correlation proved the gesture.
        // Prefer the normal Response cumulative total; use the correlated raw
        // Start/End total only for that collapsed terminal shape.
        let total_delta = response_total.or(coalesced_touch_total);
        let coalesced_terminal = response_total.is_none() && coalesced_touch_total.is_some();
        let (next, incremental_delta) = state.advance(
            session_started_at,
            app_frame,
            response_dragged || coalesced_terminal,
            response_stopped || coalesced_terminal,
            pointer_down,
            total_delta,
        );
        if next == ContinuousReadingDragState::Idle {
            data.remove_temp::<ContinuousReadingDragState>(state_id);
        } else {
            data.insert_temp(state_id, next);
        }
        incremental_delta
    })
}

fn continuous_reading_coalesced_touch_drag_total(
    ctx: &egui::Context,
    touch_frame: &crate::touch_correlation::TouchFrame,
) -> Option<egui::Vec2> {
    if touch_frame.owner() != crate::touch_input::TouchOwner::ViewerPointerPassthrough
        || touch_frame.is_active()
    {
        return None;
    }
    let mut releases = touch_frame.correlated_primary_release_positions();
    let release_pos = releases.next()?;
    if releases.next().is_some() {
        return None;
    }

    let endpoints = ctx.input(|input| {
        input
            .events
            .iter()
            .filter_map(|event| match event {
                egui::Event::Touch {
                    device_id,
                    id,
                    phase,
                    pos,
                    ..
                } if *phase != egui::TouchPhase::Move => Some((*device_id, *id, *phase, *pos)),
                _ => None,
            })
            .collect::<Vec<_>>()
    });
    let [start, end] = endpoints.as_slice() else {
        return None;
    };
    if start.0 != end.0
        || start.1 != end.1
        || start.2 != egui::TouchPhase::Start
        || end.2 != egui::TouchPhase::End
        || end.3 != release_pos
    {
        return None;
    }
    let total = end.3 - start.3;
    (total != egui::Vec2::ZERO).then_some(total)
}

fn continuous_reading_drag_delta(
    flow: ReadingFlow,
    direction: ReadingDirection,
    pointer_delta: egui::Vec2,
    unlock_axis: bool,
) -> ContinuousReadingDragDelta {
    if flow.is_horizontal() {
        ContinuousReadingDragDelta {
            scroll: if direction == ReadingDirection::Rtl {
                pointer_delta.x
            } else {
                -pointer_delta.x
            },
            pan: if unlock_axis {
                egui::vec2(0.0, pointer_delta.y)
            } else {
                egui::Vec2::ZERO
            },
        }
    } else {
        ContinuousReadingDragDelta {
            scroll: -pointer_delta.y,
            pan: if unlock_axis {
                egui::vec2(pointer_delta.x, 0.0)
            } else {
                egui::Vec2::ZERO
            },
        }
    }
}

/// 指定インデックスの画像が横長（幅>高さ）かを判定する。
///
/// live なフルサイズ cache、ロード済みサムネイル、退去後も残るページ寸法 cache の順で
/// 参照する。一度も寸法が判明していないページだけは false（縦長）として扱うが、判明済みの
/// 寸法はテクスチャ退去で失わないため、同じ items 世代で既知から未知へは後退しない。
/// 分割するか、しないならその理由。
///
/// **無言で「割らない」を返さない。** 実機で「分割を選んだのにページがつながったまま」
/// という報告が出たとき、原因が「寸法待ち」なのか「そもそも縦長」なのかが分からず、
/// ログに何も残っていなかった (2026-08-25)。
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum SplitDecision {
    /// 分割する。判明した寸法を添える。
    Split { w: u32, h: u32 },
    /// 縦長なので分割しない。これは確定した答え。
    NotLandscape { w: u32, h: u32 },
    /// **まだ寸法が分からない**ので分割しない。一時的で、届けば割れる。
    DimensionsUnknown,
    /// 静止画ページではない (動画 / 音声 / フォルダ等)。
    NotAStillPage,
}

impl SplitDecision {
    fn reason(self) -> &'static str {
        match self {
            Self::Split { .. } => "split",
            Self::NotLandscape { .. } => "not_landscape",
            Self::DimensionsUnknown => "dimensions_unknown",
            Self::NotAStillPage => "not_a_still_page",
        }
    }

    fn dims(self) -> Option<(u32, u32)> {
        match self {
            Self::Split { w, h } | Self::NotLandscape { w, h } => Some((w, h)),
            Self::DimensionsUnknown | Self::NotAStillPage => None,
        }
    }
}

/// 表示判断に使える寸法を優先順に探す。
///
/// **見つからないことがある** (まだ読み込んでいない / テクスチャが退去した)。
/// 見開きのペアリングでは「分からない = 横長でない」で困らないが、分割では
/// 「まだ分からないので割らない」と「縦長だから割らない」が別の意味を持つので、
/// 判定と探索を分けてある。
fn known_page_dims(
    idx: usize,
    fs_cache: &ItemsGenerationMap<FsCacheEntry>,
    thumbnails: &[ThumbnailState],
    page_dims_cache: &crate::page_dims::PageDimsCache,
    items_generation: u64,
) -> Option<(u32, u32)> {
    // フルサイズキャッシュから判定
    if let Some(dims) = fs_cache.get(&idx).and_then(fs_cache_entry_page_dims) {
        return Some(dims);
    }
    // サムネイルから判定
    if let Some(ThumbnailState::Loaded {
        tex,
        source_dims,
        layout_dims,
        ..
    }) = thumbnails.get(idx)
    {
        if let Some(dims) = (*layout_dims).or(*source_dims) {
            return Some(dims);
        }
        let width = u32::try_from(tex.size()[0]).unwrap_or(u32::MAX);
        let height = u32::try_from(tex.size()[1]).unwrap_or(u32::MAX);
        return Some((width, height));
    }
    // live texture が退去済みでも、一度判明した同世代の寸法は忘れない。
    page_dims_cache.get(items_generation, idx)
}

fn is_landscape(
    idx: usize,
    rotation: crate::rotation_db::Rotation,
    fs_cache: &ItemsGenerationMap<FsCacheEntry>,
    thumbnails: &[ThumbnailState],
    page_dims_cache: &crate::page_dims::PageDimsCache,
    items_generation: u64,
) -> bool {
    known_page_dims(idx, fs_cache, thumbnails, page_dims_cache, items_generation)
        .is_some_and(|(w, h)| crate::rotation_db::landscape_after_rotation(w, h, rotation))
}

pub(crate) fn fs_cache_entry_page_dims(entry: &FsCacheEntry) -> Option<(u32, u32)> {
    fn from_usize(dims: [usize; 2]) -> Option<(u32, u32)> {
        Some((u32::try_from(dims[0]).ok()?, u32::try_from(dims[1]).ok()?))
    }

    match entry {
        FsCacheEntry::Static {
            tex, source_dims, ..
        } => from_usize(source_dims.unwrap_or_else(|| tex.size())),
        FsCacheEntry::Animated { frames, .. } => {
            frames.first().and_then(|(tex, _)| from_usize(tex.size()))
        }
        FsCacheEntry::Video { player, .. } => player.info().map(|info| {
            crate::video::display_metadata::display_pixel_dimensions(
                info.width,
                info.height,
                info.sar_num,
                info.sar_den,
                info.orientation,
            )
        }),
        FsCacheEntry::Failed => None,
    }
}

#[derive(Clone, Debug)]
struct SpreadDisplayUnit {
    nav_start: usize,
    pages: Vec<usize>,
}

#[derive(Clone, Debug)]
struct SpreadDisplayUnitsToken {
    items_generation: u64,
    spread_mode: SpreadMode,
    shift_anchor_idx: Option<usize>,
    landscape_epoch: u64,
    nav: Vec<usize>,
}

impl SpreadDisplayUnitsToken {
    fn matches(
        &self,
        nav: &[usize],
        items_generation: u64,
        spread_mode: SpreadMode,
        shift_anchor_idx: Option<usize>,
        landscape_epoch: u64,
    ) -> bool {
        self.items_generation == items_generation
            && self.spread_mode == spread_mode
            && self.shift_anchor_idx == shift_anchor_idx
            && self.landscape_epoch == landscape_epoch
            && self.nav == nav
    }

    fn identifies_nav(&self, nav: &[usize], items_generation: u64) -> bool {
        self.items_generation == items_generation && self.nav == nav
    }
}

/// 見開き表示単位列を所有する viewer context 単位のキャッシュ。
///
/// nav は index 列そのものを token に保持し、並べ替え・絞り込み・連結読みの列切替を
/// `items_generation` とは独立に識別する。`landscape_epoch` は、cached nav 上で
/// 「縦長扱い」と「横長」が反転した場合だけ進む。
#[derive(Clone, Debug, Default)]
pub(crate) struct SpreadDisplayUnitsCache {
    token: Option<SpreadDisplayUnitsToken>,
    units: Arc<Vec<SpreadDisplayUnit>>,
    tracked_indices: HashSet<usize>,
    landscape_indices: HashSet<usize>,
    landscape_epoch: u64,
    rotation_recheck_all: bool,
    rotation_recheck_indices: HashSet<usize>,
}

impl SpreadDisplayUnitsCache {
    fn get(
        &self,
        nav: &[usize],
        items_generation: u64,
        spread_mode: SpreadMode,
        shift_anchor_idx: Option<usize>,
    ) -> Option<Arc<Vec<SpreadDisplayUnit>>> {
        self.token
            .as_ref()
            .is_some_and(|token| {
                token.matches(
                    nav,
                    items_generation,
                    spread_mode,
                    shift_anchor_idx,
                    self.landscape_epoch,
                )
            })
            .then(|| Arc::clone(&self.units))
    }

    fn install(
        &mut self,
        nav: &[usize],
        items_generation: u64,
        spread_mode: SpreadMode,
        shift_anchor_idx: Option<usize>,
        landscape_flags: &[bool],
        units: Vec<SpreadDisplayUnit>,
    ) -> Arc<Vec<SpreadDisplayUnit>> {
        self.token = Some(SpreadDisplayUnitsToken {
            items_generation,
            spread_mode,
            shift_anchor_idx,
            landscape_epoch: self.landscape_epoch,
            nav: nav.to_vec(),
        });
        self.tracked_indices = nav.iter().copied().collect();
        self.landscape_indices = nav
            .iter()
            .zip(landscape_flags)
            .filter_map(|(&idx, &landscape)| landscape.then_some(idx))
            .collect();
        self.rotation_recheck_all = false;
        self.rotation_recheck_indices.clear();
        self.units = Arc::new(units);
        Arc::clone(&self.units)
    }

    fn tracks(&self, items_generation: u64, idx: usize) -> bool {
        self.token
            .as_ref()
            .is_some_and(|token| token.items_generation == items_generation)
            && self.tracked_indices.contains(&idx)
    }

    fn reconcile_landscape(&mut self, items_generation: u64, idx: usize, landscape: bool) {
        if !self.tracks(items_generation, idx) {
            return;
        }
        let was_landscape = self.landscape_indices.contains(&idx);
        if was_landscape == landscape {
            return;
        }
        if landscape {
            self.landscape_indices.insert(idx);
        } else {
            self.landscape_indices.remove(&idx);
        }
        self.landscape_epoch = self.landscape_epoch.wrapping_add(1);
    }

    pub(crate) fn mark_rotation_for_recheck(&mut self, items_generation: u64, idx: usize) {
        if self.tracks(items_generation, idx) {
            self.rotation_recheck_indices.insert(idx);
        }
    }

    pub(crate) fn mark_all_rotations_for_recheck(&mut self, items_generation: u64) {
        if self
            .token
            .as_ref()
            .is_some_and(|token| token.items_generation == items_generation)
        {
            self.rotation_recheck_all = true;
            self.rotation_recheck_indices.clear();
        }
    }

    fn take_rotation_rechecks(&mut self, nav: &[usize], items_generation: u64) -> Vec<usize> {
        if !self
            .token
            .as_ref()
            .is_some_and(|token| token.identifies_nav(nav, items_generation))
        {
            self.rotation_recheck_all = false;
            self.rotation_recheck_indices.clear();
            return Vec::new();
        }
        if self.rotation_recheck_all {
            self.rotation_recheck_all = false;
            self.rotation_recheck_indices.clear();
            return nav.to_vec();
        }
        self.rotation_recheck_indices.drain().collect()
    }

    fn tracked_indices(&self, items_generation: u64) -> Vec<usize> {
        self.token
            .as_ref()
            .filter(|token| token.items_generation == items_generation)
            .map(|token| token.nav.clone())
            .unwrap_or_default()
    }
}

impl SpreadDisplayUnit {
    fn anchor_idx(&self) -> usize {
        self.pages[0]
    }

    fn contains_idx(&self, idx: usize) -> bool {
        self.pages.contains(&idx)
    }

    fn screen_pages(&self, spread_mode: SpreadMode) -> Vec<usize> {
        if self.pages.len() == 2 && spread_mode.is_rtl() {
            vec![self.pages[1], self.pages[0]]
        } else {
            self.pages.clone()
        }
    }

    fn spread_pair(&self, spread_mode: SpreadMode) -> SpreadPair {
        if self.pages.len() != 2 {
            return SpreadPair::Single;
        }
        if spread_mode.is_rtl() {
            SpreadPair::Double {
                left: self.pages[1],
                right: self.pages[0],
            }
        } else {
            SpreadPair::Double {
                left: self.pages[0],
                right: self.pages[1],
            }
        }
    }
}

fn build_spread_display_units(
    nav: &[usize],
    rotations: &[crate::rotation_db::Rotation],
    items: &[GridItem],
    spread_mode: SpreadMode,
    shift_anchor_idx: Option<usize>,
    fs_cache: &ItemsGenerationMap<FsCacheEntry>,
    thumbnails: &[ThumbnailState],
    page_dims_cache: &crate::page_dims::PageDimsCache,
    items_generation: u64,
) -> Vec<SpreadDisplayUnit> {
    build_spread_display_units_with_predicates(
        nav,
        spread_mode,
        shift_anchor_idx,
        |nav_pos, idx| {
            is_landscape(
                idx,
                rotations
                    .get(nav_pos)
                    .copied()
                    .unwrap_or(crate::rotation_db::Rotation::None),
                fs_cache,
                thumbnails,
                page_dims_cache,
                items_generation,
            )
        },
        |idx| is_spread_pairable_item(items.get(idx)),
    )
}

#[cfg(test)]
thread_local! {
    static SPREAD_DISPLAY_UNITS_BUILD_COUNT: std::cell::Cell<usize> = const { std::cell::Cell::new(0) };
}

#[cfg(test)]
pub(crate) fn reset_spread_display_units_build_count_for_test() {
    SPREAD_DISPLAY_UNITS_BUILD_COUNT.set(0);
}

#[cfg(test)]
pub(crate) fn spread_display_units_build_count_for_test() -> usize {
    SPREAD_DISPLAY_UNITS_BUILD_COUNT.get()
}
#[cfg(test)]
fn build_spread_display_units_with_landscape(
    nav: &[usize],
    spread_mode: SpreadMode,
    shift_anchor_idx: Option<usize>,
    mut is_landscape_idx: impl FnMut(usize) -> bool,
) -> Vec<SpreadDisplayUnit> {
    build_spread_display_units_with_predicates(
        nav,
        spread_mode,
        shift_anchor_idx,
        |_, idx| is_landscape_idx(idx),
        |_| true,
    )
}

fn build_spread_display_units_with_predicates(
    nav: &[usize],
    spread_mode: SpreadMode,
    shift_anchor_idx: Option<usize>,
    mut is_landscape_idx: impl FnMut(usize, usize) -> bool,
    mut is_pairable_idx: impl FnMut(usize) -> bool,
) -> Vec<SpreadDisplayUnit> {
    let mut units = Vec::new();
    let mut pos = 0usize;
    let shift_anchor_pos = shift_anchor_idx.and_then(|idx| nav.iter().position(|&n| n == idx));
    let prefix_end = shift_anchor_pos.unwrap_or(nav.len());

    if spread_mode.has_cover() && prefix_end > 0 {
        units.push(SpreadDisplayUnit {
            nav_start: 0,
            pages: vec![nav[0]],
        });
        pos = 1;
    }

    append_spread_display_units_until(
        nav,
        &mut units,
        &mut pos,
        prefix_end,
        &mut is_landscape_idx,
        &mut is_pairable_idx,
    );

    if let Some(anchor_pos) = shift_anchor_pos {
        pos = anchor_pos;
        append_spread_display_units_until(
            nav,
            &mut units,
            &mut pos,
            nav.len(),
            &mut is_landscape_idx,
            &mut is_pairable_idx,
        );
    }

    units
}

/// remote IPC 用に、本体と同じ表示単位を画面上の左→右ページ列へ解決する。
///
/// ペア可能種別、表紙位相、横長ページ境界、RTL の左右反転を fullscreen と同じ
/// `SpreadDisplayUnit::spread_pair` へ通す。`is_landscape` は一覧生成側が既存 catalog の
/// source dimensions から解決し、未確定は fullscreen と同じく縦長扱いにする。
/// リモートへ返す 1 つの表示単位。
///
/// **分割中は同じ index が 2 つの単位に現れる**ので、index だけでは識別子にならない
/// (端末側の位置照合は `(anchor, slice)` の組で行う)。
#[derive(Clone, Debug, PartialEq, Eq)]
pub(crate) struct RemotePageGroupSpec {
    pub(crate) indices: Vec<usize>,
    pub(crate) slice: crate::page_split::PageSlice,
}

impl RemotePageGroupSpec {
    fn whole(indices: Vec<usize>) -> Self {
        Self {
            indices,
            slice: crate::page_split::PageSlice::Full,
        }
    }
}

pub(crate) fn build_remote_spread_page_groups(
    items: &[GridItem],
    spread_mode: SpreadMode,
    is_landscape: &[bool],
) -> Vec<RemotePageGroupSpec> {
    let visible = (0..items.len()).collect::<Vec<_>>();
    let nav = build_image_reading_indices(items, &visible);
    // 分割は本体と**同じステップ列**から作る。並べ替えの規則を 2 か所に持たない。
    if let Some(direction) = crate::page_split::SplitDirection::from_spread_mode(spread_mode) {
        return crate::page_split::presentation_steps(&nav, direction, |_, idx| {
            is_spread_pairable_item(items.get(idx))
                && is_landscape.get(idx).copied().unwrap_or(false)
        })
        .into_iter()
        .map(|step| RemotePageGroupSpec {
            indices: vec![step.source_idx],
            slice: step.slice,
        })
        .collect();
    }
    if !spread_mode.is_spread() {
        return nav
            .into_iter()
            .map(|idx| RemotePageGroupSpec::whole(vec![idx]))
            .collect();
    }
    build_spread_display_units_with_predicates(
        &nav,
        spread_mode,
        None,
        |_, idx| is_landscape.get(idx).copied().unwrap_or(false),
        |idx| is_spread_pairable_item(items.get(idx)),
    )
    .into_iter()
    .map(|unit| match unit.spread_pair(spread_mode) {
        SpreadPair::Single => RemotePageGroupSpec::whole(vec![unit.anchor_idx()]),
        SpreadPair::Double { left, right } => RemotePageGroupSpec::whole(vec![left, right]),
    })
    .collect()
}

/// 本体の左右を、リモートの protocol 型へ写す。
pub(crate) fn remote_page_slice(
    slice: crate::page_split::PageSlice,
) -> mimageviewer_ipc::RemotePageSlice {
    match slice {
        crate::page_split::PageSlice::Full => mimageviewer_ipc::RemotePageSlice::Full,
        crate::page_split::PageSlice::Left => mimageviewer_ipc::RemotePageSlice::Left,
        crate::page_split::PageSlice::Right => mimageviewer_ipc::RemotePageSlice::Right,
    }
}

fn append_spread_display_units_until(
    nav: &[usize],
    units: &mut Vec<SpreadDisplayUnit>,
    pos: &mut usize,
    end_pos: usize,
    is_landscape_idx: &mut impl FnMut(usize, usize) -> bool,
    is_pairable_idx: &mut impl FnMut(usize) -> bool,
) {
    while *pos < end_pos {
        let current = nav[*pos];
        if !is_pairable_idx(current) || is_landscape_idx(*pos, current) {
            units.push(SpreadDisplayUnit {
                nav_start: *pos,
                pages: vec![current],
            });
            *pos += 1;
            continue;
        }

        if *pos + 1 < end_pos {
            let partner = nav[*pos + 1];
            if is_pairable_idx(partner) && !is_landscape_idx(*pos + 1, partner) {
                units.push(SpreadDisplayUnit {
                    nav_start: *pos,
                    pages: vec![current, partner],
                });
                *pos += 2;
                continue;
            }
        }

        units.push(SpreadDisplayUnit {
            nav_start: *pos,
            pages: vec![current],
        });
        *pos += 1;
    }
}

fn find_spread_display_unit(
    units: &[SpreadDisplayUnit],
    idx: usize,
) -> Option<(usize, &SpreadDisplayUnit)> {
    units
        .iter()
        .enumerate()
        .find(|(_, unit)| unit.contains_idx(idx))
}

fn spread_seek_unit_fraction(unit_index: usize, unit_count: usize) -> f32 {
    if unit_count <= 1 {
        0.0
    } else {
        unit_index.min(unit_count - 1) as f32 / (unit_count - 1) as f32
    }
}

fn spread_seek_unit_from_fraction(fraction: f32, unit_count: usize) -> usize {
    if unit_count <= 1 {
        return 0;
    }
    ((fraction.clamp(0.0, 1.0) * (unit_count - 1) as f32).round() as usize).min(unit_count - 1)
}

fn spread_offset_nudge_from_units(
    nav: &[usize],
    units: &[SpreadDisplayUnit],
    fs_idx: usize,
    dir: i32,
    landscape_flags: &[bool],
) -> Option<(usize, usize)> {
    let current_start = find_spread_display_unit(units, fs_idx)
        .map(|(_, unit)| unit.nav_start)
        .or_else(|| nav.iter().position(|&i| i == fs_idx))?;
    let new_pos = current_start as i32 + dir;
    if new_pos < 0 || new_pos as usize >= nav.len() {
        return None;
    }
    let new_pos = new_pos as usize;
    let new_idx = nav[new_pos];
    let anchor_pos = spread_shift_anchor_pos_for_target(new_pos, landscape_flags);
    Some((new_idx, nav[anchor_pos]))
}

fn spread_shift_anchor_pos_for_target(target_pos: usize, landscape_flags: &[bool]) -> usize {
    if landscape_flags.get(target_pos).copied().unwrap_or(false) {
        return target_pos;
    }

    // 直近の硬い境界から組み直し、1 ページずらし後の通常前後移動が
    // target 直前の孤立ページへ吸われないようにする。
    let segment_start = (0..target_pos)
        .rev()
        .find(|&pos| landscape_flags.get(pos).copied().unwrap_or(false))
        .map_or(0, |pos| pos + 1);
    let anchor_pos = segment_start + ((target_pos - segment_start) % 2);
    anchor_pos.min(target_pos)
}

fn spread_shift_direction_for_input(
    ctrl_left: bool,
    ctrl_right: bool,
    spread_shift_prev: bool,
    spread_shift_next: bool,
    page_rtl: bool,
) -> Option<i32> {
    let ctrl_nudge_next = (ctrl_right && !page_rtl) || (ctrl_left && page_rtl);
    let ctrl_nudge_prev = (ctrl_left && !page_rtl) || (ctrl_right && page_rtl);
    (ctrl_nudge_next || ctrl_nudge_prev || spread_shift_prev || spread_shift_next).then_some(
        if spread_shift_next || ctrl_nudge_next {
            1
        } else {
            -1
        },
    )
}

// ── フルスクリーン状態の中間構造体 ──────────────────────────────────────

/// フルスクリーン描画 1 フレーム分の事前計算済み状態。
struct FsFrameState {
    is_video: bool,
    original_preview_active: bool,
    page_turn_decision: FsPageTurnDecision,
    tex: Option<egui::TextureHandle>,
    thumb_tex: Option<egui::TextureHandle>,
    /// 上部ホバーバー左側に表示するパス文字列。
    /// 通常画像は `<folder>\<filename>`、ZIP 内画像は `<archive-path> > <entry>`、
    /// PDF ページは `<pdf-path> > Page N` の形で事前に整形して格納する。
    /// 変換済みアーカイブ閲覧中は `archive_source_override` を用いて元の
    /// RAR/7z/LZH のパスを表示する (キャッシュ ZIP のパスは見せない)。
    location_display: String,
    image_dims: Option<(u32, u32)>,
    image_file_size: Option<u64>,
    /// 原寸が GPU テクスチャ上限 (MAX_TEXTURE_DIM=8192) を超えていて、
    /// 表示は縮小版を使っているとき true。ホバーバーに⚠マーカーを出すのに使う。
    image_downscaled: bool,
    is_loading: bool,
    /// 起動時 VST3 チェーンロードが終わるまで動画開始を待っている状態。
    vst3_waiting_for_video: bool,
    fs_load_failed: bool,
    /// PDF ページのコンテンツ種別 (非 PDF なら None)
    pdf_content_type: Option<PdfPageContentType>,
}

/// Per-frame page-turn choices. Paint selection owns full-resolution work admission: a target
/// painted from its materialized source must be allowed to produce and consume the work that can
/// retire its navigation sequence, while a ready pass-through rendition keeps that work deferred.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum FsPageTurnPaintSource {
    Materialized,
    PassThrough,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum FsPageTurnWorkAdmission {
    All,
    /// Admit producer and consumer work belonging to the current typed navigation target, while
    /// keeping unrelated prefetch work deferred. Otherwise a materialized paint source can
    /// suppress the only transition capable of retiring its own sequence.
    NavigationTargetMaterializationOnly,
    /// A ready pass-through rendition is the paint source, so all full-resolution work remains
    /// deferred until that rendition has been presented.
    Deferred,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) struct FsPageTurnDecision {
    paint_source: FsPageTurnPaintSource,
    work_admission: FsPageTurnWorkAdmission,
    passthrough_rendition_ready: bool,
}

const FS_PAGE_TURN_COALESCE_ACTIONS: [KeyAction; 6] = [
    KeyAction::FsPagePrev,
    KeyAction::FsPageNext,
    KeyAction::FsSpreadShiftLeft,
    KeyAction::FsSpreadShiftRight,
    KeyAction::FsSpreadShiftPrev,
    KeyAction::FsSpreadShiftNext,
];

const FS_FIXED_PAGE_TURN_CHORDS: [Chord; 4] = [
    Chord::key(KeyName::Left),
    Chord::key(KeyName::Right),
    Chord::key(KeyName::Up),
    Chord::key(KeyName::Down),
];

impl FsPageTurnDecision {
    const fn normal() -> Self {
        Self {
            paint_source: FsPageTurnPaintSource::Materialized,
            work_admission: FsPageTurnWorkAdmission::All,
            passthrough_rendition_ready: false,
        }
    }

    const fn paint_source(self) -> FsPageTurnPaintSource {
        self.paint_source
    }

    pub(crate) const fn admits_navigation_target_materialization(self) -> bool {
        matches!(
            self.work_admission,
            FsPageTurnWorkAdmission::All
                | FsPageTurnWorkAdmission::NavigationTargetMaterializationOnly
        )
    }

    pub(crate) const fn admits_non_target_full_resolution_work(self) -> bool {
        matches!(self.work_admission, FsPageTurnWorkAdmission::All)
    }

    pub(crate) const fn defers_non_target_full_resolution_work(self) -> bool {
        !self.admits_non_target_full_resolution_work()
    }

    const fn navigation_target_open_materialization(self) -> FsOpenMaterialization {
        match self.work_admission {
            FsPageTurnWorkAdmission::All => FsOpenMaterialization::Eager,
            FsPageTurnWorkAdmission::NavigationTargetMaterializationOnly => {
                FsOpenMaterialization::NavigationTargetMaterializationOnly
            }
            FsPageTurnWorkAdmission::Deferred => FsOpenMaterialization::DeferredPageTurn,
        }
    }

    pub(crate) const fn admits_backlog_upload(self, belongs_to_navigation_target: bool) -> bool {
        match self.work_admission {
            FsPageTurnWorkAdmission::All => true,
            FsPageTurnWorkAdmission::NavigationTargetMaterializationOnly => {
                belongs_to_navigation_target
            }
            FsPageTurnWorkAdmission::Deferred => false,
        }
    }

    const fn work_admission_label(self) -> &'static str {
        match self.work_admission {
            FsPageTurnWorkAdmission::All => "all",
            FsPageTurnWorkAdmission::NavigationTargetMaterializationOnly => {
                "navigation_target_materialization_only"
            }
            FsPageTurnWorkAdmission::Deferred => "deferred",
        }
    }

    const fn perf_label(self) -> &'static str {
        match self.paint_source {
            FsPageTurnPaintSource::Materialized => "materialized",
            FsPageTurnPaintSource::PassThrough => "pass_through",
        }
    }
}

