const FS_PAINT_GEOMETRY_POINT_EPSILON: f32 = 0.25;
const FS_PAINT_GEOMETRY_SCALE_EPSILON: f32 = 0.001;

#[derive(Clone, Copy, Debug, PartialEq)]
struct FsPaintGeometrySignature {
    draw_rect: Option<[f32; 4]>,
    scale_x: Option<f32>,
    scale_y: Option<f32>,
}

impl FsPaintGeometrySignature {
    fn from_transform(transform: Option<DisplayedImageTransform>) -> Self {
        let display_size = transform
            .map(|transform| rotated_display_size(transform.texture_size, transform.rotation));
        Self {
            draw_rect: transform.map(|transform| {
                [
                    transform.paint_rect.min.x,
                    transform.paint_rect.min.y,
                    transform.paint_rect.width(),
                    transform.paint_rect.height(),
                ]
            }),
            scale_x: transform
                .zip(display_size)
                .map(|(transform, display_size)| {
                    transform.full_image_rect.width() / display_size.x.max(1.0)
                }),
            scale_y: transform
                .zip(display_size)
                .map(|(transform, display_size)| {
                    transform.full_image_rect.height() / display_size.y.max(1.0)
                }),
        }
    }

    fn differs_from(self, previous: Self) -> bool {
        fn optional_scalar_differs(
            current: Option<f32>,
            previous: Option<f32>,
            epsilon: f32,
        ) -> bool {
            match (current, previous) {
                (Some(current), Some(previous)) => (current - previous).abs() > epsilon,
                (None, None) => false,
                _ => true,
            }
        }

        let rect_differs = match (self.draw_rect, previous.draw_rect) {
            (Some(current), Some(previous)) => {
                current
                    .into_iter()
                    .zip(previous)
                    .any(|(current, previous)| {
                        (current - previous).abs() > FS_PAINT_GEOMETRY_POINT_EPSILON
                    })
            }
            (None, None) => false,
            _ => true,
        };
        rect_differs
            || optional_scalar_differs(
                self.scale_x,
                previous.scale_x,
                FS_PAINT_GEOMETRY_SCALE_EPSILON,
            )
            || optional_scalar_differs(
                self.scale_y,
                previous.scale_y,
                FS_PAINT_GEOMETRY_SCALE_EPSILON,
            )
    }
}

#[derive(Clone, Copy, Debug, PartialEq)]
struct FsPaintPageSignature {
    idx: usize,
    texture_id: egui::TextureId,
    geometry: FsPaintGeometrySignature,
}

#[derive(Clone, Debug, PartialEq)]
struct FsPaintDisplayUnitSignature {
    items_generation: u64,
    pages: Vec<FsPaintPageSignature>,
}

fn fs_paint_page_changed_from_previous(
    previous: Option<&FsPaintDisplayUnitSignature>,
    items_generation: u64,
    current: FsPaintPageSignature,
) -> bool {
    previous.map_or(true, |previous| {
        previous.items_generation != items_generation
            || previous
                .pages
                .iter()
                .find(|page| page.idx == current.idx && page.texture_id == current.texture_id)
                .is_none_or(|previous| current.geometry.differs_from(previous.geometry))
    })
}

/// What a waiting navigation target should settle on, given what has become available.
///
/// The order of the first two is the rule, not an implementation detail. A stand-in is only ever
/// offered while a held key is turning pages - `rendition_ready` already carries that condition -
/// and there it wins even when the real page is also ready. Preferring the real page reads as the
/// better choice page by page, but it is what made the two directions behave differently: reading
/// forward the prefetch keeps the real page ready, so the stand-in was never used and every turn
/// paid for a full-resolution page, while reading back it was not ready and the same burst ran at
/// thumbnail quality. A burst that changes quality depending on which way it is going is worse
/// than one that is uniformly quick, and the reader has already said they want the speed.
///
/// Outside a burst `rendition_ready` is false, so a single press still shows the real page and
/// nothing about ordinary reading changes.
fn navigation_target_next_phase(
    materialized_ready: bool,
    rendition_ready: bool,
    materialized_failed: bool,
    rendition_failed: bool,
) -> Option<FsNavigationTargetPhase> {
    if rendition_ready {
        Some(FsNavigationTargetPhase::Ready(
            FsNavigationPresentation::Rendition,
        ))
    } else if materialized_ready {
        Some(FsNavigationTargetPhase::Ready(
            FsNavigationPresentation::Materialized,
        ))
    } else if materialized_failed {
        Some(FsNavigationTargetPhase::Ready(
            FsNavigationPresentation::Failure,
        ))
    } else if rendition_failed {
        Some(FsNavigationTargetPhase::RenditionFailed)
    } else {
        None
    }
}

fn page_turn_decision_for_inputs(
    rendition_sequence_active: bool,
    passthrough_rendition_ready: bool,
) -> FsPageTurnDecision {
    let pass_through = rendition_sequence_active && passthrough_rendition_ready;
    FsPageTurnDecision {
        paint_source: if pass_through {
            FsPageTurnPaintSource::PassThrough
        } else {
            FsPageTurnPaintSource::Materialized
        },
        work_admission: if pass_through {
            FsPageTurnWorkAdmission::Deferred
        } else if rendition_sequence_active {
            FsPageTurnWorkAdmission::NavigationTargetMaterializationOnly
        } else {
            FsPageTurnWorkAdmission::All
        },
        passthrough_rendition_ready,
    }
}

fn settling_spread_uses_color_faithful_renditions(
    original_preview_active: bool,
    left_ready: bool,
    left_requires_final: bool,
    right_ready: bool,
    right_requires_final: bool,
) -> bool {
    !original_preview_active
        && ((!left_ready && left_requires_final) || (!right_ready && right_requires_final))
}

