    fn page_wait_navigation_sequence(
        opened_at: std::time::Instant,
        items_generation: u64,
        pages: Vec<usize>,
        phase: FsNavigationTargetPhase,
    ) -> FsHoldover {
        FsHoldover::NavigationSequence(FsNavigationSequence {
            previous: None,
            opened_at,
            target: FsNavigationSequenceTarget::Display(FsNavigationDisplayTarget {
                items_generation,
                pages,
                phase,
            }),
        })
    }

    fn cache_fullscreen_keyboard_owner_for_test(ctx: &egui::Context) {
        crate::keyboard_input::cache_keyboard_owner(
            ctx,
            crate::keyboard_input::KeyboardOwner::ApplicationShortcut {
                scope: crate::keyboard_input::ShortcutScope::new(
                    ctx.viewport_id(),
                    crate::keyboard_input::ShortcutSurface::Fullscreen,
                ),
            },
        );
    }

    fn plain_key_press(key: egui::Key) -> egui::Event {
        egui::Event::Key {
            key,
            physical_key: None,
            pressed: true,
            repeat: false,
            modifiers: egui::Modifiers::NONE,
        }
    }

    fn plain_key_release(key: egui::Key) -> egui::Event {
        egui::Event::Key {
            key,
            physical_key: None,
            pressed: false,
            repeat: false,
            modifiers: egui::Modifiers::NONE,
        }
    }

