    /// Pointer activity clears the idle hide. This is the pre-existing contract for the
    /// auto-hide and is unrelated to aiming, but a carried-over "was idle" flag once made
    /// the latch survive every frame of pointer motion and the cursor never came back.
    #[test]
    fn fs_cursor_idle_hide_is_cleared_by_pointer_activity() {
        let mut app = setup_zoom_cursor_app();
        let ctx = egui::Context::default();
        app.cursor_last_activity =
            Some(std::time::Instant::now() - std::time::Duration::from_secs(120));
        app.cursor_hide_reason = Some(FsCursorHide::Idle);
        let output = run_cursor_visibility_frame(&mut app, &ctx, true);
        assert_eq!(app.cursor_hide_reason, None);
        assert_eq!(cursor_visible_commands(&output), vec![true]);
    }

    /// Aiming is nothing but pointer motion, so an idle hide that preceded it does not
    /// survive it: the countdown restarted while the frame was being aimed.
    #[test]
    fn fs_cursor_zoom_aim_with_motion_does_not_keep_a_prior_idle_hide() {
        let mut app = setup_zoom_cursor_app();
        let ctx = egui::Context::default();
        app.cursor_last_activity =
            Some(std::time::Instant::now() - std::time::Duration::from_secs(120));
        app.cursor_hide_reason = Some(FsCursorHide::Idle);
        app.fs_zoom_aiming = true;
        let _ = run_cursor_visibility_frame(&mut app, &ctx, true);
        assert_eq!(app.cursor_hide_reason, Some(FsCursorHide::ZoomAiming));
        app.fs_zoom_reset();
        let output = run_cursor_visibility_frame(&mut app, &ctx, true);
        assert_eq!(app.cursor_hide_reason, None);
        assert_eq!(cursor_visible_commands(&output), vec![true]);
    }

    /// Holding the key without moving keeps the cursor hidden after aiming ends, because
    /// the idle countdown was never restarted. Same rule, opposite input.
    #[test]
    fn fs_cursor_zoom_aim_without_motion_keeps_the_idle_hide() {
        let mut app = setup_zoom_cursor_app();
        let ctx = egui::Context::default();
        app.cursor_last_activity =
            Some(std::time::Instant::now() - std::time::Duration::from_secs(120));
        app.cursor_hide_reason = Some(FsCursorHide::Idle);
        app.fs_zoom_aiming = true;
        let _ = run_cursor_visibility_frame(&mut app, &ctx, false);
        assert_eq!(app.cursor_hide_reason, Some(FsCursorHide::ZoomAiming));
        app.fs_zoom_reset();
        let output = run_cursor_visibility_frame(&mut app, &ctx, false);
        assert_eq!(app.cursor_hide_reason, Some(FsCursorHide::Idle));
        assert!(!cursor_visible_commands(&output).contains(&true));
    }

    #[test]
    fn fs_cursor_visibility_command_only_changes_with_hide_reason() {
        let mut app = setup_zoom_cursor_app();
        let ctx = egui::Context::default();
        app.fs_zoom_aiming = true;
        let first = run_cursor_visibility_frame(&mut app, &ctx, true);
        let second = run_cursor_visibility_frame(&mut app, &ctx, true);
        let third = run_cursor_visibility_frame(&mut app, &ctx, false);
        app.fs_zoom_reset();
        let exit = run_cursor_visibility_frame(&mut app, &ctx, false);
        assert_eq!(cursor_visible_commands(&first), vec![false]);
        assert!(cursor_visible_commands(&second).is_empty());
        assert!(cursor_visible_commands(&third).is_empty());
        assert_eq!(cursor_visible_commands(&exit), vec![true]);
    }

    #[test]
    fn fs_zoom_key_leaves_video_context_z_press_for_its_owner() {
        // The app test environment holds the data-dir override lock for its whole life, so this
        // lock has to come first everywhere: taking it after setup_app_for_test() inverts the order
        // against every test that takes it before, and the two deadlock under a parallel run.
        #[cfg(windows)]
        let _serial = crate::key_input::TEST_INPUT_LOCK
            .get_or_init(|| std::sync::Mutex::new(()))
            .lock()
            .expect("key input test lock poisoned");
        let mut outcomes = Vec::new();
        for (label, item) in [
            ("Video", GridItem::Video(PathBuf::from("clip.mp4"))),
            ("Audio", GridItem::Audio(PathBuf::from("track.mp3"))),
        ] {
            let mut app = crate::app::setup_app_for_test();
            app.items = vec![item];
            app.thumbnails = vec![crate::grid_item::ThumbnailState::Pending];
            app.fullscreen_idx = Some(0);
            let ctx = egui::Context::default();
            #[cfg(windows)]
            let _clear = ClearTestKeyFrame;
            #[cfg(windows)]
            crate::key_input::clear_test_frame();

            ctx.begin_pass(egui::RawInput {
                events: vec![plain_key_press(egui::Key::Z)],
                ..Default::default()
            });
            cache_fullscreen_keyboard_owner_for_test(&ctx);
            let level_permit = crate::keyboard_input::keyboard_input_permits(&ctx).current_level;
            app.update_fs_zoom_mode_keys(&ctx, 0, level_permit);
            outcomes.push((
                label,
                app.keymap
                    .consume_action_no_repeat(&ctx, KeyAction::VideoToggleAudioMode),
            ));
            let _ = ctx.end_pass();
        }

        assert_eq!(
            outcomes,
            vec![("Video", true), ("Audio", true)],
            "FsImage の KeyHold reader は FsVideo が所有する Z edge を消費してはならない"
        );
    }

    #[test]
    fn fs_zoom_video_context_collapses_state_and_tracks_the_held_zoom_key() {
        // The app test environment holds the data-dir override lock for its whole life, so this
        // lock has to come first everywhere: taking it after setup_app_for_test() inverts the order
        // against every test that takes it before, and the two deadlock under a parallel run.
        #[cfg(windows)]
        let _serial = crate::key_input::TEST_INPUT_LOCK
            .get_or_init(|| std::sync::Mutex::new(()))
            .lock()
            .expect("key input test lock poisoned");
        let mut app = crate::app::setup_app_for_test();
        app.items = vec![GridItem::Video(PathBuf::from("clip.mp4"))];
        app.thumbnails = vec![crate::grid_item::ThumbnailState::Pending];
        app.fullscreen_idx = Some(0);
        app.fs_zoom_active = true;
        app.fs_zoom_aiming = true;
        app.fs_zoom_exit_pending = true;
        app.fs_zoom_z_was_down = false;

        #[cfg(windows)]
        {
            // Windows の hold level は OS 直読みが正本。テスト用に source-routed level を
            // 注入できる NumpadEnter へ KeyHold action を差し替えて同じ状態遷移を検証する。
            let mut settings = crate::keymap::KeymapSettings::default();
            settings.set_override_chords(
                KeyAction::FsZoomMode,
                vec![crate::keymap::Chord::key(
                    crate::keymap::KeyName::NumpadEnter,
                )],
            );
            app.keymap = crate::keymap::Keymap::from_settings(&settings);
        }

        let ctx = egui::Context::default();
        #[cfg(windows)]
        let _clear = ClearTestKeyFrame;
        #[cfg(windows)]
        crate::key_input::set_test_frame_for_viewport(ctx.viewport_id(), Vec::new());
        #[cfg(windows)]
        crate::key_input::set_test_return_key_state(ctx.viewport_id(), false, true);
        #[cfg(windows)]
        let events = Vec::new();
        #[cfg(not(windows))]
        let events = vec![plain_key_press(egui::Key::Z)];

        ctx.begin_pass(egui::RawInput {
            events,
            ..Default::default()
        });
        cache_fullscreen_keyboard_owner_for_test(&ctx);
        let level_permit = crate::keyboard_input::keyboard_input_permits(&ctx).current_level;
        app.update_fs_zoom_mode_keys(&ctx, 0, level_permit);
        let _ = ctx.end_pass();

        assert!(!app.fs_zoom_active);
        assert!(!app.fs_zoom_aiming);
        assert!(!app.fs_zoom_exit_pending);
        assert!(
            app.fs_zoom_z_was_down,
            "foreign context へ移った時も現在の KeyHold level をラッチへ反映する"
        );
    }

