    #[cfg(windows)]
    fn video_audio_exit_diagnostic_record(
        outcome: VideoAudioExitKeyOutcome,
        saw_z: bool,
    ) -> VideoAudioExitKeyDiagnosticRecord {
        VideoAudioExitKeyDiagnosticRecord {
            inputs: VideoAudioExitKeyDiagnosticInputs {
                fs_idx: 1,
                pass: 1,
                video_audio_mode: Some(1),
                action_peek: saw_z,
                z_press: DiagnosticChordPressSnapshot {
                    viewport: egui::ViewportId::ROOT,
                    frame_active: true,
                    frame_had_key_down: saw_z,
                    win32_viewport_key_down: saw_z,
                    win32_viewport_chord_down: saw_z,
                    win32_any_key_down_source: saw_z.then_some(egui::ViewportId::ROOT),
                    egui_key_down: saw_z,
                    egui_chord_down: saw_z,
                    egui_fallback_allowed: true,
                    frame_active_blocks_egui_fallback: false,
                    result: saw_z,
                },
                fullscreen_summary: None,
            },
            outcome,
        }
    }

    #[cfg(windows)]
    #[test]
    fn video_audio_exit_diagnostic_folds_repeats_and_preserves_rate_limited_z() {
        let start = std::time::Instant::now();
        let mut state = VideoAudioExitKeyDiagnosticRateState::default();
        let baseline =
            video_audio_exit_diagnostic_record(VideoAudioExitKeyOutcome::ActionNotConsumed, false);
        assert!(state.observe(start, baseline.clone()).is_some());
        assert!(
            state
                .observe(
                    start + std::time::Duration::from_millis(100),
                    baseline.clone()
                )
                .is_none()
        );

        let z =
            video_audio_exit_diagnostic_record(VideoAudioExitKeyOutcome::ActionNotConsumed, true);
        assert!(
            state
                .observe(start + std::time::Duration::from_millis(200), z)
                .is_none()
        );
        assert!(
            state
                .observe(
                    start + std::time::Duration::from_millis(999),
                    baseline.clone()
                )
                .is_none()
        );
        let emitted = state
            .observe(start + std::time::Duration::from_secs(1), baseline.clone())
            .unwrap();
        assert!(emitted.inputs.saw_z_or_action_press());
        assert!(
            state
                .observe(start + std::time::Duration::from_millis(1500), baseline)
                .is_none()
        );
    }

    #[cfg(windows)]
    #[test]
    fn video_audio_exit_diagnostic_uses_fullscreen_summary_when_all_four_probes_miss() {
        let start = std::time::Instant::now();
        let mut state = VideoAudioExitKeyDiagnosticRateState::default();
        let baseline =
            video_audio_exit_diagnostic_record(VideoAudioExitKeyOutcome::ActionNotConsumed, false);
        assert!(state.observe(start, baseline.clone()).is_some());
        let mut summary_z = baseline.clone();
        summary_z.inputs.fullscreen_summary = Some("Z:down:Modifiers".to_string());
        assert!(!summary_z.inputs.action_peek);
        assert!(!summary_z.inputs.z_press.win32_viewport_key_down);
        assert!(summary_z.inputs.z_press.win32_any_key_down_source.is_none());
        assert!(!summary_z.inputs.z_press.egui_key_down);
        assert!(summary_z.inputs.fullscreen_summary_saw_z_down());
        assert!(summary_z.inputs.saw_z_or_action_press());
        assert!(
            state
                .observe(start + std::time::Duration::from_millis(200), summary_z)
                .is_none()
        );
        let emitted = state
            .observe(start + std::time::Duration::from_millis(1200), baseline)
            .expect("the independently observed fullscreen Z must remain a candidate");
        assert!(emitted.inputs.fullscreen_summary_saw_z_down());
    }

    #[cfg(windows)]
    #[test]
    fn video_audio_exit_diagnostic_emits_a_heartbeat_without_candidates() {
        let start = std::time::Instant::now();
        let mut state = VideoAudioExitKeyDiagnosticRateState::default();
        let baseline =
            video_audio_exit_diagnostic_record(VideoAudioExitKeyOutcome::ActionNotConsumed, false);
        assert!(state.observe(start, baseline.clone()).is_some());
        assert!(
            state
                .observe(
                    start + std::time::Duration::from_millis(100),
                    baseline.clone()
                )
                .is_none()
        );
        let first_heartbeat = state
            .observe(
                start + VIDEO_AUDIO_EXIT_DIAGNOSTIC_MIN_INTERVAL,
                baseline.clone(),
            )
            .expect("an unchanged audio-mode frame must still emit after one second");
        assert!(!first_heartbeat.inputs.saw_z_or_action_press());
        assert_eq!(
            first_heartbeat.outcome,
            VideoAudioExitKeyOutcome::ActionNotConsumed
        );
        assert!(
            state
                .observe(
                    start + std::time::Duration::from_millis(1500),
                    baseline.clone()
                )
                .is_none()
        );
        assert!(
            state
                .observe(start + std::time::Duration::from_secs(2), baseline)
                .is_some(),
            "the heartbeat must remain periodic while audio mode is observed"
        );
    }

    #[cfg(windows)]
    #[test]
    fn video_audio_exit_diagnostic_rearms_for_new_audio_mode_session() {
        let start = std::time::Instant::now();
        let mut state = VideoAudioExitKeyDiagnosticRateState::default();
        let first =
            video_audio_exit_diagnostic_record(VideoAudioExitKeyOutcome::ActionNotConsumed, false);
        assert!(state.observe(start, first).is_some());

        let steady =
            video_audio_exit_diagnostic_record(VideoAudioExitKeyOutcome::ActionNotConsumed, false);
        assert!(
            state
                .observe(start + std::time::Duration::from_millis(100), steady)
                .is_none()
        );

        state.reset_session();
        let reentered =
            video_audio_exit_diagnostic_record(VideoAudioExitKeyOutcome::ActionNotConsumed, false);
        assert!(
            state
                .observe(start + std::time::Duration::from_millis(200), reentered)
                .is_none()
        );
        let next =
            video_audio_exit_diagnostic_record(VideoAudioExitKeyOutcome::ActionNotConsumed, false);
        assert!(
            state
                .observe(start + std::time::Duration::from_secs(1), next)
                .is_some()
        );
    }

    #[cfg(windows)]
    fn original_preview_blocker_record(
        active: bool,
        cache_hit: bool,
        sequence_at_write: bool,
        sequence_at_blocker: bool,
        call_order: u64,
    ) -> FsOriginalPreviewBlockerDiagnosticRecord {
        FsOriginalPreviewBlockerDiagnosticRecord {
            idx: 4,
            items_generation: 9,
            viewport: egui::ViewportId::ROOT,
            sequence_blocks_new_target: sequence_at_blocker,
            observation: FsOriginalPreviewFrameObservation {
                sample: FsOriginalPreviewFrameSample {
                    frame_nr: 11,
                    items_generation: 9,
                    idx: 4,
                    active,
                    written_pass_nr: 20,
                    written_call_order: 1,
                    sequence_blocks_new_target_at_write: sequence_at_write,
                },
                cache_hit,
                observed_frame_nr: 11,
                observed_pass_nr: 20,
                observed_call_order: call_order,
            },
        }
    }

    #[cfg(windows)]
    #[test]
    fn original_preview_blocker_diagnostic_aggregates_without_signal_gating() {
        let start = std::time::Instant::now();
        let mut state = FsOriginalPreviewBlockerDiagnosticRateState::default();
        let first = state
            .observe(
                start,
                original_preview_blocker_record(false, false, false, false, 1),
            )
            .expect("the first observation establishes the one-second heartbeat");
        assert_eq!(first.checks, 1);
        assert_eq!(first.original_preview_returns, 0);

        assert!(
            state
                .observe(
                    start + std::time::Duration::from_millis(100),
                    original_preview_blocker_record(true, true, false, true, 2),
                )
                .is_none()
        );
        assert!(
            state
                .observe(
                    start + std::time::Duration::from_millis(200),
                    original_preview_blocker_record(true, false, false, false, 1),
                )
                .is_none()
        );
        let summary = state
            .observe(
                start + FS_ORIGINAL_PREVIEW_BLOCKER_LOG_INTERVAL,
                original_preview_blocker_record(false, true, true, true, 3),
            )
            .expect("the interval, not an investigated signal, must release the summary");
        assert_eq!(summary.checks, 3);
        assert_eq!(summary.sequence_in_flight_checks, 2);
        assert_eq!(summary.original_preview_returns, 2);
        assert_eq!(summary.sequence_in_flight_returns, 1);
        assert_eq!(summary.sequence_idle_returns, 1);
        assert_eq!(summary.memo_hit_returns, 1);
        assert_eq!(summary.fresh_evaluation_returns, 1);
        let last = summary
            .last_return
            .expect("the latest return keeps its order");
        assert!(!last.sequence_blocks_new_target);
        assert!(!last.observation.cache_hit);
        assert_eq!(last.observation.sample.written_call_order, 1);
        assert_eq!(last.observation.observed_frame_nr, 11);
        assert_eq!(last.observation.observed_call_order, 1);

        let heartbeat = state
            .observe(
                start + FS_ORIGINAL_PREVIEW_BLOCKER_LOG_INTERVAL * 2,
                original_preview_blocker_record(false, false, false, true, 1),
            )
            .expect("a zero-return interval must still emit");
        assert_eq!(heartbeat.sequence_in_flight_checks, 1);
        assert_eq!(heartbeat.original_preview_returns, 0);
        assert!(heartbeat.last_return.is_none());
    }

