    fn assert_rect_close(actual: egui::Rect, expected: egui::Rect) {
        const EPSILON: f32 = 1.0e-3;
        assert!((actual.left() - expected.left()).abs() < EPSILON);
        assert!((actual.top() - expected.top()).abs() < EPSILON);
        assert!((actual.right() - expected.right()).abs() < EPSILON);
        assert!((actual.bottom() - expected.bottom()).abs() < EPSILON);
    }

    fn push_loaded_pdf_page(
        app: &mut App,
        ctx: &egui::Context,
        texture_name: &str,
        path: &str,
        page_num: u32,
        texture_size: [usize; 2],
        source_dims: (u32, u32),
        layout_dims: (u32, u32),
        color: egui::Color32,
    ) -> usize {
        let idx = app.items.len();
        app.items.push(GridItem::PdfPage {
            pdf_path: PathBuf::from(path),
            page_num,
            content_type: None,
        });
        app.thumbnails.push(ThumbnailState::Loaded {
            tex: ctx.load_texture(
                texture_name,
                egui::ColorImage::filled(texture_size, color),
                egui::TextureOptions::LINEAR,
            ),
            from_cache: false,
            from_edit_preview: false,
            rendered_at_px: texture_size[0].max(texture_size[1]) as u32,
            source_dims: Some(source_dims),
            layout_dims: Some(layout_dims),
        });
        idx
    }

    fn replace_loaded_pdf_page(
        app: &mut App,
        ctx: &egui::Context,
        idx: usize,
        texture_name: &str,
        path: &str,
        page_num: u32,
        layout_dims: (u32, u32),
    ) {
        app.items[idx] = GridItem::PdfPage {
            pdf_path: PathBuf::from(path),
            page_num,
            content_type: None,
        };
        app.thumbnails[idx] = ThumbnailState::Loaded {
            tex: ctx.load_texture(
                texture_name,
                egui::ColorImage::filled([24, 12], egui::Color32::LIGHT_BLUE),
                egui::TextureOptions::LINEAR,
            ),
            from_cache: false,
            from_edit_preview: false,
            rendered_at_px: 24,
            source_dims: Some((1200, 600)),
            layout_dims: Some(layout_dims),
        };
    }

