    fn assert_loupe_scale(mapping: LoupeSampleMapping, texture_size: egui::Vec2, expected: f32) {
        let scale_x = mapping.image_rect.width() / (mapping.uv_rect.width() * texture_size.x);
        let scale_y = mapping.image_rect.height() / (mapping.uv_rect.height() * texture_size.y);
        assert!((scale_x - expected).abs() < 1.0e-4);
        assert!((scale_y - expected).abs() < 1.0e-4);
    }

    #[test]
    fn unresolved_page_turn_keeps_atomic_holdover_while_admitting_target_materialization() {
        let decision = page_turn_decision_for_inputs(true, false);

        assert_eq!(decision.paint_source(), FsPageTurnPaintSource::Materialized);
        assert_eq!(
            decision.work_admission,
            FsPageTurnWorkAdmission::NavigationTargetMaterializationOnly
        );
        assert!(decision.admits_navigation_target_materialization());
        assert!(decision.admits_backlog_upload(true));
        assert!(!decision.admits_backlog_upload(false));
        assert!(!decision.passthrough_rendition_ready);
        let fields = fs_page_turn_decision_probe_fields(
            1,
            2,
            3,
            4,
            decision,
            "navigation_sequence",
            false,
            None,
            FsPageTurnCtrlProbeLevels::default(),
        );
        assert_eq!(
            page_turn_probe_field(&fields, "defer_ui_uploads"),
            &serde_json::Value::Bool(true)
        );
        assert_eq!(
            page_turn_probe_field(&fields, "ui_work_admission"),
            &serde_json::Value::String("navigation_target_materialization_only".to_owned())
        );
    }

    fn page_turn_probe_field<'a>(
        fields: &'a [(&'static str, serde_json::Value)],
        name: &str,
    ) -> &'a serde_json::Value {
        fields
            .iter()
            .find_map(|(field_name, value)| (*field_name == name).then_some(value))
            .unwrap_or_else(|| panic!("missing page-turn probe field: {name}"))
    }

