    #[test]
    fn continuous_navigation_sequence_retires_after_complete_target_rendition_is_drawn() {
        let ctx = egui::Context::default();
        let mut app = crate::app::setup_app_for_test();
        app.items = (0..2)
            .map(|idx| {
                GridItem::Image(PathBuf::from(format!(
                    "c:/test/continuous-navigation-{idx}.jpg"
                )))
            })
            .collect();
        app.thumbnails.clear();
        for idx in 0..2 {
            let pixels = std::sync::Arc::new(egui::ColorImage::filled(
                [4, 6],
                egui::Color32::from_gray(80 + idx as u8 * 40),
            ));
            let texture = ctx.load_texture(
                format!("continuous_navigation_thumbnail_{idx}"),
                pixels.as_ref().clone(),
                egui::TextureOptions::LINEAR,
            );
            app.thumbnails.push(ThumbnailState::Loaded {
                tex: texture,
                from_cache: false,
                from_edit_preview: false,
                rendered_at_px: 6,
                source_dims: Some((400, 600)),
                layout_dims: None,
            });
            app.thumb_pixels.insert(idx, pixels);
        }
        app.visible_indices = vec![0, 1];
        app.fullscreen_idx = Some(0);
        app.selected = Some(0);
        app.items_generation = 9;
        app.reading_flow = ReadingFlow::Horizontal;
        app.spread_mode = SpreadMode::Ltr;

        let left_rendition = app.ensure_passthrough_rendition(&ctx, 0).unwrap();
        assert!(app.ensure_passthrough_rendition(&ctx, 1).is_some());
        assert!(app.fs_cache.is_empty());
        assert!(app.fs_upload_backlog.is_empty());
        assert!(app.final_composite_cache.is_empty());
        app.fs_nav_locked_gen = Some(app.items_generation);
        app.fs_holdover_tex = Some(FsHoldover::NavigationSequence(FsNavigationSequence {
            previous: None,
            opened_at: std::time::Instant::now(),
            target: FsNavigationSequenceTarget::Display(FsNavigationDisplayTarget {
                items_generation: app.items_generation,
                pages: vec![0, 1],
                phase: FsNavigationTargetPhase::Ready(FsNavigationPresentation::Rendition),
            }),
        }));
        let decision = page_turn_decision_for_inputs(true, true);
        assert!(decision.defers_non_target_full_resolution_work());
        assert!(app.fs_nav_holdover_for_draw().is_none());

        let one_drawn = FsNavigatorTextureSources::single(
            0,
            Some(FullscreenPaintResource::direct(left_rendition)),
        );
        app.emit_fs_page_turn_ready_for_display_unit(
            &ctx,
            0,
            SpreadPair::Double { left: 0, right: 1 },
            decision,
            &one_drawn,
        );
        assert!(app.fs_navigation_sequence_blocks_new_target());
        let image_rect = egui::Rect::from_min_size(egui::Pos2::ZERO, egui::vec2(800.0, 600.0));
        let mut continuous_sources = FsNavigatorTextureSources::default();
        let _ = ctx.run(
            egui::RawInput {
                screen_rect: Some(image_rect),
                ..Default::default()
            },
            |ctx| {
                egui::CentralPanel::default()
                    .frame(egui::Frame::NONE)
                    .show(ctx, |ui| {
                        continuous_sources =
                            app.draw_fs_continuous_reading(ui, ctx, image_rect, 0, false, decision);
                    });
            },
        );
        app.emit_fs_page_turn_ready_for_display_unit(
            &ctx,
            0,
            SpreadPair::Double { left: 0, right: 1 },
            decision,
            &continuous_sources,
        );
        assert!(app.fs_holdover_tex.is_none());
        let (sequence_active, rendition_ready) = app.fs_navigation_sequence_rendition_state(0);
        let next_decision = page_turn_decision_for_inputs(sequence_active, rendition_ready);
        assert!(!next_decision.defers_non_target_full_resolution_work());
    }

    /// Build an app sitting in fullscreen on a video whose thumbnail has loaded.
    ///
    /// A video is drawn by the native presenter, so it never reaches
    /// `emit_fs_page_turn_ready_for_display_unit` - the only production caller of
    /// `observe_fs_navigation_sequence_presented`, and therefore the only thing that can retire a
    /// navigation sequence. Anything that opens a sequence for this item has to be able to close
    /// it some other way, or fullscreen navigation stops responding until the user leaves
    /// fullscreen entirely.
    fn app_in_fullscreen_on_a_video(ctx: &egui::Context) -> crate::app::AppTestEnvForTest {
        let mut app = crate::app::setup_app_for_test();
        let texture = ctx.load_texture(
            stringify!(video_thumbnail),
            egui::ColorImage::filled([1, 1], egui::Color32::WHITE),
            egui::TextureOptions::LINEAR,
        );
        app.items = vec![crate::grid_item::GridItem::Video(std::path::PathBuf::from(
            "c:/clips/clip.mp4",
        ))];
        app.thumbnails = vec![crate::grid_item::ThumbnailState::Loaded {
            tex: texture,
            from_cache: false,
            from_edit_preview: false,
            rendered_at_px: 64,
            source_dims: None,
            layout_dims: None,
        }];
        app.fullscreen_idx = Some(0);
        app.items_generation = 5;
        app
    }

    /// Ctrl+Down onto a folder whose first item is a video must not wedge navigation.
    ///
    /// Observed 2026-08-14: 14 navigation inputs over 21.8 seconds produced no folder change,
    /// and only leaving fullscreen recovered.
    #[test]
    fn folder_navigation_onto_a_video_does_not_wedge_the_next_navigation() {
        let ctx = egui::Context::default();
        let mut app = app_in_fullscreen_on_a_video(&ctx);
        app.fs_holdover_tex = Some(FsHoldover::NavigationSequence(FsNavigationSequence {
            previous: None,
            opened_at: std::time::Instant::now(),
            target: FsNavigationSequenceTarget::FolderItems {
                accepted_generation: 4,
            },
        }));
        app.fs_nav_locked_gen = Some(4);

        app.poll_fs_nav_lock(&ctx);

        assert!(
            !app.fs_navigation_sequence_blocks_new_target(),
            "a sequence that landed on a video has to retire: the page-turn draw path that would \
             normally retire it never runs for a natively presented item, so leaving it open \
             drops every later Ctrl+Up/Down"
        );
    }

    /// A `Display` target names a unit the page renderer will draw, and the page renderer's trace
    /// is the only thing that retires a sequence. So every page in such a target has to be
    /// page-bearing; a video described this way can be resolved to `Ready` but never presented,
    /// and fullscreen navigation stops responding.
    ///
    /// `Ready` is deliberately not the assertion here: it means "drawable", not "presented", so
    /// checking `blocks_new_target()` right after resolution would encode the wrong contract.
    /// The defect is that the target was built at all.
    #[test]
    fn page_navigation_never_describes_a_natively_presented_item_as_a_page_unit() {
        let ctx = egui::Context::default();
        let mut app = app_in_fullscreen_on_a_video(&ctx);
        // idx 0 is a still image the viewer is on; idx 1 is the video it navigates to.
        app.items.insert(
            0,
            crate::grid_item::GridItem::Image(std::path::PathBuf::from("c:/clips/page.png")),
        );
        let still = app.thumbnails[0].clone();
        app.thumbnails.insert(0, still);
        app.fullscreen_idx = Some(0);

        assert!(app.begin_fs_page_navigation_sequence(&ctx, 0, 1, true));

        let target = app
            .fs_holdover_tex
            .as_ref()
            .and_then(FsHoldover::navigation_sequence)
            .map(|sequence| sequence.target.clone());
        if let Some(FsNavigationSequenceTarget::Display(target)) = target {
            for page in &target.pages {
                assert!(
                    app.items
                        .get(*page)
                        .is_some_and(crate::grid_item::GridItem::has_page_data),
                    "page {page} of a Display target is not drawn by the page renderer, so no \
                     presentation trace can ever retire this sequence"
                );
            }
        }
    }

    #[test]
    fn page_navigation_onto_video_does_not_wedge_the_next_handler_navigation() {
        let ctx = egui::Context::default();
        let mut app = app_in_fullscreen_on_a_video(&ctx);
        app.items.insert(
            0,
            GridItem::Image(PathBuf::from("c:/clips/before-video.png")),
        );
        app.items.push(GridItem::ZipImage {
            zip_path: PathBuf::from("c:/clips/pages.zip"),
            entry_name: "after-video.png".to_owned(),
        });
        app.items
            .push(GridItem::Image(PathBuf::from("c:/clips/next-page.png")));
        app.thumbnails = vec![ThumbnailState::Pending; app.items.len()];
        app.visible_indices = (0..app.items.len()).collect();
        app.fullscreen_idx = Some(0);

        app.handle_fs_navigation(
            &ctx,
            false,
            false,
            None,
            None,
            None,
            FsPageNav::Target(1),
            None,
            0,
        );
        assert_eq!(app.fullscreen_idx, Some(1));
        assert!(
            !app.fs_navigation_sequence_blocks_new_target(),
            "the still-to-video handler must not leave a Display sequence that native video \
             presentation cannot retire"
        );

        // The video handler resolves filesystem-backed candidates asynchronously. A virtual page
        // has no filesystem existence check, so it exercises that production branch without a
        // test fixture file and still lands through the normal fullscreen-open boundary.
        app.handle_fs_navigation(
            &ctx,
            false,
            false,
            None,
            None,
            None,
            FsPageNav::Target(2),
            None,
            1,
        );
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(1);
        while app.fullscreen_idx != Some(2) && std::time::Instant::now() < deadline {
            app.poll_video(&ctx);
            std::thread::yield_now();
        }
        assert_eq!(app.fullscreen_idx, Some(2));
        assert!(!app.fs_navigation_sequence_blocks_new_target());
        app.handle_fs_navigation(
            &ctx,
            false,
            false,
            None,
            None,
            None,
            FsPageNav::Target(3),
            None,
            2,
        );

        assert_eq!(app.fullscreen_idx, Some(3));
        let target = app
            .fs_holdover_tex
            .as_ref()
            .and_then(FsHoldover::navigation_sequence)
            .map(|sequence| sequence.target.clone());
        assert!(matches!(
            target,
            Some(FsNavigationSequenceTarget::Display(FsNavigationDisplayTarget {
                pages,
                ..
            })) if pages == vec![3]
        ));
    }

