    #[test]
    fn passthrough_thumbnail_preserves_its_aspect_inside_the_final_page_rectangle() {
        let viewport_rect = egui::Rect::from_min_size(egui::Pos2::ZERO, egui::vec2(1200.0, 800.0));
        let source_size = egui::vec2(1000.0, 1501.0);
        let make_input = |texture_size| DisplayedImageTransformInput {
            pixel_fit: RectPixelFit::Texels,
            page_idx: 0,
            viewport_rect,
            source_size,
            texture_size,
            rotation: crate::rotation_db::Rotation::None,
            free_rotation_rad: 0.0,
            content_bbox: None,
            fit_mode: FullscreenFitMode::Page,
            fit_scale_limits: FullscreenFitScaleLimits::default(),
            pixels_per_point: 1.0,
            placement: ResolvedDisplayPlacement::Normal { zoom_pan: None },
        };

        let pass =
            resolve_fs_image_transform(make_input(egui::vec2(300.0, 450.0)), Some(source_size))
                .expect("pass-through transform");
        let final_image =
            resolve_fs_image_transform(make_input(source_size), None).expect("final transform");
        // 差し替えでページが飛ばないこと。**内包では縛れない**: 最終ラスタは縮小なので
        // 描画矩形が物理ピクセル格子へ寄り、低解像度の下敷きは拡大側なので寄らない。
        // どちらが大きくなるかは倍率次第で、差は 1 物理ピクセル未満 (§1.0e)。
        // 中心は一致し続けなければならない — ここがずれると本当に飛んで見える。
        const HALF_PIXEL: f32 = 0.5;
        assert!(
            (pass.full_image_rect.center().x - final_image.full_image_rect.center().x).abs()
                <= HALF_PIXEL
        );
        assert!(
            (pass.full_image_rect.center().y - final_image.full_image_rect.center().y).abs()
                <= HALF_PIXEL
        );
        assert!(
            (pass.full_image_rect.width() - final_image.full_image_rect.width()).abs()
                <= 2.0 * HALF_PIXEL
        );
        assert!(
            (pass.full_image_rect.height() - final_image.full_image_rect.height()).abs()
                <= 2.0 * HALF_PIXEL
        );
        // **完全一致では縛れない** (§1.161): 貼り先はどの倍率でも整数テクセルへ寄るので、
        // 軸ごとの丸めで縦横比が最大 1 出力画素ぶん動く。捕まえたいのは「レイアウトの
        // 縦横比がテクスチャの倍率へ漏れる」退行で、そちらは 2 割規模で出る。
        let texture_ratio = 300.0 / 450.0;
        let paint_ratio = pass.full_image_rect.width() / pass.full_image_rect.height();
        let scale_x = pass.full_image_rect.width() / 300.0;
        let scale_y = pass.full_image_rect.height() / 450.0;
        assert!((paint_ratio - texture_ratio).abs() < 1.0 / 300.0);
        assert!((scale_x - scale_y).abs() < 1.0 / 300.0);
    }

    #[test]
    fn layout_source_and_texture_aspect_mismatch_keeps_texture_scale_uniform() {
        let viewport_rect = egui::Rect::from_min_size(egui::Pos2::ZERO, egui::vec2(1200.0, 800.0));
        // The reported transient ratio was about 409/512 while the page texture
        // itself was about 336/512. A layout frame may use either ratio, but the
        // raster's square pixels must never receive different X/Y scales.
        let texture_size = egui::vec2(336.0, 512.0);
        let layout_source_size = egui::vec2(409.0, 512.0);
        let transform = resolve_fs_image_transform(
            DisplayedImageTransformInput {
                pixel_fit: RectPixelFit::Texels,
                page_idx: 0,
                viewport_rect,
                source_size: texture_size,
                texture_size,
                rotation: crate::rotation_db::Rotation::None,
                free_rotation_rad: 0.0,
                content_bbox: None,
                fit_mode: FullscreenFitMode::Page,
                fit_scale_limits: FullscreenFitScaleLimits::default(),
                pixels_per_point: 1.0,
                placement: ResolvedDisplayPlacement::Normal { zoom_pan: None },
            },
            Some(layout_source_size),
        )
        .expect("mismatched layout/texture transform");

        let paint_ratio = transform.full_image_rect.width() / transform.full_image_rect.height();
        let texture_ratio = texture_size.x / texture_size.y;
        let scale_x = transform.full_image_rect.width() / texture_size.x;
        let scale_y = transform.full_image_rect.height() / texture_size.y;
        assert!((paint_ratio - texture_ratio).abs() < 1.0 / texture_size.x);
        assert!((scale_x - scale_y).abs() < 1.0 / texture_size.x);
        // 中心は viewport の中心から**最大 1 物理ピクセル**。原点を画素境界へ寄せるので
        // 完全一致にはならない (§1.0e / §1.161。ppp = 1 なので 1px = 1point)。
        assert!((transform.full_image_rect.center().x - viewport_rect.center().x).abs() <= 1.0);
        assert!((transform.full_image_rect.center().y - viewport_rect.center().y).abs() <= 1.0);
    }

    #[test]
    fn pdf_thumbnail_and_rounded_display_raster_use_the_same_page_box_rectangle() {
        let viewport_rect = egui::Rect::from_min_size(egui::Pos2::ZERO, egui::vec2(1200.0, 800.0));
        // Page-box aspect is retained in 1/1000 point units. Both the 327x473
        // thumbnail and 1643x2375 display raster round that ratio differently.
        let page_box_layout = egui::vec2(691_792.0, 1_000_000.0);
        let make_input = |source_size, texture_size| DisplayedImageTransformInput {
            pixel_fit: RectPixelFit::Texels,
            page_idx: 0,
            viewport_rect,
            source_size,
            texture_size,
            rotation: crate::rotation_db::Rotation::None,
            free_rotation_rad: 0.0,
            content_bbox: None,
            fit_mode: FullscreenFitMode::Page,
            fit_scale_limits: FullscreenFitScaleLimits::default(),
            pixels_per_point: 1.0,
            placement: ResolvedDisplayPlacement::Normal { zoom_pan: None },
        };
        let pass = resolve_fs_image_transform(
            make_input(egui::vec2(327.0, 473.0), egui::vec2(327.0, 473.0)),
            Some(page_box_layout),
        )
        .expect("PDF pass-through transform");
        let final_image = resolve_fs_image_transform(
            make_input(egui::vec2(1643.0, 2375.0), egui::vec2(1643.0, 2375.0)),
            Some(page_box_layout),
        )
        .expect("PDF final transform");

        // 差し替えでページが飛ばないこと。**完全一致では縛れない**: 最終ラスタは縮小
        // なので描画矩形が物理ピクセル格子へ寄る (§1.0e — 寄せないと Lanczos の出力を
        // もう一度バイリニアで貼り直すことになり、全面がボケる)。低解像度の下敷きは
        // 拡大側なので寄らない。ずれは 1 物理ピクセル未満で、目視できる段差ではない。
        // どちらの入力も pixels_per_point = 1.0 なので、1 物理ピクセル = 1 point。
        const HALF_PIXEL: f32 = 0.5;
        assert!(
            (pass.full_image_rect.center().x - final_image.full_image_rect.center().x).abs()
                <= HALF_PIXEL
        );
        assert!(
            (pass.full_image_rect.center().y - final_image.full_image_rect.center().y).abs()
                <= HALF_PIXEL
        );
        assert!(
            (pass.full_image_rect.width() - final_image.full_image_rect.width()).abs()
                <= 2.0 * HALF_PIXEL
        );
        assert!(
            (pass.full_image_rect.height() - final_image.full_image_rect.height()).abs()
                <= 2.0 * HALF_PIXEL
        );
        // 縦横比の許容は 1 出力画素ぶん (§1.161、上の pass-through テストと同じ理由)。
        let texture_ratio = 327.0 / 473.0;
        let paint_ratio = pass.full_image_rect.width() / pass.full_image_rect.height();
        let scale_x = pass.full_image_rect.width() / 327.0;
        let scale_y = pass.full_image_rect.height() / 473.0;
        assert!((paint_ratio - texture_ratio).abs() < 1.0 / 327.0);
        assert!((scale_x - scale_y).abs() < 1.0 / 327.0);
    }

