    #[test]
    fn fs_paint_dedup_compares_each_page_with_the_immediately_previous_display_unit() {
        let ctx = egui::Context::default();
        let texture_a = ctx
            .load_texture(
                "fs_paint_a",
                egui::ColorImage::filled([1, 1], egui::Color32::RED),
                egui::TextureOptions::LINEAR,
            )
            .id();
        let texture_b = ctx
            .load_texture(
                "fs_paint_b",
                egui::ColorImage::filled([1, 1], egui::Color32::BLUE),
                egui::TextureOptions::LINEAR,
            )
            .id();
        let geometry = FsPaintGeometrySignature {
            draw_rect: Some([52.0, 70.0, 158.0, 243.0]),
            scale_x: Some(0.5),
            scale_y: Some(0.5),
        };
        let previous = FsPaintDisplayUnitSignature {
            items_generation: 7,
            pages: vec![
                FsPaintPageSignature {
                    idx: 2,
                    texture_id: texture_a,
                    geometry,
                },
                FsPaintPageSignature {
                    idx: 3,
                    texture_id: texture_b,
                    geometry,
                },
            ],
        };

        assert!(!fs_paint_page_changed_from_previous(
            Some(&previous),
            7,
            FsPaintPageSignature {
                idx: 3,
                texture_id: texture_b,
                geometry,
            },
        ));
        assert!(fs_paint_page_changed_from_previous(
            Some(&previous),
            7,
            FsPaintPageSignature {
                idx: 4,
                texture_id: texture_a,
                geometry,
            },
        ));
        assert!(fs_paint_page_changed_from_previous(
            Some(&previous),
            7,
            FsPaintPageSignature {
                idx: 2,
                texture_id: texture_b,
                geometry,
            },
        ));
        assert!(fs_paint_page_changed_from_previous(
            Some(&previous),
            8,
            FsPaintPageSignature {
                idx: 2,
                texture_id: texture_a,
                geometry,
            },
        ));
        assert!(fs_paint_page_changed_from_previous(
            Some(&previous),
            7,
            FsPaintPageSignature {
                idx: 2,
                texture_id: texture_a,
                geometry: FsPaintGeometrySignature {
                    draw_rect: Some([34.0, 70.0, 194.0, 243.0]),
                    scale_x: Some(0.6127),
                    scale_y: Some(0.5),
                },
            },
        ));
        assert!(!fs_paint_page_changed_from_previous(
            Some(&previous),
            7,
            FsPaintPageSignature {
                idx: 2,
                texture_id: texture_a,
                geometry: FsPaintGeometrySignature {
                    draw_rect: Some([52.1, 69.9, 158.1, 242.9]),
                    scale_x: Some(0.5005),
                    scale_y: Some(0.4995),
                },
            },
        ));
    }

