    #[test]
    fn music_view_interactive_ui_blocks_cursor_auto_hide() {
        use crate::settings::FsSidePanelMode;
        use crate::ui_helpers::MetadataPanelOpenState::{ByPointer, Closed};

        let idle = MusicViewFrameUiState::from_panel_inputs(
            FsSidePanelMode::Hover,
            false,
            false,
            Closed,
            Closed,
            false,
            false,
        );
        assert!(!idle.blocks_cursor_auto_hide());

        let hover_left = MusicViewFrameUiState::from_panel_inputs(
            FsSidePanelMode::Hover,
            true,
            false,
            Closed,
            Closed,
            false,
            false,
        );
        assert!(hover_left.left_panel_visible);
        assert!(hover_left.blocks_cursor_auto_hide());

        let click_right = MusicViewFrameUiState::from_panel_inputs(
            FsSidePanelMode::ClickToShow,
            false,
            false,
            Closed,
            ByPointer,
            false,
            false,
        );
        assert!(click_right.right_panel_visible);
        assert!(click_right.blocks_cursor_auto_hide());

        let modal = MusicViewFrameUiState::from_panel_inputs(
            FsSidePanelMode::Hover,
            true,
            true,
            Closed,
            Closed,
            true,
            false,
        );
        assert!(!modal.left_panel_visible);
        assert!(!modal.right_panel_visible);
        assert!(modal.blocks_cursor_auto_hide());
    }

    #[test]
    fn music_side_panel_hit_test_respects_left_and_right_visibility() {
        let viewport = egui::Rect::from_min_size(egui::Pos2::ZERO, egui::vec2(1920.0, 1080.0));
        let left = egui::pos2(120.0, 300.0);
        let right = egui::pos2(1700.0, 300.0);

        assert!(!music_side_panel_contains_pointer(
            viewport, left, false, false
        ));
        assert!(music_side_panel_contains_pointer(
            viewport, left, true, false
        ));
        assert!(!music_side_panel_contains_pointer(
            viewport, left, false, true
        ));
        assert!(music_side_panel_contains_pointer(
            viewport, right, false, true
        ));
        assert!(!music_side_panel_contains_pointer(
            viewport, right, true, false
        ));
    }

    #[test]
    fn music_side_panel_hit_test_is_limited_to_the_drawn_vertical_band() {
        let viewport =
            egui::Rect::from_min_size(egui::pos2(100.0, 200.0), egui::vec2(1920.0, 1080.0));
        let x = viewport.left() + 100.0;
        let band_top = viewport.top() + MUSIC_TOP_BAR_HEIGHT;
        let band_bottom = viewport.bottom() - crate::ui_music_panels::MUSIC_HUD_HEIGHT;

        assert!(!music_side_panel_contains_pointer(
            viewport,
            egui::pos2(x, band_top - 0.1),
            true,
            false,
        ));
        assert!(music_side_panel_contains_pointer(
            viewport,
            egui::pos2(x, band_top),
            true,
            false,
        ));
        assert!(music_side_panel_contains_pointer(
            viewport,
            egui::pos2(x, band_bottom),
            true,
            false,
        ));
        assert!(!music_side_panel_contains_pointer(
            viewport,
            egui::pos2(x, band_bottom + 0.1),
            true,
            false,
        ));
    }

    #[test]
    fn music_right_panel_hit_test_clamps_width_to_half_the_viewport() {
        let viewport = egui::Rect::from_min_size(egui::Pos2::ZERO, egui::vec2(600.0, 500.0));
        let panel_left = viewport.right() - viewport.width() * 0.5;
        let y = viewport.top() + MUSIC_TOP_BAR_HEIGHT + 10.0;

        assert!(!music_side_panel_contains_pointer(
            viewport,
            egui::pos2(panel_left - 0.1, y),
            false,
            true,
        ));
        assert!(music_side_panel_contains_pointer(
            viewport,
            egui::pos2(panel_left, y),
            false,
            true,
        ));
    }

    // テスト用ラッパ: コンテンツ領域 = 画像全体 (トリムなし) で zoom helper を呼ぶ。
    fn tz_pan(
        view: egui::Vec2,
        image: egui::Vec2,
        factor: f32,
        cursor: egui::Vec2,
    ) -> (f32, egui::Vec2) {
        zip_cover_zoom_pan(view, image, egui::Vec2::ZERO, image, factor, cursor)
    }
    fn tz_basis(view: egui::Rect, band: egui::Rect, image: egui::Vec2) -> ZAimBasis {
        let content_fit = (view.width() / image.x).min(view.height() / image.y);
        ZAimBasis::resolve(view, band, image, content_fit)
    }
    fn tz_aim(basis: &ZAimBasis, image: egui::Vec2, factor: f32, cursor: egui::Vec2) -> egui::Rect {
        zip_aim_frame_rect(basis, egui::Vec2::ZERO, image, factor, cursor)
    }
    fn tz_cursor(basis: &ZAimBasis, image: egui::Vec2, cursor: egui::Pos2) -> egui::Vec2 {
        z_cursor_image_px(basis, egui::Vec2::ZERO, image, cursor)
    }

    // ファイル名スタックのフラット読書中に Shift+↓↑ が「スタックジャンプ」ではなく通常ページ
    // 送りになる v2.2.0 回帰 (646e7709 でスタックジャンプを egui `consume_key` → keymap の
    // Win32 KeySlot キュー経路へ移したことが発端) の再発防止テスト。
    //
    // 根本原因は egui の `consume_key(NONE, key)` が `matches_logically` を使い「余分な Shift」を
    // 無視する契約にある: plain ↓ のつもりの consume が Shift+↓ イベントも飲み込む。スタック
    // ジャンプは別キュー (Win32) で consume するため egui 側に残った Shift+↓ を plain ページ送りが
    // 拾って二重発火していた。ui_fullscreen 側は `stack_shift_arrow` (OS 直読み Shift) で除外して
    // いる。将来 egui 更新でこの契約が変わったら (= 下の assert が false になったら) 除外ロジックを
    // 見直せるよう、依存している egui 挙動をここで固定する。
    #[test]
    fn egui_plain_arrow_consume_swallows_shift_modified_event() {
        let mut input = egui::InputState::default();
        input.events.push(egui::Event::Key {
            key: egui::Key::ArrowDown,
            physical_key: None,
            pressed: true,
            repeat: false,
            modifiers: egui::Modifiers::SHIFT,
        });
        // plain ↓ (NONE) の consume が Shift+↓ イベントを飲み込む = 二重発火の温床。
        assert!(
            input.consume_key(egui::Modifiers::NONE, egui::Key::ArrowDown),
            "egui consume_key(NONE) が Shift+↓ を拾わなくなったら stack_shift_arrow 除外を再検討する"
        );
    }

    #[test]
    fn video_display_texture_never_falls_back_to_poster_thumbnail() {
        // 動画は native presenter が実フレームを描くので、egui 側はサムネ (ポスターフレーム) を
        // 表示物に使わない。ライブ再生位置とズレた別フレームが違う拡大率で一瞬出るチラつきを
        // 防ぐ (実機 2026-07-01 の F12 切替で F250 が黒余白を溢れて見えた回帰の固定)。静止画は
        // progressive load で thumb にフォールバックする。
        let ctx = egui::Context::default();
        let mk = |name: &str| {
            let ci = egui::ColorImage::from_rgba_unmultiplied([2, 2], &[255u8; 16]);
            ctx.load_texture(name, ci, egui::TextureOptions::LINEAR)
        };
        let full = mk("full");
        let thumb = mk("thumb");

        // 動画: フル tex があればそれ、無ければ None (サムネにフォールバックしない)。
        assert!(App::fs_display_texture_choice(true, None, Some(&thumb)).is_none());
        assert_eq!(
            App::fs_display_texture_choice(true, Some(&full), Some(&thumb)).map(|t| t.id()),
            Some(full.id()),
            "動画でフル tex があればそれを使う"
        );
        assert!(App::fs_display_texture_choice(true, None, None).is_none());

        // 静止画: フル tex 優先、無ければ thumb にフォールバック。
        assert_eq!(
            App::fs_display_texture_choice(false, None, Some(&thumb)).map(|t| t.id()),
            Some(thumb.id()),
            "静止画はサムネにフォールバックする (progressive load)"
        );
        assert_eq!(
            App::fs_display_texture_choice(false, Some(&full), Some(&thumb)).map(|t| t.id()),
            Some(full.id())
        );
        assert!(App::fs_display_texture_choice(false, None, None).is_none());
    }

    #[test]
    #[cfg(windows)]
    fn parked_live_music_layout_uses_spectrum_without_timeline_or_waveform() {
        let rect = egui::Rect::from_min_size(egui::Pos2::ZERO, egui::vec2(1280.0, 720.0));
        let edge_trigger = 64.0;
        let layout = App::parked_live_music_window_layout(rect, edge_trigger)
            .expect("normal parked music window should have a layout");

        assert!(
            !layout.draw_timeline,
            "ParkedLive music windows must not draw the active timeline"
        );
        assert!(
            !layout.draw_waveform_fallback,
            "ParkedLive music windows must not fall back to the static waveform"
        );
        assert!(
            layout.show_spectrum,
            "ParkedLive music windows should keep the lower spectrum alive"
        );
        assert_eq!(layout.top_rect.height(), PARKED_LIVE_MUSIC_TOP_H);
        assert!(layout.central_rect.bottom() <= layout.spectrum_rect.top());
        let content_gutter = (edge_trigger + rect.width() * 0.03).max(8.0);
        let band_top = rect.top() + PARKED_LIVE_MUSIC_TOP_H;
        let band_bottom = rect.bottom() - crate::ui_music_panels::MUSIC_HUD_HEIGHT - 4.0;
        let spectrum_h = PARKED_LIVE_MUSIC_SPECTRUM_MAX_H.min(
            (band_bottom
                - band_top
                - PARKED_LIVE_MUSIC_SPECTRUM_GAP
                - PARKED_LIVE_MUSIC_TIMELINE_MIN_H)
                .max(0.0),
        );
        let expected = egui::Rect::from_min_max(
            egui::pos2(rect.left() + content_gutter, band_bottom - spectrum_h),
            egui::pos2(rect.right() - content_gutter, band_bottom),
        );
        assert_eq!(
            layout.spectrum_rect, expected,
            "ParkedLive spectrum rect must match the active music-view band formula"
        );
    }

