    /// リモートへ返す分割の表示単位。**同じ index の group が 2 つ並ぶ。**
    ///
    /// 端末側はこれを `(anchor, slice)` の組で照合する。index だけで解決すると
    /// 必ず先頭へ吸われる (本体側で 2 回踏んだのと同じ形)。
    #[test]
    fn a_landscape_page_becomes_two_remote_groups() {
        use crate::page_split::PageSlice;

        let items = (0..3)
            .map(|k| GridItem::Image(std::path::PathBuf::from(format!("p{k}.jpg"))))
            .collect::<Vec<_>>();
        let mut landscape = vec![false; items.len()];
        landscape[1] = true;

        let groups = build_remote_spread_page_groups(&items, SpreadMode::SplitLtr, &landscape);
        assert_eq!(
            groups
                .iter()
                .map(|group| (group.indices.clone(), group.slice))
                .collect::<Vec<_>>(),
            vec![
                (vec![0], PageSlice::Full),
                (vec![1], PageSlice::Left),
                (vec![1], PageSlice::Right),
                (vec![2], PageSlice::Full),
            ]
        );

        // 右→左では左右の順序だけが変わる。元ページの順序は変わらない。
        let rtl = build_remote_spread_page_groups(&items, SpreadMode::SplitRtl, &landscape);
        assert_eq!(
            rtl.iter().map(|group| group.slice).collect::<Vec<_>>(),
            vec![
                PageSlice::Full,
                PageSlice::Right,
                PageSlice::Left,
                PageSlice::Full
            ]
        );
        assert_eq!(
            rtl.iter()
                .map(|group| group.indices.clone())
                .collect::<Vec<_>>(),
            groups
                .iter()
                .map(|group| group.indices.clone())
                .collect::<Vec<_>>()
        );

        // 分割は見開きではない。1 group に 2 ページを入れない。
        assert!(groups.iter().all(|group| group.indices.len() == 1));
    }

    /// リモート group の index だけを取り出す。左右は分割モードの専用テストで確かめる。
    fn remote_group_indices(
        items: &[GridItem],
        spread_mode: SpreadMode,
        landscape: &[bool],
    ) -> Vec<Vec<usize>> {
        build_remote_spread_page_groups(items, spread_mode, landscape)
            .into_iter()
            .map(|group| group.indices)
            .collect()
    }

    fn spread_unit_summary(units: &[SpreadDisplayUnit]) -> Vec<(usize, Vec<usize>)> {
        units
            .iter()
            .map(|unit| (unit.nav_start, unit.pages.clone()))
            .collect()
    }

    fn assert_spread_seek_units_cover_nav_and_endpoints(
        nav: &[usize],
        units: &[SpreadDisplayUnit],
    ) {
        assert!(!units.is_empty());
        assert_eq!(
            units
                .iter()
                .flat_map(|unit| unit.pages.iter().copied())
                .collect::<Vec<_>>(),
            nav.to_vec()
        );
        assert_eq!(
            units.first().map(SpreadDisplayUnit::anchor_idx),
            nav.first().copied()
        );
        assert_eq!(
            units.last().map(SpreadDisplayUnit::anchor_idx),
            nav.last().copied()
        );
        assert!(
            nav.iter()
                .all(|idx| find_spread_display_unit(units, *idx).is_some())
        );
        assert_eq!(spread_seek_unit_fraction(0, units.len()), 0.0);
        assert_eq!(spread_seek_unit_fraction(units.len() - 1, units.len()), 1.0);
    }

    fn spread_landscape_flags(
        nav: &[usize],
        mut is_landscape_idx: impl FnMut(usize) -> bool,
    ) -> Vec<bool> {
        nav.iter()
            .copied()
            .map(|idx| is_landscape_idx(idx))
            .collect()
    }

    fn spread_unit_summary_1based(units: &[SpreadDisplayUnit]) -> Vec<Vec<usize>> {
        units
            .iter()
            .map(|unit| unit.pages.iter().map(|idx| idx + 1).collect())
            .collect()
    }

    fn shifted_spread_units_1based(
        page_count: usize,
        spread_mode: SpreadMode,
        landscape_pages_1based: &[usize],
        fs_page_1based: usize,
    ) -> (usize, usize, Vec<Vec<usize>>) {
        let nav = (0..page_count).collect::<Vec<_>>();
        let is_landscape_idx =
            |idx: usize| landscape_pages_1based.iter().any(|page| *page == idx + 1);
        let units =
            build_spread_display_units_with_landscape(&nav, spread_mode, None, is_landscape_idx);
        let landscape_flags = spread_landscape_flags(&nav, |idx| {
            landscape_pages_1based.iter().any(|page| *page == idx + 1)
        });
        let (new_idx, anchor_idx) =
            spread_offset_nudge_from_units(&nav, &units, fs_page_1based - 1, 1, &landscape_flags)
                .expect("shift target is in range");
        let shifted_units =
            build_spread_display_units_with_landscape(&nav, spread_mode, Some(anchor_idx), |idx| {
                landscape_pages_1based.iter().any(|page| *page == idx + 1)
            });
        (
            new_idx + 1,
            anchor_idx + 1,
            spread_unit_summary_1based(&shifted_units),
        )
    }

