    #[test]
    fn fixed_bar_gap_is_subtracted_only_at_locked_edges() {
        let full = egui::Rect::from_min_size(egui::Pos2::ZERO, egui::vec2(1200.0, 800.0));
        let both = fullscreen_rect_excluding_fixed_bars(full, true, true, 24, 0.0);
        assert_eq!(both.top(), TOP_BAR_HEIGHT + 24.0);
        assert_eq!(both.bottom(), 800.0 - FS_SEEK_BAR_HEIGHT - 24.0);

        let hover_bars = fullscreen_rect_excluding_fixed_bars(full, false, false, 24, 0.0);
        assert_eq!(hover_bars, full);

        let panel = fullscreen_seek_panel_rect(full);
        assert_eq!(fullscreen_seek_separator_y(panel, false), panel.top());
        assert_eq!(fullscreen_seek_separator_y(panel, true), panel.top() + 0.5);
    }

    /// 上下どちらの固定バーも、区切り線が画像側へはみ出さないこと。
    /// 上部だけ直して下部を忘れる (逆も) 退行を 1 本で塞ぐ。
    #[test]
    fn locked_bar_separators_stay_inside_both_bars() {
        let full = egui::Rect::from_min_size(egui::Pos2::ZERO, egui::vec2(1200.0, 800.0));
        let top_bar = fullscreen_top_bar_rect(full);
        let seek_panel = fullscreen_seek_panel_rect(full);
        let media = fullscreen_rect_excluding_fixed_bars(full, true, true, 0, 0.0);
        const HALF_STROKE: f32 = 0.5;

        let top_y = fullscreen_top_bar_separator_y(top_bar, true);
        assert!(
            top_y + HALF_STROKE <= media.top(),
            "top separator must not paint onto the image: {top_y} vs {}",
            media.top()
        );
        assert!(top_y - HALF_STROKE >= top_bar.top());

        let seek_y = fullscreen_seek_separator_y(seek_panel, true);
        assert!(
            seek_y - HALF_STROKE >= media.bottom(),
            "seek separator must not paint onto the image: {seek_y} vs {}",
            media.bottom()
        );
        assert!(seek_y + HALF_STROKE <= seek_panel.bottom());
    }

    #[test]
    fn seek_pointer_and_knob_share_the_same_effective_direction() {
        let track = egui::Rect::from_min_max(egui::pos2(100.0, 0.0), egui::pos2(500.0, 8.0));
        for rtl in [false, true] {
            for pointer_x in [100.0, 220.0, 500.0] {
                let fraction = fullscreen_seek_fraction_from_x(track, pointer_x, rtl);
                let knob_x = fullscreen_seek_knob_x(track, fraction, rtl);
                assert!((knob_x - pointer_x).abs() < 0.001);
            }
        }
        assert_eq!(fullscreen_seek_fraction_from_x(track, 100.0, false), 0.0);
        assert_eq!(fullscreen_seek_fraction_from_x(track, 100.0, true), 1.0);
    }

    #[test]
    fn seek_ruler_rtl_positions_are_ltr_mirror_images() {
        let track = egui::Rect::from_min_max(egui::pos2(100.0, 0.0), egui::pos2(500.0, 8.0));
        let ticks = crate::seek_ruler::page_ruler_ticks(
            100,
            track.width(),
            crate::seek_ruler::SEEK_RULER_MIN_SPACING,
        );

        assert!(!ticks.is_empty());
        for tick in ticks {
            let ltr_x = fullscreen_seek_knob_x(track, tick.fraction, false);
            let rtl_x = fullscreen_seek_knob_x(track, tick.fraction, true);
            assert!((ltr_x + rtl_x - track.left() - track.right()).abs() < 0.001);
        }
    }

    #[test]
    fn compare_wipe_reference_rect_is_letterbox_fitted_not_full_rect() {
        // 横長ウィンドウ + 縦長画像 → 左右に黒帯。比較 Wipe の白線 / clip / ドラッグ /
        // シェーダー合成境界は、この「フィット後の実表示画像矩形」を基準にしなければ
        // ならない。full_rect (黒帯込み) と混在させると、同じ fraction でも線の位置と
        // 切り替わり位置がズレる (本バグの本質)。
        let full = egui::Rect::from_min_size(egui::pos2(0.0, 0.0), egui::vec2(1000.0, 800.0));
        let fitted = App::compare_image_draw_rect(
            full,
            [400, 800],
            None,
            FullscreenFitScaleLimits::default(),
        )
        .unwrap();
        // 高さフィット (800/800=1.0)、幅 400 → 中央寄せで左右に黒帯。
        assert!((fitted.height() - 800.0).abs() < 0.5);
        assert!((fitted.width() - 400.0).abs() < 0.5);
        assert!(fitted.width() < full.width()); // = full_rect とは別物
        assert!((fitted.center().x - full.center().x).abs() < 0.5); // 中央寄せ
        // 同一 fraction でも基準が違えば線の x がズレる。
        let f = 0.25_f32;
        let x_fitted = compare_wipe_screen_x(fitted, f);
        let x_full = compare_wipe_screen_x(full, f);
        assert!((x_fitted - x_full).abs() > 100.0);
    }

    #[test]
    fn compare_wipe_fraction_and_screen_x_round_trip_for_fit_zoom_and_letterbox() {
        let viewport = egui::Rect::from_min_size(egui::pos2(20.0, 30.0), egui::vec2(1000.0, 800.0));
        let fit = App::compare_image_draw_rect(
            viewport,
            [1000, 800],
            None,
            FullscreenFitScaleLimits::default(),
        )
        .unwrap();
        let zoomed = App::compare_image_draw_rect(
            viewport,
            [1000, 800],
            Some((2.0, egui::vec2(73.0, -41.0))),
            FullscreenFitScaleLimits::default(),
        )
        .unwrap();
        let letterboxed = App::compare_image_draw_rect(
            viewport,
            [400, 800],
            None,
            FullscreenFitScaleLimits::default(),
        )
        .unwrap();

        let fraction = 0.37;
        for draw_rect in [fit, zoomed, letterboxed] {
            let line_x = compare_wipe_screen_x(draw_rect, fraction);
            let grabbed_fraction =
                compare_wipe_fraction_from_screen_x(draw_rect, viewport, line_x).unwrap();
            assert!((grabbed_fraction - fraction).abs() < 1.0e-6);
            assert!(compare_wipe_grab_hit(
                draw_rect,
                egui::pos2(line_x, draw_rect.center().y),
                fraction,
            ));
        }
    }

    #[test]
    fn compare_wipe_line_uses_drag_or_grab_band_and_ctrl_only_suppresses_drag() {
        let image = egui::Rect::from_min_max(egui::pos2(100.0, 50.0), egui::pos2(900.0, 750.0));
        let fraction = 0.25;
        let line_x = compare_wipe_screen_x(image, fraction);
        let line_pos = Some(egui::pos2(line_x, image.center().y));

        assert!(!compare_wipe_line_visible(
            image, None, fraction, false, false
        ));
        assert!(compare_wipe_line_visible(
            image, line_pos, fraction, false, false
        ));
        assert!(compare_wipe_line_visible(
            image, line_pos, fraction, false, true
        ));
        assert!(!compare_wipe_line_visible(
            image,
            Some(egui::pos2(image.right() - 1.0, image.center().y)),
            fraction,
            false,
            false
        ));
        assert!(compare_wipe_line_visible(
            image, None, fraction, true, false
        ));
        assert!(!compare_wipe_line_visible(
            image, line_pos, fraction, true, true
        ));
    }

