    #[test]
    fn vertical_reading_texel_hysteresis_starts_above_high_and_trims_to_low() {
        let watermarks = crate::vram_budget::VramWatermarks {
            high_texels: Some(320_000_000),
            low_texels: Some(240_000_000),
        };
        assert_eq!(
            vertical_reading_texel_trim_plan(320_000_000, [usize::MAX], watermarks),
            (0, 320_000_000)
        );

        let page_texels = 30_000_000;
        let (remove_count, remaining) = vertical_reading_texel_trim_plan(
            320_000_001,
            [page_texels, page_texels, page_texels],
            watermarks,
        );
        assert_eq!(remove_count, 3);
        assert!(320_000_001 - page_texels * 2 > 240_000_000);
        assert!(remaining <= 240_000_000);
    }

    #[test]
    fn vertical_reading_texel_trim_is_disabled_for_unlimited_pool() {
        let watermarks = crate::vram_budget::VramWatermarks {
            high_texels: None,
            low_texels: None,
        };

        assert_eq!(
            vertical_reading_texel_trim_plan(usize::MAX, [usize::MAX, usize::MAX], watermarks,),
            (0, usize::MAX)
        );
    }

    #[test]
    fn vertical_reading_texel_estimate_includes_edit_intermediate_textures() {
        let ctx = egui::Context::default();
        let mut app = crate::app::setup_app_for_test();
        let idx = 7;
        let make_texture = |name: &str| {
            let image = egui::ColorImage::new([4, 4], vec![egui::Color32::BLACK; 16]);
            (
                Arc::new(image.clone()),
                ctx.load_texture(name, image, egui::TextureOptions::LINEAR),
            )
        };

        let erase_key = app.current_erase_result_key(idx);
        let (pixels, texture) = make_texture("estimate_erase");
        app.erase_result_cache.insert(
            erase_key,
            crate::app::EraseResultCacheEntry { pixels, texture },
        );

        let local_key = app.current_local_adjust_key(idx);
        let (pixels, texture) = make_texture("estimate_local");
        app.local_adjust_cache.insert(
            local_key,
            crate::app::LocalAdjustCacheEntry { pixels, texture },
        );

        let bypass_key = crate::app::LocalAdjustLayerBypassPreviewKey {
            result_key: local_key,
            layer_idx: 0,
        };
        let (pixels, texture) = make_texture("estimate_bypass");
        app.local_adjust_layer_bypass_cache.insert(
            bypass_key,
            crate::app::LocalAdjustCacheEntry { pixels, texture },
        );

        let prefix_key = crate::app::LocalAdjustPrefixPreviewKey {
            result_key: local_key,
            layer_count: 1,
        };
        let (pixels, texture) = make_texture("estimate_prefix");
        app.local_adjust_prefix_preview_cache.insert(
            prefix_key,
            crate::app::LocalAdjustCacheEntry { pixels, texture },
        );

        let (pixels, texture) = make_texture("estimate_conceal");
        let conceal_generation = app.conceal_generation;
        app.conceal_cache.insert(
            idx,
            crate::app::ConcealCacheEntry {
                pixels,
                texture,
                generation: conceal_generation,
            },
        );

        // 4x4 の完全chainは 16+4+1=21 texel。独立した5 textureをすべて数える。
        assert_eq!(
            app.vertical_reading_keep_set_loaded_texels(&std::collections::HashSet::from([idx])),
            5 * 21
        );
    }

